--
-- Name: admin_metrics; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.admin_metrics AS
 SELECT ( SELECT count(*) AS count
           FROM public.user_profiles) AS customers,
    ( SELECT count(*) AS count
           FROM public.orders) AS orders,
    ( SELECT COALESCE(sum(orders.total_cents), (0)::bigint) AS "coalesce"
           FROM public.orders
          WHERE (orders.payment_status = ANY (ARRAY['paid'::text, 'paid_credit'::text]))) AS revenue_cents,
    ( SELECT count(*) AS count
           FROM public.support_tickets
          WHERE (support_tickets.status <> 'closed'::text)) AS open_tickets,
    ( SELECT count(*) AS count
           FROM public.products
          WHERE (products.active = true)) AS active_products,
    ( SELECT count(*) AS count
           FROM public.license_fulfillments
          WHERE (license_fulfillments.state = 'pending'::text)) AS pending_licenses;


