COPY public.__orbitfs_export_dump (id, sql_text) FROM stdin;
t	-- OrbitFS Billing + Master License Database export\\n-- Generated from live OrbitFS Website Supabase database\\n-- Schema: all public tables/functions/triggers/indexes/RLS; data: core/default configuration only\\n\\nBEGIN;\\n\\nCREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;\\nCREATE SCHEMA IF NOT EXISTS app_private;\\n\\nCREATE TABLE public.account_activity (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  auth_user_id uuid NOT NULL,\n  event_type text NOT NULL,\n  ip_address inet,\n  user_agent text,\n  detail jsonb DEFAULT '{}'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  source text,\n  route text,\n  entity_type text,\n  entity_id text,\n  success boolean DEFAULT true NOT NULL,\n  request_id text,\n  session_ref text\n);\n\nCREATE TABLE public.account_balances (\n  user_id uuid NOT NULL,\n  available_cents bigint DEFAULT 0 NOT NULL,\n  reserved_cents bigint DEFAULT 0 NOT NULL,\n  lifetime_credit_cents bigint DEFAULT 0 NOT NULL,\n  lifetime_debit_cents bigint DEFAULT 0 NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.admin_audit_log (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  actor_id uuid,\n  actor_email text,\n  action text NOT NULL,\n  target_type text,\n  target_id text,\n  detail jsonb DEFAULT '{}'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.app_settings (\n  key text NOT NULL,\n  value jsonb NOT NULL,\n  category text DEFAULT 'general'::text NOT NULL,\n  public_read boolean DEFAULT false NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.coupon_redemptions (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  coupon_id uuid NOT NULL,\n  invoice_id uuid,\n  auth_user_id uuid,\n  discount_cents bigint DEFAULT 0 NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  credit_cents bigint DEFAULT 0 NOT NULL\n);\n\nCREATE TABLE public.coupons (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  code text NOT NULL,\n  description text,\n  discount_type text NOT NULL,\n  discount_value bigint NOT NULL,\n  active boolean DEFAULT true NOT NULL,\n  starts_at timestamp with time zone,\n  ends_at timestamp with time zone,\n  max_redemptions integer,\n  per_user_limit integer DEFAULT 1 NOT NULL,\n  min_order_cents bigint DEFAULT 0 NOT NULL,\n  product_ids uuid[] DEFAULT '{}'::uuid[] NOT NULL,\n  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.credit_ledger (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  user_id uuid NOT NULL,\n  direction text NOT NULL,\n  amount_cents bigint NOT NULL,\n  balance_after_cents bigint NOT NULL,\n  reason text NOT NULL,\n  reference_type text,\n  reference_id text,\n  created_by uuid,\n  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.custom_field_definitions (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  scope text NOT NULL,\n  key text NOT NULL,\n  label text NOT NULL,\n  field_type text DEFAULT 'text'::text NOT NULL,\n  options jsonb DEFAULT '[]'::jsonb NOT NULL,\n  required boolean DEFAULT false NOT NULL,\n  admin_only boolean DEFAULT false NOT NULL,\n  enabled boolean DEFAULT true NOT NULL,\n  sort_order integer DEFAULT 100 NOT NULL\n);\n\nCREATE TABLE public.custom_field_values (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  definition_id uuid NOT NULL,\n  owner_id text NOT NULL,\n  value jsonb,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.customer_credentials (\n  user_id uuid NOT NULL,\n  password_hash text NOT NULL,\n  password_changed_at timestamp with time zone DEFAULT now() NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.customer_sessions (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  user_id uuid NOT NULL,\n  token_hash text NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  last_seen_at timestamp with time zone DEFAULT now() NOT NULL,\n  expires_at timestamp with time zone NOT NULL,\n  revoked_at timestamp with time zone,\n  ip_address inet,\n  user_agent text\n);\n\nCREATE TABLE public.customers (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  auth_user_id uuid,\n  email text NOT NULL,\n  name text,\n  license_user_id text,\n  status text DEFAULT 'active'::text NOT NULL,\n  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\n  customer_number text,\n  username text,\n  email_verified_at timestamp with time zone,\n  display_name text,\n  first_name text,\n  last_name text,\n  company_name text,\n  phone text,\n  address_line1 text,\n  address_line2 text,\n  city text,\n  state_region text,\n  postal_code text,\n  country_code text,\n  timezone text,\n  currency text,\n  language text\n);\n\nCREATE TABLE public.download_entitlements (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  auth_user_id uuid NOT NULL,\n  order_id uuid,\n  order_item_id uuid,\n  product_id uuid,\n  status text DEFAULT 'active'::text NOT NULL,\n  granted_at timestamp with time zone DEFAULT now() NOT NULL,\n  revoked_at timestamp with time zone,\n  reason text,\n  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,\n  source_order_status text\n);\n\nCREATE TABLE public.email_verification_tokens (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  user_id uuid NOT NULL,\n  token_hash text NOT NULL,\n  expires_at timestamp with time zone NOT NULL,\n  used_at timestamp with time zone,\n  request_ip inet,\n  created_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.enforcement_settings (\n  id boolean DEFAULT true NOT NULL,\n  integration_enabled boolean DEFAULT false NOT NULL,\n  auto_suspend_overdue boolean DEFAULT true NOT NULL,\n  overdue_grace_days integer DEFAULT 0 NOT NULL,\n  auto_restore_paid boolean DEFAULT true NOT NULL,\n  ban_blocks_licenses boolean DEFAULT true NOT NULL,\n  suspension_blocks_licenses boolean DEFAULT true NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.gift_deliveries (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  source_order_id uuid NOT NULL,\n  source_order_item_id uuid NOT NULL,\n  purchaser_user_id uuid NOT NULL,\n  recipient_email text NOT NULL,\n  recipient_user_id uuid,\n  recipient_order_id uuid,\n  status text DEFAULT 'pending'::text NOT NULL,\n  account_created boolean DEFAULT false NOT NULL,\n  error text,\n  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  delivered_at timestamp with time zone,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.guest_support_access_attempts (\n  id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,\n  request_ip text NOT NULL,\n  attempted_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.invoice_items (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  invoice_id uuid NOT NULL,\n  order_item_id uuid,\n  description text NOT NULL,\n  quantity integer DEFAULT 1 NOT NULL,\n  unit_price_cents bigint DEFAULT 0 NOT NULL,\n  total_cents bigint DEFAULT 0 NOT NULL,\n  metadata jsonb DEFAULT '{}'::jsonb NOT NULL\n);\n\nCREATE TABLE public.invoice_payments (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  invoice_id uuid NOT NULL,\n  auth_user_id uuid,\n  method text NOT NULL,\n  amount_cents bigint NOT NULL,\n  status text DEFAULT 'completed'::text NOT NULL,\n  external_reference text,\n  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() 