tatus text DEFAULT 'stored'::text NOT NULL,\n  is_read boolean DEFAULT false NOT NULL,\n  sent_at timestamp with time zone,\n  received_at timestamp with time zone,\n  created_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.mail_settings (\n  key text NOT NULL,\n  value jsonb DEFAULT '{}'::jsonb NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.mail_spam_events (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  provider_id text,\n  mailbox_address text NOT NULL,\n  sender_email text,\n  sender_domain text,\n  sender_ip inet,\n  decision text NOT NULL,\n  score integer DEFAULT 0 NOT NULL,\n  reasons jsonb DEFAULT '[]'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.mail_spam_rules (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  scope text DEFAULT 'global'::text NOT NULL,\n  mailbox_address text,\n  rule_type text NOT NULL,\n  value text NOT NULL,\n  action text DEFAULT 'block'::text NOT NULL,\n  reason text,\n  active boolean DEFAULT true NOT NULL,\n  created_by uuid,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.mail_templates (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  template_key text NOT NULL,\n  name text NOT NULL,\n  category text NOT NULL,\n  subject text NOT NULL,\n  html text,\n  text_body text,\n  from_account text DEFAULT 'noreply@orbitfs.cc'::text NOT NULL,\n  enabled boolean DEFAULT true NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.news_posts (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  slug text NOT NULL,\n  title text NOT NULL,\n  excerpt text,\n  body text,\n  category text DEFAULT 'general'::text NOT NULL,\n  published boolean DEFAULT false NOT NULL,\n  pinned boolean DEFAULT 