'::text NOT NULL,\n  compact_mode boolean DEFAULT false NOT NULL,\n  email_news boolean DEFAULT true NOT NULL,\n  email_support boolean DEFAULT true NOT NULL,\n  email_orders boolean DEFAULT true NOT NULL,\n  locale text DEFAULT 'en-AU'::text NOT NULL,\n  dashboard_layout jsonb DEFAULT '{}'::jsonb NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL\n);\n\nCREATE TABLE public.user_profiles (\n  id uuid NOT NULL,\n  role text DEFAULT 'user'::text NOT NULL,\n  status text DEFAULT 'active'::text NOT NULL,\n  first_name text,\n  last_name text,\n  display_name text,\n  company_name text,\n  phone text,\n  address_line1 text,\n  address_line2 text,\n  city text,\n  state_region text,\n  postal_code text,\n  country_code text,\n  timezone text DEFAULT 'Australia/Sydney'::text,\n  currency text DEFAULT 'AUD'::text,\n  language text DEFAULT 'en'::text,\n  notes text,\n  admin_notes text,\n  email_verified_at timestamp with time zone,\n  last_login_at timestamp with time zone,\n  last_login_ip inet,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  updated_at timestamp with time zone DEFAULT now() NOT NULL,\n  suspension_reason text,\n  suspended_at timestamp with time zone,\n  banned_at timestamp with time zone,\n  ban_reason text,\n  ban_expires_at timestamp with time zone,\n  enforcement_notes text,\n  customer_number text,\n  suspension_expires_at timestamp with time zone\n);\n\nCREATE TABLE public.wallet_recharges (\n  id uuid DEFAULT gen_random_uuid() NOT NULL,\n  receipt_number text NOT NULL,\n  auth_user_id uuid NOT NULL,\n  amount_cents bigint NOT NULL,\n  currency text DEFAULT 'AUD'::text NOT NULL,\n  status text DEFAULT 'pending'::text NOT NULL,\n  gateway_code text,\n  provider_reference text,\n  credited_cents bigint DEFAULT 0 NOT NULL,\n  balance_after_cents bigint,\n  metadata jsonb DEFAULT '{}'::jsonb NOT NULL,\n  created_at timestamp with time zone DEFAULT now() NOT NULL,\n  updated_at timestamp with time zone DEFAULT now()