E (receipt_number);\\nALTER TABLE wallet_recharges ADD CONSTRAINT wallet_recharges_status_check CHECK (status = ANY (ARRAY['pending'::text, 'action_required'::text, 'processing'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text, 'expired'::text, 'refunded'::text]));\\nALTER TABLE webhook_events ADD CONSTRAINT webhook_events_pkey PRIMARY KEY (id);\\nALTER TABLE webhook_events ADD CONSTRAINT webhook_events_provider_external_event_id_key UNIQUE (provider, external_event_id);\\n\nCREATE INDEX idx_account_activity_user_created ON public.account_activity USING btree (auth_user_id, created_at DESC);\nCREATE INDEX idx_account_activity_user_ip ON public.account_activity USING btree (auth_user_id, ip_address);\nCREATE INDEX idx_account_activity_event ON public.account_activity USING btree (event_type, created_at DESC);\nCREATE INDEX idx_account_activity_entity ON public.account_activity USING btree (entity_type, entity_id, created_at DESC);\nCREATE INDEX idx_credit_ledger_user_created ON public.credit_ledger USING btree (user_id, created_at DESC);\nCREATE INDEX customer_sessions_user_id_idx ON public.customer_sessions USING btree (user_id);\nCREATE INDEX customer_sessions_expires_at_idx ON public.customer_sessions USING btree (expires_at) WHERE (revoked_at IS NULL);\nCREATE UNIQUE INDEX customers_auth_user_unique ON public.customers USING btree (auth_user_id) WHERE (auth_user_id IS NOT NULL);\nCREATE UNIQUE INDEX customers_customer_number_key ON public.customers USING btree (customer_number);\nCREATE UNIQUE INDEX customers_email_lower_uidx ON public.customers USING btree (lower(email));\nCREATE UNIQUE INDEX customers_username_lower_uidx ON public.customers USING btree (lower(username)) WHERE (username IS NOT NULL);\nCREATE UNIQUE INDEX customers_auth_user_id_uidx ON public.customers USING btree (auth_user_id) WHERE (auth_user_id IS NOT NULL);\nCREATE INDEX email_verification_tokens_user_idx ON public.email_verification_tokens USING btree (user_id, created_at DESC);\nCREATE INDEX guest_support_access_attempts_ip_time_idx ON public.guest_support_access_attempts USING btree (request_ip, attempted_at DESC);\nCREATE INDEX idx_license_bindings_user ON public.license_bindings USING btree (auth_user_id);\nCREATE UNIQUE INDEX license_bindings_one_active_per_user ON public.license_bindings USING btree (auth_user_id) WHERE ((archived_at IS NULL) AND (desired_state <> 'revoked'::text) AND (admin_override = false));\nCREATE INDEX idx_license_queue_state ON public.license_enforcement_queue USING btree (state, priority, created_at);\nCREATE INDEX license_fulfillments_auth_user_idx ON public.license_fulfillments USING btree (auth_user_id);\nCREATE UNIQUE INDEX mail_delivery_log_reference_id_uidx ON public.mail_delivery_log USING btree (reference_id) WHERE (reference_id IS NOT NULL);\nCREATE INDEX mail_messages_mailbox_direction_date_idx ON public.mail_messages USING btree (mailbox_address, direction, COALESCE(received_at, sent_at, created_at) DESC);\nCREATE INDEX news_posts_public_feed_idx ON public.news_posts USING btree (published, published_at DESC) WHERE (published = true);\nCREATE INDEX news_posts_category_feed_idx ON public.news_posts USING btree (category, published_at DESC) WHERE (published = true);\nCREATE INDEX news_posts_homepage_idx ON public.news_posts USING btree (show_on_homepage, category, published_at DESC) WHERE ((published = true) AND (show_on_homepage = true));\nCREATE INDEX notifications_recipient_surface_created_idx ON public.notifications USING btree (recipient_user_id, surface, created_at DESC);\nCREATE INDEX notifications_recipient_unread_idx ON public.notifications USING btree (recipient_user_id, surface, created_at DESC) WHERE ((read_at IS NULL) AND (archived_at IS NULL));\nCREATE UNIQUE INDEX notifications_dedupe_idx ON public.notifications USING btree (recipient_user_id, surface, dedupe_key) WHERE (dedupe_key IS NOT NULL);\nCREATE INDEX orbitfs_deployment_events_install_idx ON public.orbitfs_deployment_events USING btree (installation_id, created_at DESC);\nCREATE INDEX orbitfs_installation_releases_install_idx ON public.orbitfs_installation_releases USING btree (installation_id, created_at DESC);\nCREATE INDEX orbitfs_installations_user_idx ON public.orbitfs_installations USING btree (auth_user_id, created_at DESC);\nCREATE INDEX orbitfs_installations_binding_idx ON public.orbitfs_installations USING btree (license_binding_id);\nCREATE INDEX orbitfs_installations_state_idx ON public.orbitfs_installations USING btree (state, updated_at DESC);\nCREATE INDEX orbitfs_release_bundles_channel_status_idx ON public.orbitfs_release_bundles USING btree (channel, status, updated_at DESC);\nCREATE INDEX orbitfs_release_bundles_published_idx ON public.orbitfs_release_bundles USING btree (published_at DESC) WHERE (published_at IS NOT NULL);\nCREATE UNIQUE INDEX order_cancel_one_open_idx ON public.order_cancellation_requests USING btree (order_id) WHERE (status = 'requested'::text);\nCREATE INDEX order_cancellation_status_created_idx ON public.order_cancellation_requests USING btree (status, created_at DESC);\nCREATE INDEX order_cancellation_scheduled_idx ON public.order_cancellation_requests USING btree (scheduled_for) WHERE (status = 'approved_scheduled'::text);\nCREATE UNIQUE INDEX order_cancellation_one_open_idx ON public.order_cancellation_requests USING btree (order_id) WHERE (status = ANY (ARRAY['requested'::text, 'approved_scheduled'::text]));\nCREATE INDEX orders_auth_user_idx ON public.orders USING btree (auth_user_id);\nCREATE INDEX password_reset_tokens_user_created_idx ON public.password_reset_tokens USING btree (user_id, created_at DESC);\nCREATE INDEX password_reset_tokens_expiry_idx ON public.password_reset_tokens USING btree (expires_at) WHERE (used_at IS NULL);\nCREATE INDEX idx_payment_attempts_invoice ON public.payment_attempts USING btree (invoice_id, created_at DESC);\nCREATE INDEX payment_attempts_wallet_recharge_idx ON public.payment_attempts USING btree (wallet_recharge_id, created_at DESC) WHERE (wallet_recharge_id IS NOT NULL);\nCREATE UNIQUE INDEX uq_payment_events_provider ON public.payment_events USING btree (gateway_code, provider_event_id) WHERE (provider_event_id IS NOT NULL);\nCREATE UNIQUE INDEX payment_events_provider_event_unique ON public.payment_events USING btree (gateway_code, provider_event_id) WHERE (provider_event_id IS NOT NULL);\nCREATE INDEX idx_staff_notes_entity ON public.staff_notes USING btree (entity_type, entity_id, created_at DESC) WHERE (deleted_at IS NULL);\nCREATE INDEX support_department_staff_user_idx ON public.support_department_staff USING btree (user_id, department_id);\nCREATE INDEX support_kb_articles_category_idx ON public.support_kb_articles USING btree (category_id, status, sort_order);\nCREATE INDEX idx_ticket_messages_ticket ON public.support_ticket_messages USING btree (ticket_id, created_at);\nCREATE INDEX idx_support_tickets_user ON public.support_tickets USING btree (user_id, updated_at DESC);\nCREATE INDEX idx_support_tickets_queue ON public.support_tickets USING btree (status, priority, updated_at DESC);\nCREATE INDEX support_tickets_assigned_to_idx ON public.support_tickets USING btree (assigned_to);\nCREATE UNIQUE INDEX support_tickets_guest_access_hash_unique ON public.support_tickets USING btree (((metadata ->> 'guest_access_hash'::text))) WHERE ((source = 'public_web'::text) AND (metadata ? 'guest_access_hash'::text));\nCREATE UNIQUE INDEX user_profiles_customer_number_key ON public.user_profiles USING btree (customer_number) WHERE (customer_number IS NOT NULL);\nCREATE INDEX wallet_recharges_user_created_idx ON public.wallet_recharges USING btree (auth_user_id, created_at DESC);\n\nCREATE OR REPLACE VIEW public.admin_metrics AS SELECT ( SELECT count(*) AS count\n           FROM user_profiles) AS customers,\n    ( SELECT count(*) AS count\n           FROM orders) AS orders,\n    ( SELECT COALESCE(sum(orders.total_cents), (0)::bigint) AS "coalesce"\n           FROM orders\n          WHERE (orders.payment_status = ANY (ARRAY['paid'::text, 'paid_credit'::text]))) AS revenue_cents,\n    ( SELECT count(*) AS count\n           FROM support_tickets\n          WHERE (support_tickets.status <> 'closed'::text)) AS open_tickets,\n    ( SELECT count(*) AS count\n           FROM products\n          WHERE (products.active = true)) AS active_products,\n    ( SELECT count(*) AS count\n           FROM license_fulfillments\n          WHERE (license_fulfillments.state = 'pending'::text)) AS pending_licenses;;\\n\\nCREATE OR REPLACE FUNCTION app_private.adjust_credit_impl(target_user uuid, amount_cents bigint, reason text, reference_type text, reference_id text)\n RETURNS account_balances\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'app_private'\nAS $function$ declare b public.account_balances; dir text; abs_amount bigint; begin if not app_private.is_admin() then raise exception 'admin access required'; end if; if amount_cents=0 then raise exception 'amount cannot be zero'; end if; select * into b from public.account_balances where user_id=target_user for update; if not found then insert into public.account_balances(user_id) values(target_user) returning * into b; end if; if amount_cents<0 and b.available_cents+amount_cents<0 and coalesce((select value::text='true' from public.system_settings where key='credit.allow_negative'),false)=false then raise exception 'insufficient credit'; end if; dir:=case when amount_cents>0 then 'credit' else 'debit' end; abs_amount:=abs(amount_cents); update public.account_balances set available_cents=available_cents+amount_cents,lifetime_credit_cents=lifetime_credit_cents+case when amount_cents>0 then amount_cents else 0 end,lifetime_debit_cents=lifetime_debit_cents+case when amount_cents<0 then abs_amount else 0 end,updated_at=now() where user_id=target_user returning * into b; insert into public.credit_ledger(user_id,direction,amount_cents,balance_after_cents,reason,reference_type,reference_id,created_by) values(target_user,dir,abs_amount,b.available_cents,reason,reference_type,reference_id,auth.uid()); return b; end; $function$\n\nCREATE OR REPLACE FUNCTION app_private."current_role"()\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select coalesce((select role from public.user_profiles where id=auth.uid()),'user') $function$\n\nCREATE OR REPLACE FUNCTION app_private.is_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select app_private.current_role() in ('admin','superadmin') $function$\n\nCREATE OR REPLACE FUNCTION app_private.is_staff()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select app_private.current_role() in ('support','admin','superadmin') $function$\n\nCREATE OR REPLACE FUNCTION app_private.is_superadmin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select app_private.current_role()='superadmin' $function$\n\nCREATE OR REPLACE FUNCTION public.account_can_order(target_user uuid DEFAULT auth.uid())\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select coalesce((public.account_enforcement_status(target_user)->>'state')='active',false)\n$function$\n\nCREATE OR REPLACE FUNCTION public.account_enforcement_status(target_user uuid DEFAULT auth.uid())\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare r jsonb;\nbegin\n  if target_user is null then return jsonb_build_object('state','active','support_email','support@orbitfs.cc'); end if;\n  if auth.uid() is not null and target_user<>auth.uid() and not public.has_permission('customers.enforce') then\n    raise exception 'permission denied';\n  end if;\n\n  select jsonb_build_object(\n      'state',\n        case\n          when p.banned_at is not null and (p.ban_expires_at is null or p.ban_expires_at > now()) then 'banned'\n          when p.status='suspended' and (p.suspension_expires_at is null or p.suspension_expires_at > now()) then 'suspended'\n          else 'active'\n        end,\n      'reason',\n        case\n          when p.banned_at is not null and (p.ban_expires_at is null or p.ban_expires_at > now()) then p.ban_reason\n          when p.status='suspended' and (p.suspension_expires_at is null or p.suspension_expires_at > now()) then p.suspension_reason\n          else null\n        end,\n      'expires_at',\n        case\n          when p.banned_at is not null and (p.ban_expires_at is null or p.ban_expires_at > now()) then p.ban_expires_at\n          when p.status='suspended' and (p.suspension_expires_at is null or p.suspension_expires_at > now()) then p.suspension_expires_at\n          else null\n        end,\n      'permanent',\n        case\n          when p.banned_at is not null and (p.ban_expires_at is null or p.ban_expires_at > now()) then p.ban_expires_at is null\n          when p.status='suspended' and (p.suspension_expires_at is null or p.suspension_expires_at > now()) then p.suspension_expires_at is null\n          else false\n        end,\n      'suspended_at',p.suspended_at,\n      'banned_at',p.banned_at,\n      'support_email','support@orbitfs.cc'\n    )\n  into r\n  from public.user_profiles p where p.id=target_user;\n\n  return coalesce(r,jsonb_build_object('state','active','support_email','support@orbitfs.cc'));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.add_to_cart(p_product_id uuid, p_configuration jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); cid uuid; prod public.products%rowtype; is_gift boolean:=false; gift_email text;\nbegin\n if uid is null then raise exception 'authentication required'; end if;\n if not public.account_can_order(uid) then raise exception 'account is not allowed to place new orders'; end if;\n select * into prod from public.products where id=p_product_id and active=true;\n if not found then raise exception 'product unavailable'; end if;\n if prod.price_cents is null and not coalesce((prod.metadata->>'free_product')::boolean,false) then raise exception 'product pricing has not been configured'; end if;\n is_gift:=coalesce((p_configuration->>'gift')::boolean,false);\n gift_email:=lower(trim(coalesce(p_configuration->>'gift_recipient_email','')));\n if is_gift and (gift_email='' or gift_email !~* '^[A-Z0-9._%+\\-]+@[A-Z0-9.\\-]+\\.[A-Z]{2,}$') then raise exception 'enter a valid gift recipient email'; end if;\n if not is_gift and not coalesce((prod.metadata->>'allow_repeat_purchase')::boolean,false) and public.user_has_active_product(uid,prod.id) then raise exception 'you already own this active product'; end if;\n cid:=public.get_or_create_cart();\n insert into public.shopping_cart_items(cart_id,product_id,configuration) values(cid,prod.id,coalesce(p_configuration,'{}'::jsonb))\n on conflict(cart_id,product_id) do update set configuration=excluded.configuration,updated_at=now();\n update public.shopping_carts set updated_at=now() where id=cid;\n return jsonb_build_object('ok',true,'cart_id',cid,'gift',is_gift,'gift_recipient_email',nullif(gift_email,''));\nend $function$\n\nCREATE OR REPLACE FUNCTION public.adjust_credit(target_user uuid, amount_cents bigint, reason text, reference_type text DEFAULT NULL::text, reference_id text DEFAULT NULL::text)\n RETURNS account_balances\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'app_private'\nAS $function$ begin if not public.has_permission('credit.manage') then raise exception 'permission denied: credit.manage'; end if; return app_private.adjust_credit_impl(target_user,amount_cents,reason,reference_type,reference_id); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_add_staff_note(p_entity_type text, p_entity_id uuid, p_body text, p_visibility text DEFAULT 'internal'::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare nid uuid; begin if not public.staff_note_permission(p_entity_type,'manage') then raise exception 'permission denied for % notes',p_entity_type; end if; if p_visibility='customer' and not public.has_permission('notes.external') and public.current_role()<>'superadmin' then raise exception 'permission denied: notes.external'; end if; if p_entity_type not in ('customer','order','invoice','support_ticket') or p_visibility not in ('internal','customer') or coalesce(btrim(p_body),'')='' then raise exception 'invalid note'; end if; insert into public.staff_notes(entity_type,entity_id,visibility,body,created_by) values(p_entity_type,p_entity_id,p_visibility,btrim(p_body),auth.uid()) returning id into nid; insert into public.staff_note_revisions(note_id,body,visibility,revision_type,changed_by) values(nid,btrim(p_body),p_visibility,'created',auth.uid()); insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'note.add',p_entity_type,p_entity_id::text,jsonb_build_object('note_id',nid,'visibility',p_visibility)); return nid; end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_archive_support_ticket(p_ticket_id uuid, p_reason text DEFAULT NULL::text, p_archive boolean DEFAULT true)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare t public.support_tickets%rowtype; begin\n if not public.has_permission('support.archive') then raise exception 'permission denied: support.archive'; end if;\n select * into t from public.support_tickets where id=p_ticket_id for update; if not found then raise exception 'ticket not found'; end if;\n update public.support_tickets set archived_at=case when p_archive then now() else null end,archived_by=case when p_archive then auth.uid() else null end,archive_reason=case when p_archive then p_reason else null end,updated_at=now() where id=p_ticket_id;\n insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail) values(p_ticket_id,auth.uid(),case when p_archive then 'archived' else 'unarchived' end,jsonb_build_object('reason',p_reason));\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),case when p_archive then 'support.archive' else 'support.unarchive' end,'support_ticket',p_ticket_id::text,jsonb_build_object('ticket_number',t.ticket_number,'reason',p_reason));\n return jsonb_build_object('ok',true,'archived',p_archive); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_attach_license_to_order(p_order_id uuid, p_binding_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare o public.orders%rowtype; b public.license_bindings%rowtype; base_item uuid;\nbegin\n if not public.has_permission('orders.attach_license') then raise exception 'permission denied: orders.attach_license'; end if;\n select * into o from public.orders where id=p_order_id for update;\n select * into b from public.license_bindings where id=p_binding_id for update;\n if o.id is null or b.id is null then raise exception 'order or licence not found'; end if;\n if b.auth_user_id<>o.auth_user_id then raise exception 'licence belongs to a different customer'; end if;\n if b.desired_state='revoked' then raise exception 'revoked licence cannot be attached'; end if;\n select id into base_item from public.order_items where order_id=o.id and public.canonical_license_component_key(license_product_key)='orbitfs_base' order by id limit 1;\n update public.license_bindings set order_id=o.id,order_item_id=coalesce(base_item,order_item_id),updated_at=now(),notes=case when p_reason is null then notes else concat_ws(E'\\n',notes,'Attached to order #'||o.order_number||': '||p_reason) end where id=b.id;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.attach_license','order',o.id::text,jsonb_build_object('binding_id',b.id,'reason',p_reason));\n return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_cancellation_queue_snapshot()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare rows jsonb; pending_count int;\nbegin\n  if not public.has_permission('customers.cancellations') then raise exception 'permission denied: customers.cancellations'; end if;\n  select coalesce(jsonb_agg(to_jsonb(x) order by case when x.status='requested' then 0 else 1 end,x.created_at asc),'[]'::jsonb) into rows\n  from (\n    select r.id,r.order_id,r.auth_user_id,r.reason,r.status,r.staff_note,r.requested_timing,r.scheduled_for,r.reviewed_at,r.processed_at,r.created_at,r.updated_at,\n      r.refund_preference,r.refund_status,r.refund_amount_cents,r.refund_processed_cents,r.refund_last_error,r.refund_completed_at,\n      o.order_number,o.status order_status,o.service_status,o.payment_status,o.total_cents,o.currency,o.activated_at,\n      i.id invoice_id,i.invoice_number,i.status invoice_status,i.paid_cents invoice_paid_cents,\n      coalesce(p.display_name,nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),u.email,'Customer') customer_name,u.email customer_email,\n      s.id subscription_id,s.status subscription_status,s.interval_unit,s.interval_count,s.next_charge_at,s.cancel_at_period_end\n    from public.order_cancellation_requests r\n    join public.orders o on o.id=r.order_id\n    left join lateral (select * from public.invoices ix where ix.order_id=o.id order by ix.created_at desc limit 1) i on true\n    left join public.user_profiles p on p.id=r.auth_user_id\n    left join auth.users u on u.id=r.auth_user_id\n    left join lateral (select * from public.payment_subscriptions ps where ps.order_id=o.id order by ps.created_at desc limit 1) s on true\n    order by r.created_at desc limit 250\n  ) x;\n  select count(*) into pending_count from public.order_cancellation_requests where status='requested';\n  return jsonb_build_object('requests',rows,'pending_count',pending_count,'scheduled_count',(select count(*) from public.order_cancellation_requests where status='approved_scheduled'));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_create_order_invoice(p_customer_id uuid, p_mode text, p_currency text DEFAULT 'AUD'::text, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text, p_lines jsonb DEFAULT '[]'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  ord uuid;\n  inv uuid;\n  ordno text;\n  invno text;\n  order_prefix text := 'ORB-';\n  invoice_prefix text := 'INV-';\n  total bigint := 0;\n  line jsonb;\n  qty integer;\n  unit bigint;\n  prod public.products%rowtype;\n  order_item uuid;\n  customer_user uuid;\n  desc_text text;\n  product_id uuid;\nbegin\n  if not (public.has_permission('orders.edit') or public.has_permission('invoices.edit')) then\n    raise exception 'permission denied';\n  end if;\n  if p_mode not in ('order_only','order_invoice','invoice_only') then\n    raise exception 'invalid creation mode';\n  end if;\n  if p_mode = 'order_only' and not public.has_permission('orders.edit') then\n    raise exception 'orders.edit permission required';\n  end if;\n  if p_mode = 'invoice_only' and not public.has_permission('invoices.edit') then\n    raise exception 'invoices.edit permission required';\n  end if;\n\n  select auth_user_id into customer_user from public.customers where id=p_customer_id;\n  if customer_user is null then raise exception 'customer must have a linked user account'; end if;\n  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines)=0 then raise exception 'at least one line item is required'; end if;\n\n  for line in select value from jsonb_array_elements(p_lines) loop\n    qty := greatest(1,coalesce((line->>'quantity')::integer,1));\n    unit := greatest(0,coalesce((line->>'unit_price_cents')::bigint,0));\n    total := total + qty*unit;\n  end loop;\n\n  select coalesce((select trim(both '"' from value::text) from public.app_settings where key='billing.order_prefix'),'ORB-') into order_prefix;\n  select coalesce((select trim(both '"' from value::text) from public.app_settings where key='invoice.prefix'),'INV-') into invoice_prefix;\n\n  if p_mode in ('order_only','order_invoice') then\n    ordno := order_prefix||lpad(nextval('public.order_number_seq')::text,6,'0');\n    insert into public.orders(order_number,customer_id,auth_user_id,status,payment_status,fulfillment_status,subtotal_cents,total_cents,currency,notes,metadata)\n    values(ordno,p_customer_id,customer_user,case when p_mode='order_only' then 'pending' else 'pending_payment' end,'unpaid','pending',total,total,upper(coalesce(nullif(p_currency,''),'AUD')),p_notes,jsonb_build_object('created_by_admin',auth.uid()))\n    returning id into ord;\n  end if;\n\n  if p_mode in ('order_invoice','invoice_only') then\n    invno := invoice_prefix||lpad(nextval('public.invoice_number_seq')::text,6,'0');\n    insert into public.invoices(invoice_number,order_id,auth_user_id,status,subtotal_cents,discount_cents,total_cents,paid_cents,currency,due_at,notes,metadata)\n    values(invno,ord,customer_user,'unpaid',total,0,total,0,upper(coalesce(nullif(p_currency,''),'AUD')),coalesce(p_due_at,now()+interval '7 days'),p_notes,jsonb_build_object('created_by_admin',auth.uid(),'admin_created',true,'invoice_only',p_mode='invoice_only'))\n    returning id into inv;\n  end if;\n\n  for line in select value from jsonb_array_elements(p_lines) loop\n    qty := greatest(1,coalesce((line->>'quantity')::integer,1));\n    unit := greatest(0,coalesce((line->>'unit_price_cents')::bigint,0));\n    product_id := nullif(line->>'product_id','')::uuid;\n    if product_id is not null then select * into prod from public.products where id=product_id; end if;\n    desc_text := coalesce(nullif(btrim(line->>'description'),''),prod.name,'Custom item');\n    order_item := null;\n\n    if ord is not null then\n      insert into public.order_items(order_id,product_id,product_name,product_slug,license_product_key,quantity,unit_price_cents,total_cents,configuration,metadata)\n      values(ord,product_id,desc_text,case when product_id is not null then prod.slug else null end,coalesce(case when product_id is not null then prod.license_product_key end,'custom'),qty,unit,qty*unit,coalesce(line->'configuration','{}'::jsonb),jsonb_build_object('created_by_admin',auth.uid()))\n      returning id into order_item;\n    end if;\n\n    if inv is not null then\n      insert into public.invoice_items(invoice_id,order_item_id,description,quantity,unit_price_cents,total_cents,metadata)\n      values(inv,order_item,desc_text,qty,unit,qty*unit,jsonb_build_object('created_by_admin',auth.uid()));\n    end if;\n  end loop;\n\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(auth.uid(),'billing.create',case p_mode when 'invoice_only' then 'invoice' when 'order_only' then 'order' else 'order_invoice' end,coalesce(inv,ord)::text,jsonb_build_object('mode',p_mode,'order_id',ord,'invoice_id',inv,'total_cents',total));\n\n  return jsonb_build_object('ok',true,'mode',p_mode,'order_id',ord,'order_number',ordno,'invoice_id',inv,'invoice_number',invno,'total_cents',total);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_create_support_ticket(p_user_id uuid, p_department_id uuid, p_subject text, p_priority text, p_body text, p_related_order_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare tid uuid; num bigint; mid uuid; r integer;\nbegin\n if not public.has_permission('support.ticket_create') then raise exception 'permission denied: support.ticket_create'; end if;\n r:=public.support_staff_rank(auth.uid());\n if not exists(select 1 from public.support_departments where id=p_department_id and enabled=true and allow_direct_create=true and r>=min_support_rank) then raise exception 'advanced departments cannot be used to start a ticket; move or escalate an existing ticket instead'; end if;\n if r<3 and not public.support_user_has_department(auth.uid(),p_department_id) then raise exception 'you are not assigned to this support department'; end if;\n if p_user_id is null or not exists(select 1 from public.user_profiles where id=p_user_id) then raise exception 'customer not found'; end if;\n if nullif(trim(coalesce(p_subject,'')),'') is null or nullif(trim(coalesce(p_body,'')),'') is null then raise exception 'subject and message are required'; end if;\n if p_priority not in ('low','normal','high','urgent') then raise exception 'invalid priority'; end if;\n if p_related_order_id is not null and not exists(select 1 from public.orders where id=p_related_order_id and auth_user_id=p_user_id) then raise exception 'order not found'; end if;\n insert into public.support_tickets(user_id,department_id,subject,status,priority,source,related_order_id,last_staff_reply_at,last_reply_at)\n values(p_user_id,p_department_id,trim(p_subject),'open',p_priority,'admin',p_related_order_id,now(),now()) returning id,ticket_number into tid,num;\n insert into public.support_ticket_messages(ticket_id,author_user_id,author_role,body,internal_note,attachments)\n values(tid,auth.uid(),public.current_role(),trim(p_body),false,'[]'::jsonb) returning id into mid;\n perform public.support_emit_system_message(tid,'welcome','{}'::jsonb);\n insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail)\n values(tid,auth.uid(),'admin_created',jsonb_build_object('priority',p_priority,'department_id',p_department_id,'message_id',mid,'customer_id',p_user_id));\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n values(auth.uid(),'support.ticket.create','support_ticket',tid::text,jsonb_build_object('ticket_number',num,'customer_id',p_user_id,'department_id',p_department_id));\n return jsonb_build_object('id',tid,'ticket_number',num);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_customer_activity_snapshot(p_user_id uuid)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select case when public.has_permission('customers.view') or public.has_permission('audit.view') then jsonb_build_object(\n    'events',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at desc) from (select * from public.account_activity where auth_user_id=p_user_id order by created_at desc limit 250) a),'[]'::jsonb),\n    'ips',coalesce((select jsonb_agg(jsonb_build_object('ip_address',x.ip_address::text,'first_seen',x.first_seen,'last_seen',x.last_seen,'events',x.events,'last_user_agent',x.last_user_agent) order by x.last_seen desc) from (select ip_address,min(created_at) first_seen,max(created_at) last_seen,count(*) events,(array_agg(user_agent order by created_at desc))[1] last_user_agent from public.account_activity where auth_user_id=p_user_id and ip_address is not null group by ip_address) x),'[]'::jsonb),\n    'event_counts',coalesce((select jsonb_object_agg(event_type,cnt) from (select event_type,count(*) cnt from public.account_activity where auth_user_id=p_user_id group by event_type) q),'{}'::jsonb)\n  ) else null end\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_customer_mail_snapshot(p_user_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_email text; v_templates jsonb; v_logs jsonb;\nbegin\n  if not public.has_permission('customers.view') then raise exception 'permission denied: customers.view'; end if;\n  select email into v_email from public.customers where auth_user_id=p_user_id;\n\n  select coalesce(jsonb_agg(to_jsonb(t) order by t.category,t.name),'[]'::jsonb) into v_templates\n  from public.mail_templates t\n  where t.enabled=true;\n\n  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) into v_logs\n  from (\n    select id,provider_id,template_key,event_type,related_type,related_id,recipient,sender,subject,status,error,sent_at,created_at\n    from public.mail_delivery_log\n    where lower(recipient)=lower(coalesce(v_email,''))\n    order by created_at desc limit 100\n  ) x;\n  return jsonb_build_object('email',v_email,'templates',v_templates,'logs',v_logs);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_dashboard_metrics()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ begin if public.current_role() not in ('support','admin','superadmin') then raise exception 'staff access required'; end if; return jsonb_build_object('customers',(select count(*) from public.user_profiles),'active_customers',(select count(*) from public.user_profiles where status='active'),'orders',(select count(*) from public.orders),'revenue_cents',(select coalesce(sum(total_cents),0) from public.orders where payment_status in ('paid','paid_credit')),'open_tickets',(select count(*) from public.support_tickets where status<>'closed'),'pending_licenses',(select count(*) from public.license_fulfillments where state='pending'),'active_products',(select count(*) from public.products where active=true),'credit_outstanding_cents',(select coalesce(sum(available_cents),0) from public.account_balances)); end; $function$\n\nCREATE OR REPLACE FUNCTION public.admin_delete_staff_note(p_note_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare n public.staff_notes%rowtype; begin select * into n from public.staff_notes where id=p_note_id and deleted_at is null for update; if not found then raise exception 'note not found'; end if; if not public.staff_note_permission(n.entity_type,'manage') then raise exception 'permission denied'; end if; insert into public.staff_note_revisions(note_id,body,visibility,revision_type,changed_by) values(p_note_id,n.body,n.visibility,'deleted',auth.uid()); update public.staff_notes set deleted_at=now(),updated_at=now() where id=p_note_id; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'note.delete',n.entity_type,n.entity_id::text,jsonb_build_object('note_id',p_note_id)); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_delete_support_department(p_department_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare ticket_count integer; dname text;\nbegin\n if not (public.has_permission('support.settings') or public.has_permission('support.departments.manage')) then raise exception 'permission denied: support.departments.manage'; end if;\n select name into dname from public.support_departments where id=p_department_id; if dname is null then raise exception 'department not found'; end if;\n select count(*) into ticket_count from public.support_tickets where department_id=p_department_id;\n if ticket_count>0 then raise exception 'department has % historical or active ticket(s); disable it instead to preserve ticket history',ticket_count; end if;\n delete from public.support_departments where id=p_department_id;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'support.department.delete','support_department',p_department_id::text,jsonb_build_object('name',dname));\n return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_delete_support_ticket(p_ticket_id uuid, p_reason text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare t public.support_tickets%rowtype; paths jsonb; begin\n if not public.has_permission('support.delete') then raise exception 'permission denied: support.delete'; end if;\n if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'deletion reason is required'; end if;\n select * into t from public.support_tickets where id=p_ticket_id for update; if not found then raise exception 'ticket not found'; end if;\n select coalesce(jsonb_agg(storage_path),'[]'::jsonb) into paths from public.support_attachments where ticket_id=p_ticket_id;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'support.delete','support_ticket',p_ticket_id::text,jsonb_build_object('ticket_number',t.ticket_number,'subject',t.subject,'customer_id',t.user_id,'reason',p_reason));\n delete from public.staff_notes where entity_type='support_ticket' and entity_id=p_ticket_id;\n delete from public.support_tickets where id=p_ticket_id;\n return jsonb_build_object('ok',true,'storage_paths',paths); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_delete_website_license(p_binding_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare b public.license_bindings%rowtype; begin if not public.has_permission('licenses.delete') then raise exception 'permission denied: licenses.delete'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'delete reason is required'; end if; select * into b from public.license_bindings where id=p_binding_id; if not found then raise exception 'licence not found'; end if; if b.api_source<>'website' then raise exception 'native delete is only available for website licences'; end if; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'license.delete','license_binding',p_binding_id::text,jsonb_build_object('reason',p_reason,'auth_user_id',b.auth_user_id,'label',b.label)); delete from public.license_validation_log where binding_id=p_binding_id; delete from public.license_installations where binding_id=p_binding_id; delete from public.license_controller_requests where binding_id=p_binding_id; delete from public.license_enforcement_queue where binding_id=p_binding_id; delete from public.license_bindings where id=p_binding_id; perform public.bump_license_revision(); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_edit_invoice(p_invoice_id uuid, p_due_at timestamp with time zone, p_notes text, p_subtotal_cents bigint, p_discount_cents bigint, p_tax_cents bigint, p_total_cents bigint, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare inv public.invoices%rowtype; begin if not public.has_permission('invoices.edit') then raise exception 'permission denied: invoices.edit'; end if; select * into inv from public.invoices where id=p_invoice_id for update; if not found then raise exception 'invoice not found'; end if; if inv.status='paid' and not public.has_permission('billing.edit_paid') then raise exception 'permission denied: billing.edit_paid'; end if; if p_total_cents<0 or p_subtotal_cents<0 or p_discount_cents<0 or p_tax_cents<0 then raise exception 'amounts cannot be negative'; end if; if p_total_cents<coalesce(inv.paid_cents,0) and not public.has_permission('billing.override_state') then raise exception 'new total cannot be lower than amount already paid'; end if; update public.invoices set due_at=p_due_at,notes=p_notes,subtotal_cents=p_subtotal_cents,discount_cents=p_discount_cents,tax_cents=p_tax_cents,total_cents=p_total_cents,updated_at=now() where id=inv.id; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'invoice.edit','invoice',inv.id::text,jsonb_build_object('reason',p_reason,'old_total',inv.total_cents,'new_total',p_total_cents)); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_edit_invoice_item(p_item_id uuid, p_description text, p_quantity integer, p_unit_price_cents bigint, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare ii public.invoice_items%rowtype; inv public.invoices%rowtype; new_subtotal bigint; begin if not public.has_permission('invoices.edit_items') then raise exception 'permission denied: invoices.edit_items'; end if; select * into ii from public.invoice_items where id=p_item_id for update; select * into inv from public.invoices where id=ii.invoice_id; if ii.id is null then raise exception 'invoice item not found'; end if; if inv.status='paid' and not public.has_permission('billing.edit_paid') then raise exception 'permission denied: billing.edit_paid'; end if; if p_quantity<1 or p_unit_price_cents<0 then raise exception 'invalid item values'; end if; update public.invoice_items set description=p_description,quantity=p_quantity,unit_price_cents=p_unit_price_cents,total_cents=p_quantity*p_unit_price_cents where id=p_item_id; select coalesce(sum(total_cents),0) into new_subtotal from public.invoice_items where invoice_id=ii.invoice_id; update public.invoices set subtotal_cents=new_subtotal,total_cents=new_subtotal-coalesce(discount_cents,0)+coalesce(tax_cents,0),updated_at=now() where id=ii.invoice_id; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'invoice.item_edit','invoice_item',p_item_id::text,jsonb_build_object('reason',p_reason)); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_edit_order(p_order_id uuid, p_notes text, p_total_cents bigint, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare o public.orders%rowtype; begin if not public.has_permission('orders.edit') then raise exception 'permission denied: orders.edit'; end if; select * into o from public.orders where id=p_order_id for update; if not found then raise exception 'order not found'; end if; if o.payment_status like 'paid%' and not public.has_permission('billing.edit_paid') then raise exception 'permission denied: billing.edit_paid'; end if; if p_total_cents<0 then raise exception 'total cannot be negative'; end if; update public.orders set notes=p_notes,total_cents=p_total_cents,updated_at=now() where id=o.id; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.edit','order',o.id::text,jsonb_build_object('reason',p_reason,'old_total',o.total_cents,'new_total',p_total_cents)); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_edit_order_item(p_item_id uuid, p_product_name text, p_license_product_key text, p_quantity integer, p_unit_price_cents integer, p_configuration jsonb, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare oi public.order_items%rowtype; o public.orders%rowtype; new_total bigint; begin if not public.has_permission('orders.edit_items') then raise exception 'permission denied: orders.edit_items'; end if; select * into oi from public.order_items where id=p_item_id for update; if not found then raise exception 'order item not found'; end if; select * into o from public.orders where id=oi.order_id; if o.payment_status like 'paid%' and not public.has_permission('billing.edit_paid') then raise exception 'permission denied: billing.edit_paid'; end if; if p_quantity<1 or p_unit_price_cents<0 then raise exception 'invalid item values'; end if; update public.order_items set product_name=p_product_name,license_product_key=p_license_product_key,quantity=p_quantity,unit_price_cents=p_unit_price_cents,total_cents=p_quantity*p_unit_price_cents,configuration=coalesce(p_configuration,'{}'::jsonb) where id=p_item_id; select coalesce(sum(total_cents),0) into new_total from public.order_items where order_id=oi.order_id; update public.orders set total_cents=new_total,updated_at=now() where id=oi.order_id; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.item_edit','order_item',p_item_id::text,jsonb_build_object('reason',p_reason)); return jsonb_build_object('ok',true,'order_total_cents',new_total); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_edit_website_license(p_binding_id uuid, p_label text, p_state text, p_expires_at timestamp with time zone, p_notes text, p_components jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare old public.license_bindings%rowtype; begin if not public.has_permission('licenses.edit') then raise exception 'permission denied: licenses.edit'; end if; select * into old from public.license_bindings where id=p_binding_id and api_source='website'; if not found then raise exception 'website licence not found'; end if; if p_state is distinct from old.desired_state and not public.has_permission('licenses.enforce') then raise exception 'permission denied: licenses.enforce'; end if; update public.license_bindings set label=coalesce(nullif(trim(p_label),''),label),desired_state=p_state,remote_state=p_state,expires_at=p_expires_at,notes=p_notes,components=coalesce(p_components,components),updated_at=now() where id=p_binding_id; perform public.bump_license_revision(); insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'license.edit','license_binding',p_binding_id::text,jsonb_build_object('state',p_state)); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_enforced_accounts()\n RETURNS TABLE(id uuid, display_name text, customer_number text, status text, effective_state text, reason text, expires_at timestamp with time zone, suspended_at timestamp with time zone, banned_at timestamp with time zone)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select p.id,p.display_name,p.customer_number,p.status,\n    public.account_enforcement_status(p.id)->>'state' effective_state,\n    public.account_enforcement_status(p.id)->>'reason' reason,\n    nullif(public.account_enforcement_status(p.id)->>'expires_at','')::timestamptz expires_at,\n    p.suspended_at,p.banned_at\n  from public.user_profiles p\n  where public.has_permission('customers.enforce')\n    and (public.account_enforcement_status(p.id)->>'state') in ('suspended','banned')\n  order by coalesce(p.banned_at,p.suspended_at) desc\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_escalate_support_ticket(p_ticket_id uuid, p_target_level integer, p_reason text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare t public.support_tickets%rowtype; rank integer; target_label text; new_department uuid; mapped uuid;\nbegin\n if not public.has_permission('support.escalate') then raise exception 'permission denied: support.escalate'; end if;\n if p_target_level not between 0 and 3 then raise exception 'invalid escalation level'; end if;\n if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'escalation reason is required'; end if;\n rank:=public.support_staff_rank(auth.uid());\n select * into t from public.support_tickets where id=p_ticket_id for update; if not found then raise exception 'ticket not found'; end if;\n if not public.support_staff_can_access_ticket(p_ticket_id,auth.uid()) then raise exception 'ticket is outside your support department or escalation level'; end if;\n if p_target_level>t.escalation_level then\n   if p_target_level<>t.escalation_level+1 then raise exception 'tickets must escalate one support level at a time'; end if;\n   if p_target_level>least(rank,3) then raise exception 'your support level cannot escalate to that tier'; end if;\n elsif p_target_level<t.escalation_level then\n   if p_target_level<>t.escalation_level-1 then raise exception 'tickets must de-escalate one support level at a time'; end if;\n   if not public.has_permission('support.escalation.manage') then raise exception 'permission denied: support.escalation.manage'; end if;\n   if rank<t.escalation_level+1 then raise exception 'your support level cannot de-escalate this ticket'; end if;\n end if;\n target_label:=case p_target_level when 3 then 'Superadmin' when 2 then 'Admin' when 1 then 'Senior Support' else 'Support' end;\n new_department:=t.department_id;\n if p_target_level>t.escalation_level then\n   select escalation_department_id into mapped from public.support_departments where id=t.department_id;\n   if mapped is not null then new_department:=mapped; end if;\n elsif p_target_level=0 and p_target_level<t.escalation_level then\n   select id into mapped from public.support_departments where escalation_department_id=t.department_id and enabled=true order by sort_order limit 1;\n   if mapped is not null then new_department:=mapped; end if;\n end if;\n perform public.support_emit_system_message(p_ticket_id,'escalated',jsonb_build_object('escalation',target_label,'reason',trim(p_reason),'status','escalated'));\n update public.support_tickets set\n   escalation_level=p_target_level,\n   escalation_reason=trim(p_reason),\n   department_id=new_department,\n   escalated_at=case when p_target_level=0 then null else now() end,\n   escalated_by=case when p_target_level=0 then null else auth.uid() end,\n   assigned_to=case when p_target_level<>t.escalation_level then null else assigned_to end,\n   claim_required=case when p_target_level<>t.escalation_level then true else claim_required end,\n   updated_at=now()\n where id=p_ticket_id;\n insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail)\n values(p_ticket_id,auth.uid(),case when p_target_level>t.escalation_level then 'escalated' when p_target_level<t.escalation_level then 'deescalated' else 'escalation_updated' end,\n   jsonb_build_object('from_level',t.escalation_level,'to_level',p_target_level,'target',target_label,'reason',trim(p_reason),'from_department_id',t.department_id,'to_department_id',new_department,'claim_required',p_target_level<>t.escalation_level));\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n values(auth.uid(),'support.escalation','support_ticket',p_ticket_id::text,jsonb_build_object('ticket_number',t.ticket_number,'from_level',t.escalation_level,'to_level',p_target_level,'reason',trim(p_reason),'from_department_id',t.department_id,'to_department_id',new_department));\n return jsonb_build_object('ok',true,'level',p_target_level,'label',target_label,'department_id',new_department,'claim_required',p_target_level<>t.escalation_level);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_force_activate_order(p_order_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'extensions'\nAS $function$\ndeclare\n  o public.orders%rowtype;\n  inv public.invoices%rowtype;\n  remaining bigint;\nbegin\n  if not public.has_permission('orders.override_payment') then raise exception 'permission denied: orders.override_payment'; end if;\n  if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'override reason is required'; end if;\n  select * into o from public.orders where id=p_order_id for update;\n  if not found then raise exception 'order not found'; end if;\n  select * into inv from public.invoices where order_id=p_order_id order by created_at desc limit 1 for update;\n  if not found then raise exception 'order has no invoice'; end if;\n  if inv.status in ('void','cancelled') then raise exception 'void/cancelled invoice cannot be force activated'; end if;\n\n  remaining:=greatest(0,coalesce(inv.total_cents,0)-coalesce(inv.paid_cents,0));\n  if remaining>0 then\n    insert into public.invoice_payments(invoice_id,auth_user_id,method,amount_cents,status,external_reference,metadata)\n    values(inv.id,o.auth_user_id,'admin_override',remaining,'completed','ADMIN-OVERRIDE',jsonb_build_object('recorded_by',auth.uid(),'reason',p_reason,'bypass',true));\n  end if;\n\n  update public.invoices\n     set paid_cents=total_cents,status='paid',paid_at=coalesce(paid_at,now()),notes=concat_ws(E'\\n',notes,'Admin activation override: '||p_reason),updated_at=now()\n   where id=inv.id;\n\n  update public.orders\n     set payment_status='paid_admin_override',status='active',\n         notes=concat_ws(E'\\n',notes,'Admin activation override: '||p_reason),\n         metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('approval_state','approved','approval_required',false,'approved_at',now(),'approved_by',auth.uid(),'approval_via','payment_override'),\n         updated_at=now()\n   where id=o.id;\n\n  perform public.grant_paid_order_entitlements(o.id,o.auth_user_id);\n\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(auth.uid(),'order.force_activate','order',o.id::text,jsonb_build_object('invoice_id',inv.id,'override_cents',remaining,'reason',p_reason,'activated',true));\n\n  return jsonb_build_object('ok',true,'overridden_cents',remaining,'invoice_id',inv.id,'order_id',o.id,'activated',true);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_gateway_setup_summary()\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nselect case when public.has_permission('payment_gateways.manage') then\n  coalesce(jsonb_agg(jsonb_build_object(\n    'gateway_id',g.id,\n    'code',g.code,\n    'provider',g.provider,\n    'display_name',g.display_name,\n    'enabled',g.enabled,\n    'currencies',g.currencies,\n    'environment',s.environment,\n    'setup_status',s.setup_status,\n    'last_verified_at',s.last_verified_at,\n    'last_verify_error',s.last_verify_error,\n    'webhook_config',s.webhook_config,\n    'metadata',s.metadata,\n    'configured_keys',(\n      select coalesce(jsonb_agg(k),'[]'::jsonb)\n      from jsonb_object_keys(s.secret_refs) k\n    )\n  ) order by g.sort_order,g.display_name),'[]'::jsonb)\nelse '[]'::jsonb end\nfrom public.payment_gateways g\nleft join public.payment_gateway_setups s on s.gateway_id=g.id;\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_get_customer_email(p_user_id uuid)\n RETURNS text\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare e text;\nbegin\n  if not public.has_permission('customers.password_reset') then raise exception 'permission denied: customers.password_reset'; end if;\n  select email into e from public.customers where auth_user_id=p_user_id;\n  return e;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_get_staff_snapshot()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  can_view boolean := public.has_permission('staff.view') or public.has_permission('staff.manage') or public.has_permission('staff.invite') or public.has_permission('staff.groups.view') or public.has_permission('staff.groups.manage') or public.has_permission('settings.permissions');\n  can_manage boolean := public.has_permission('staff.manage') or public.has_permission('settings.permissions');\n  can_invite boolean := public.has_permission('staff.invite') or public.has_permission('settings.permissions');\n  can_groups_view boolean := public.has_permission('staff.groups.view') or public.has_permission('staff.groups.manage') or public.has_permission('settings.permissions');\n  can_groups_manage boolean := public.has_permission('staff.groups.manage') or public.has_permission('settings.permissions');\n  can_permission_admin boolean := public.has_permission('settings.permissions');\n  result jsonb;\nbegin\n  if not can_view then raise exception 'Permission denied'; end if;\n  select jsonb_build_object(\n    'members', coalesce((select jsonb_agg(jsonb_build_object('user_id',sm.user_id,'status',sm.status,'title',sm.title,'department',sm.department,'staff_notes',sm.staff_notes,'created_at',sm.created_at,'updated_at',sm.updated_at,'display_name',coalesce(up.display_name,c.name,sm.user_id::text),'email',coalesce(c.email,''),'customer_id',c.id,'customer_number',c.customer_number,'is_customer',(c.id is not null),'profile_status',up.status,'profile_role',up.role,'group_ids',coalesce((select jsonb_agg(sg.id order by smg.is_primary desc,sg.sort_order,sg.name) from public.staff_member_groups smg join public.staff_groups sg on sg.id=smg.group_id where smg.user_id=sm.user_id),'[]'::jsonb),'primary_group_id',(select smg.group_id from public.staff_member_groups smg join public.staff_groups sg on sg.id=smg.group_id where smg.user_id=sm.user_id order by smg.is_primary desc,sg.sort_order,sg.name limit 1),'group_names',coalesce((select jsonb_agg(sg.name order by smg.is_primary desc,sg.sort_order,sg.name) from public.staff_member_groups smg join public.staff_groups sg on sg.id=smg.group_id where smg.user_id=sm.user_id),'[]'::jsonb),'effective_permissions',coalesce((select jsonb_agg(k order by k) from (select distinct e.key as k from public.staff_member_groups smg join public.staff_groups sg on sg.id=smg.group_id cross join lateral jsonb_each_text(sg.permissions) e where smg.user_id=sm.user_id and e.value='true') q),'[]'::jsonb)) order by sm.status desc,coalesce(up.display_name,c.name,c.email,sm.user_id::text)) from public.staff_members sm left join public.user_profiles up on up.id=sm.user_id left join lateral (select c1.* from public.customers c1 where c1.auth_user_id=sm.user_id order by c1.created_at desc nulls last limit 1) c on true),'[]'::jsonb),\n    'groups',coalesce((select jsonb_agg(to_jsonb(sg) order by sg.sort_order,sg.name) from public.staff_groups sg),'[]'::jsonb),\n    'availableCustomers',case when can_invite then coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'auth_user_id',c.auth_user_id,'email',c.email,'name',c.name,'status',c.status,'customer_number',c.customer_number) order by coalesce(c.name,c.email)) from public.customers c where c.auth_user_id is not null and not exists(select 1 from public.staff_members sm where sm.user_id=c.auth_user_id)),'[]'::jsonb) else '[]'::jsonb end,\n    'can',jsonb_build_object('view',can_view,'manage',can_manage,'invite',can_invite,'groupsView',can_groups_view,'groupsManage',can_groups_manage,'permissionAdmin',can_permission_admin)\n  ) into result;\n  return result;\nend;\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_issue_website_license(p_user_id uuid, p_label text, p_components jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text, p_superadmin_override boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'extensions'\nAS $function$\ndeclare\n  k text; h text; bid uuid; comps jsonb;\n  actor_is_superadmin boolean;\nbegin\n  if not public.is_admin() then raise exception 'admin required'; end if;\n\n  select exists(\n    select 1\n    from public.staff_members sm\n    join public.staff_member_groups smg on smg.user_id=sm.user_id\n    join public.staff_groups sg on sg.id=smg.group_id\n    where sm.user_id=auth.uid()\n      and sm.status='active'\n      and sg.slug='superadmin'\n  ) into actor_is_superadmin;\n\n  if p_superadmin_override and not actor_is_superadmin then\n    raise exception 'Superadmin required for licence override';\n  end if;\n\n  comps:=coalesce(p_components,'{}'::jsonb);\n  comps:=(comps-'orbitfs_panel'-'orbitfs_sorter')\n    || case when comps ? 'orbitfs_panel'\n         then jsonb_build_object('orbitfs_base',coalesce((comps->>'orbitfs_panel')::boolean,false) or coalesce((comps->>'orbitfs_base')::boolean,false))\n         else '{}'::jsonb end\n    || case when comps ? 'orbitfs_sorter'\n         then jsonb_build_object('orbitfs_apex',coalesce((comps->>'orbitfs_sorter')::boolean,false) or coalesce((comps->>'orbitfs_apex')::boolean,false))\n         else '{}'::jsonb end;\n  comps:=comps||jsonb_build_object('orbitfs_base',true);\n\n  k:='OFS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'\n    ||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'\n    ||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'\n    ||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4));\n  h:=encode(digest(k,'sha256'),'hex');\n\n  insert into public.license_bindings(\n    auth_user_id,license_product_key,desired_state,remote_state,components,label,\n    license_key_hash,license_key_last4,expires_at,notes,api_source,admin_override\n  )\n  values(\n    p_user_id,'orbitfs_base','active','active',comps,\n    coalesce(nullif(trim(p_label),''),'OrbitFS licence'),\n    h,right(k,4),p_expires_at,p_notes,'website',p_superadmin_override\n  )\n  returning id into bid;\n\n  perform public.bump_license_revision();\n\n  insert into public.license_enforcement_queue(\n    binding_id,auth_user_id,action,reason,source,payload\n  )\n  values(\n    bid,p_user_id,'sync',\n    case when p_superadmin_override then 'website licence issued by Superadmin override' else 'website licence issued' end,\n    'website_engine',\n    jsonb_build_object('components',comps,'superadmin_override',p_superadmin_override)\n  );\n\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(\n    auth.uid(),\n    case when p_superadmin_override then 'license.superadmin_override_issued' else 'license.website_issued' end,\n    'license_binding',\n    bid::text,\n    jsonb_build_object('auth_user_id',p_user_id,'components',comps,'superadmin_override',p_superadmin_override)\n  );\n\n  return jsonb_build_object(\n    'binding_id',bid,\n    'license_key',k,\n    'last4',right(k,4),\n    'superadmin_override',p_superadmin_override\n  );\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_license_runtime_snapshot()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  result jsonb;\nbegin\n  if not (\n    public.is_admin()\n    or public.has_permission('admin.access')\n    or public.has_permission('settings.permissions')\n    or public.has_permission('license.manage')\n  ) then\n    raise exception 'admin permission required';\n  end if;\n\n  with runtime_ids as (\n    select installation_id,\n           max(last_seen_at) as last_seen_at,\n           min(registered_at) as registered_at,\n           max(device_name) filter (where device_name is not null) as device_name,\n           max(platform) filter (where platform is not null) as platform,\n           max(app_version) filter (where app_version is not null) as app_version,\n           true as registered\n      from public.license_installations\n     where installation_id is not null\n       and installation_id <> 'contract-test'\n     group by installation_id\n    union all\n    select v.installation_id,\n           max(v.created_at) as last_seen_at,\n           null::timestamptz as registered_at,\n           null::text as device_name,\n           null::text as platform,\n           null::text as app_version,\n           false as registered\n      from public.license_validation_log v\n     where v.installation_id is not null\n       and v.installation_id <> 'contract-test'\n       and not exists (\n         select 1 from public.license_installations i\n          where i.installation_id=v.installation_id\n       )\n     group by v.installation_id\n  ),\n  clients as (\n    select r.installation_id,\n           r.device_name,\n           r.platform,\n           r.app_version,\n           r.last_seen_at,\n           r.registered_at,\n           r.registered,\n           coalesce((\n             select jsonb_agg(distinct i.component_key order by i.component_key)\n               from public.license_installations i\n              where i.installation_id=r.installation_id\n                and i.component_key is not null\n           ),'[]'::jsonb) as components\n      from runtime_ids r\n  )\n  select jsonb_build_object(\n    'total',count(*),\n    'active_today',count(*) filter (where last_seen_at >= now()-interval '24 hours'),\n    'registered',count(*) filter (where registered),\n    'validation_only',count(*) filter (where not registered),\n    'component_registrations',(select count(*) from public.license_installations where installation_id <> 'contract-test'),\n    'clients',coalesce(jsonb_agg(to_jsonb(clients) order by last_seen_at desc),'[]'::jsonb)\n  )\n  into result\n  from clients;\n\n  return result;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_mark_gateway_verification(p_gateway_code text, p_ok boolean, p_error text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare gid uuid;\nbegin\n  if auth.role()<>'service_role' and not public.has_permission('payment_gateways.manage') then raise exception 'permission denied'; end if;\n  select id into gid from public.payment_gateways where code=p_gateway_code;\n  if gid is null then raise exception 'gateway not found'; end if;\n  update public.payment_gateway_setups set setup_status=case when p_ok then 'ready' else 'error' end,last_verified_at=case when p_ok then now() else last_verified_at end,last_verify_error=case when p_ok then null else p_error end,updated_at=now() where gateway_id=gid;\n  if not p_ok then update public.payment_gateways set enabled=false,updated_at=now() where id=gid; end if;\n  return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_orbitfs_release_system_snapshot()\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public', 'private'\nAS $function$\nselect case when public.has_permission('licenses.view') then\n  jsonb_build_object(\n    'settings',to_jsonb(s),\n    'supabase_client_secret_configured',exists(select 1 from private.orbitfs_release_secret_refs where key='supabase_client_secret'),\n    'vercel_client_secret_configured',exists(select 1 from private.orbitfs_release_secret_refs where key='vercel_client_secret'),\n    'panel_publish_token_configured',exists(select 1 from private.orbitfs_release_secret_refs where key='panel_publish_token'),\n    'installations',(select count(*) from public.orbitfs_installations),\n    'connected_supabase',(select count(*) from public.orbitfs_provider_connections where provider='supabase' and status='connected'),\n    'connected_vercel',(select count(*) from public.orbitfs_provider_connections where provider='vercel' and status='connected')\n  ) else '{}'::jsonb end\nfrom public.orbitfs_release_system_settings s where s.id='primary';\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_order_customer_snapshot(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$ declare o public.orders%rowtype; p public.user_profiles%rowtype; em text; begin if not public.has_permission('orders.view') then raise exception 'permission denied: orders.view'; end if; select * into o from public.orders where id=p_order_id; if not found then raise exception 'order not found'; end if; select * into p from public.user_profiles where id=o.auth_user_id; select email into em from auth.users where id=o.auth_user_id; return jsonb_build_object('id',p.id,'name',coalesce(nullif(p.display_name,''),nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),'Customer'),'first_name',p.first_name,'last_name',p.last_name,'email',em,'company',p.company_name,'phone',p.phone,'status',p.status,'role',p.role,'address_line1',p.address_line1,'address_line2',p.address_line2,'city',p.city,'state',p.state_region,'postcode',p.postal_code,'country',p.country_code,'currency',p.currency,'created_at',p.created_at,'last_login_at',p.last_login_at,'last_login_ip',p.last_login_ip); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_order_mail_recipient(p_order_id uuid)\n RETURNS text\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare e text;\nbegin\n  if not public.has_permission('orders.view') then raise exception 'permission denied: orders.view'; end if;\n  select coalesce(c.email,u.email) into e\n  from public.orders o\n  left join public.customers c on c.auth_user_id=o.auth_user_id\n  left join auth.users u on u.id=o.auth_user_id\n  where o.id=p_order_id;\n  return e;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_order_service_action(p_order_id uuid, p_action text, p_reason text DEFAULT NULL::text, p_reissue_license boolean DEFAULT true)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare o public.orders%rowtype; begin if p_action not in ('activate','reprovision','suspend','unsuspend','terminate') then raise exception 'invalid service action'; end if; if p_action in ('activate','reprovision') and not public.has_permission('orders.activate') then raise exception 'permission denied'; end if; if p_action in ('suspend','unsuspend') and not public.has_permission('orders.suspend') then raise exception 'permission denied'; end if; if p_action='terminate' and not public.has_permission('orders.terminate') then raise exception 'permission denied'; end if; select * into o from public.orders where id=p_order_id for update; if not found then raise exception 'order not found'; end if; if p_action in ('activate','reprovision') then if o.payment_status not like 'paid%' then raise exception 'order must be paid before activation'; end if; update public.orders set status='active',fulfillment_status='pending',updated_at=now() where id=o.id; update public.license_bindings set desired_state='active',remote_state=case when api_source='website' then 'active' else remote_state end,archived_at=null,suspension_reason=null,updated_at=now() where order_id=o.id and desired_state<>'revoked'; if p_reissue_license or p_action='reprovision' then perform public.grant_paid_order_entitlements(o.id,o.auth_user_id); else update public.order_items set service_status='active' where order_id=o.id; end if; elsif p_action='suspend' then if coalesce(btrim(p_reason),'')='' then raise exception 'suspension reason required'; end if; update public.orders set status='suspended',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('suspended_at',now(),'suspension_reason',p_reason),updated_at=now() where id=o.id; update public.order_items set service_status='suspended' where order_id=o.id; update public.license_bindings set desired_state='suspended',remote_state=case when api_source='website' then 'suspended' else remote_state end,suspension_reason=p_reason,updated_at=now() where order_id=o.id and archived_at is null; elsif p_action='unsuspend' then update public.orders set status='active',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('suspended_at',null,'suspension_reason',null),updated_at=now() where id=o.id; update public.order_items set service_status='active' where order_id=o.id; update public.license_bindings set desired_state='active',remote_state=case when api_source='website' then 'active' else remote_state end,suspension_reason=null,updated_at=now() where order_id=o.id and archived_at is null; elsif p_action='terminate' then if coalesce(btrim(p_reason),'')='' then raise exception 'termination reason required'; end if; update public.orders set status='terminated',fulfillment_status='terminated',terminated_at=coalesce(terminated_at,now()),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('terminated_at',now(),'termination_reason',p_reason,'recurring_enabled',false),updated_at=now() where id=o.id; update public.order_items set service_status='terminated' where order_id=o.id; update public.invoices set status='cancelled',notes=concat_ws(E'\\n',notes,'Order terminated: '||p_reason),updated_at=now() where order_id=o.id and status in ('unpaid','partial','overdue'); update public.license_bindings set desired_state='revoked',remote_state=case when api_source='website' then 'revoked' else remote_state end,archived_at=now(),suspension_reason=p_reason,updated_at=now() where order_id=o.id and archived_at is null; update public.download_entitlements set status='revoked',revoked_at=now(),reason='Order terminated: '||p_reason where order_id=o.id and status='active'; update public.license_enforcement_queue set state='cancelled',last_error='Order terminated before queued action completed',finished_at=coalesce(finished_at,now()) where binding_id in(select id from public.license_bindings where order_id=o.id) and state in ('queued','running'); end if; perform public.sync_order_service_status(o.id); perform public.bump_license_revision(); insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.service.'||p_action,'order',o.id::text,jsonb_build_object('reason',p_reason,'reissue_license',p_reissue_license)); return jsonb_build_object('ok',true,'action',p_action,'order_id',o.id); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_order_service_action(p_order_id uuid, p_action text, p_reason text DEFAULT NULL::text, p_reissue_license boolean DEFAULT true, p_suspend_until timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare o public.orders%rowtype;\nbegin\n  if p_action not in ('activate','reprovision','suspend','unsuspend','terminate') then raise exception 'invalid service action'; end if;\n  if p_action in ('activate','reprovision') and not public.has_permission('orders.activate') then raise exception 'permission denied'; end if;\n  if p_action in ('suspend','unsuspend') and not public.has_permission('orders.suspend') then raise exception 'permission denied'; end if;\n  if p_action='terminate' and not public.has_permission('orders.terminate') then raise exception 'permission denied'; end if;\n  select * into o from public.orders where id=p_order_id for update;\n  if not found then raise exception 'order not found'; end if;\n  if p_action in ('activate','reprovision') then\n    if o.payment_status not like 'paid%' then raise exception 'order must be paid before activation'; end if;\n    update public.orders set status='active',fulfillment_status='pending',updated_at=now() where id=o.id;\n    update public.license_bindings set desired_state='active',remote_state=case when api_source='website' then 'active' else remote_state end,archived_at=null,suspension_reason=null,updated_at=now() where order_id=o.id and desired_state<>'revoked';\n    if p_reissue_license or p_action='reprovision' then perform public.grant_paid_order_entitlements(o.id,o.auth_user_id); else update public.order_items set service_status='active' where order_id=o.id; end if;\n  elsif p_action='suspend' then\n    if coalesce(btrim(p_reason),'')='' then raise exception 'suspension reason required'; end if;\n    update public.orders set status='suspended',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('suspended_at',now(),'suspension_reason',p_reason,'suspension_until',p_suspend_until),updated_at=now() where id=o.id;\n    update public.order_items set service_status='suspended' where order_id=o.id;\n    update public.license_bindings set desired_state='suspended',remote_state=case when api_source='website' then 'suspended' else remote_state end,suspension_reason=p_reason,updated_at=now() where order_id=o.id and archived_at is null;\n  elsif p_action='unsuspend' then\n    update public.orders set status='active',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('suspended_at',null,'suspension_reason',null,'suspension_until',null),updated_at=now() where id=o.id;\n    update public.order_items set service_status='active' where order_id=o.id;\n    update public.license_bindings set desired_state='active',remote_state=case when api_source='website' then 'active' else remote_state end,suspension_reason=null,updated_at=now() where order_id=o.id and archived_at is null;\n  elsif p_action='terminate' then\n    if coalesce(btrim(p_reason),'')='' then raise exception 'termination reason required'; end if;\n    update public.orders set status='terminated',fulfillment_status='terminated',terminated_at=coalesce(terminated_at,now()),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('terminated_at',now(),'termination_reason',p_reason,'recurring_enabled',false),updated_at=now() where id=o.id;\n    update public.order_items set service_status='terminated' where order_id=o.id;\n    update public.invoices set status='cancelled',notes=concat_ws(E'\\n',notes,'Order terminated: '||p_reason),updated_at=now() where order_id=o.id and status in ('unpaid','partial','overdue');\n    update public.license_bindings set desired_state='revoked',remote_state=case when api_source='website' then 'revoked' else remote_state end,archived_at=now(),suspension_reason=p_reason,updated_at=now() where order_id=o.id and archived_at is null;\n    update public.download_entitlements set status='revoked',revoked_at=now(),reason='Order terminated: '||p_reason where order_id=o.id and status='active';\n    update public.license_enforcement_queue set state='cancelled',last_error='Order terminated before queued action completed',finished_at=coalesce(finished_at,now()) where binding_id in(select id from public.license_bindings where order_id=o.id) and state in ('queued','running');\n  end if;\n  perform public.sync_order_service_status(o.id);\n  perform public.bump_license_revision();\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.service.'||p_action,'order',o.id::text,jsonb_build_object('reason',p_reason,'reissue_license',p_reissue_license,'suspend_until',p_suspend_until));\n  return jsonb_build_object('ok',true,'action',p_action,'order_id',o.id);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_queue_license_action(target_binding uuid, action_name text, why text DEFAULT NULL::text, payload_data jsonb DEFAULT '{}'::jsonb)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare qid bigint; b public.license_bindings%rowtype; begin if public.current_role() not in ('admin','superadmin') then raise exception 'admin required'; end if; select * into b from public.license_bindings where id=target_binding; if not found then raise exception 'binding not found'; end if; insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,payload,source) values(b.id,b.auth_user_id,b.license_id,action_name,why,payload_data,'manual_admin') returning id into qid; if action_name='block' then update public.license_bindings set desired_state='blocked',suspension_reason=coalesce(why,'manual block'),updated_at=now() where id=b.id; elsif action_name='unblock' then update public.license_bindings set desired_state='active',suspension_reason=null,updated_at=now() where id=b.id; elsif action_name='revoke' then update public.license_bindings set desired_state='revoked',suspension_reason=coalesce(why,'manual revoke'),updated_at=now() where id=b.id; end if; return qid; end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_record_external_refund(p_invoice_id uuid, p_payment_id uuid, p_amount_cents bigint, p_external_reference text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare inv public.invoices%rowtype; pay public.invoice_payments%rowtype; refunded bigint; rid uuid; raw_status text; st text;\nbegin\n if auth.role()<>'service_role' and not public.has_permission('invoices.edit') then raise exception 'permission denied'; end if;\n select * into inv from public.invoices where id=p_invoice_id for update; if not found then raise exception 'invoice not found'; end if;\n select * into pay from public.invoice_payments where id=p_payment_id and invoice_id=inv.id; if not found then raise exception 'payment not found'; end if;\n select coalesce(sum(amount_cents),0) into refunded from public.invoice_refunds where invoice_id=inv.id and status in ('pending','processing','completed','succeeded');\n if p_amount_cents<=0 or p_amount_cents>greatest(0,inv.paid_cents-refunded) or p_amount_cents>pay.amount_cents then raise exception 'refund amount exceeds refundable balance'; end if;\n raw_status:=lower(coalesce(p_metadata->>'status','succeeded'));\n st:=case when raw_status in ('succeeded','completed') then 'succeeded' when raw_status in ('pending','processing') then 'pending' when raw_status in ('failed','canceled','cancelled') then 'failed' else 'pending' end;\n insert into public.invoice_refunds(invoice_id,payment_id,auth_user_id,method,amount_cents,status,external_reference,reason,created_by,metadata) values(inv.id,pay.id,inv.auth_user_id,pay.method,p_amount_cents,st,p_external_reference,p_reason,auth.uid(),coalesce(p_metadata,'{}'::jsonb)) returning id into rid;\n update public.invoices set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('refunded_cents',refunded+case when st in ('pending','processing','completed','succeeded') then p_amount_cents else 0 end,'last_refund_method',pay.method),updated_at=now() where id=inv.id;\n return jsonb_build_object('ok',true,'refund_id',rid,'amount_cents',p_amount_cents,'status',st);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_record_invoice_payment(p_invoice_id uuid, p_amount_cents bigint, p_method text DEFAULT 'manual'::text, p_reference text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare inv public.invoices%rowtype; new_paid bigint; begin if not public.has_permission('invoices.record_payment') then raise exception 'permission denied: invoices.record_payment'; end if; if p_amount_cents<=0 then raise exception 'payment must be positive'; end if; select * into inv from public.invoices where id=p_invoice_id for update; if not found then raise exception 'invoice not found'; end if; if inv.status in ('void','cancelled') then raise exception 'invoice is not payable'; end if; if inv.paid_cents+p_amount_cents>inv.total_cents then raise exception 'payment exceeds amount due'; end if; insert into public.invoice_payments(invoice_id,auth_user_id,method,amount_cents,status,external_reference,metadata) values(inv.id,inv.auth_user_id,p_method,p_amount_cents,'completed',p_reference,jsonb_build_object('recorded_by',auth.uid())); new_paid:=inv.paid_cents+p_amount_cents; update public.invoices set paid_cents=new_paid,status=case when new_paid>=total_cents then 'paid' else 'partial' end,paid_at=case when new_paid>=total_cents then now() else paid_at end,updated_at=now() where id=inv.id; if new_paid>=inv.total_cents then update public.orders set payment_status='paid',status='active',updated_at=now() where id=inv.order_id; end if; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'invoice.payment','invoice',inv.id::text,jsonb_build_object('amount_cents',p_amount_cents,'method',p_method)); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_refund_context(p_invoice_id uuid, p_payment_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare inv public.invoices%rowtype; pay public.invoice_payments%rowtype; refunded bigint;\nbegin\n if not public.has_permission('invoices.edit') then raise exception 'permission denied: invoices.edit'; end if;\n select * into inv from public.invoices where id=p_invoice_id; if not found then raise exception 'invoice not found'; end if;\n if p_payment_id is not null then select * into pay from public.invoice_payments where id=p_payment_id and invoice_id=inv.id and status='completed';\n else select * into pay from public.invoice_payments where invoice_id=inv.id and status='completed' and method in ('stripe','paypal') order by created_at desc limit 1; end if;\n if pay.id is null then raise exception 'no refundable original payment found'; end if;\n select coalesce(sum(amount_cents),0) into refunded from public.invoice_refunds where invoice_id=inv.id and status in ('pending','processing','completed','succeeded');\n return jsonb_build_object('invoice_id',inv.id,'invoice_number',inv.invoice_number,'payment_id',pay.id,'method',pay.method,'payment_amount_cents',pay.amount_cents,'provider_reference',pay.external_reference,'currency',inv.currency,'refundable_cents',greatest(0,least(pay.amount_cents,inv.paid_cents-refunded)));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_refund_invoice_to_wallet(p_invoice_id uuid, p_amount_cents bigint, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare inv public.invoices%rowtype; refunded bigint; newbal bigint; rid uuid;\nbegin\n if not public.has_permission('invoices.edit') then raise exception 'permission denied: invoices.edit'; end if;\n select * into inv from public.invoices where id=p_invoice_id for update; if not found then raise exception 'invoice not found'; end if;\n select coalesce(sum(amount_cents),0) into refunded from public.invoice_refunds where invoice_id=inv.id and status in ('pending','processing','completed','succeeded');\n if p_amount_cents<=0 or p_amount_cents>greatest(0,inv.paid_cents-refunded) then raise exception 'refund amount exceeds refundable balance'; end if;\n newbal:=public.wallet_credit(inv.auth_user_id,p_amount_cents,'Invoice refund to wallet','invoice_refund',inv.id::text,jsonb_build_object('invoice_number',inv.invoice_number,'reason',p_reason),auth.uid());\n insert into public.invoice_refunds(invoice_id,auth_user_id,method,amount_cents,status,reason,created_by,metadata) values(inv.id,inv.auth_user_id,'wallet',p_amount_cents,'completed',p_reason,auth.uid(),jsonb_build_object('balance_after_cents',newbal)) returning id into rid;\n update public.invoices set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('refunded_cents',refunded+p_amount_cents,'last_refund_method','wallet'),updated_at=now() where id=inv.id;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'invoice.refund_wallet','invoice',inv.id::text,jsonb_build_object('refund_id',rid,'amount_cents',p_amount_cents,'reason',p_reason));\n return jsonb_build_object('ok',true,'refund_id',rid,'amount_cents',p_amount_cents,'balance_cents',newbal);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_remove_gateway_secret(p_gateway_code text, p_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare gid uuid; refs jsonb;\nbegin\n  if not public.has_permission('payment_gateways.manage') then raise exception 'permission denied'; end if;\n  select id into gid from public.payment_gateways where code=p_gateway_code;\n  if gid is null then raise exception 'gateway not found'; end if;\n  select secret_refs into refs from public.payment_gateway_setups where gateway_id=gid for update;\n  update public.payment_gateway_setups set secret_refs=coalesce(secret_refs,'{}'::jsonb)-p_key,setup_status='credentials_saved',last_verified_at=null,last_verify_error=null,updated_by=auth.uid(),updated_at=now() where gateway_id=gid;\n  return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_remove_orbitfs_release_secret(p_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private'\nAS $function$\nbegin\n  if not (public.has_permission('licenses.manage') or public.has_permission('license_api.manage')) then raise exception 'permission denied'; end if;\n  delete from private.orbitfs_release_secret_refs where key=p_key;\n  return jsonb_build_object('ok',true,'key',p_key,'configured',false);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_remove_staff_member(p_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  target_is_superadmin boolean;\n  active_superadmins integer;\nbegin\n  if not (public.has_permission('staff.manage') or public.has_permission('settings.permissions')) then\n    raise exception 'Permission denied';\n  end if;\n  if p_user_id=auth.uid() then raise exception 'You cannot remove your own staff access'; end if;\n  if not exists(select 1 from public.staff_members where user_id=p_user_id) then raise exception 'Staff member not found'; end if;\n\n  select exists(\n    select 1 from public.staff_member_groups smg join public.staff_groups sg on sg.id=smg.group_id\n    where smg.user_id=p_user_id and sg.slug='superadmin'\n  ) into target_is_superadmin;\n\n  if target_is_superadmin then\n    select count(distinct sm.user_id) into active_superadmins\n    from public.staff_members sm\n    join public.staff_member_groups smg on smg.user_id=sm.user_id\n    join public.staff_groups sg on sg.id=smg.group_id\n    where sm.status='active' and sg.slug='superadmin';\n    if active_superadmins<=1 then raise exception 'Cannot remove the last active Superadmin'; end if;\n  end if;\n\n  delete from public.staff_members where user_id=p_user_id;\n  update public.user_profiles set role='user' where id=p_user_id;\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(auth.uid(),'staff.member_removed','staff_member',p_user_id,jsonb_build_object('customer_account_preserved',true));\n  return true;\nend$function$\n\nCREATE OR REPLACE FUNCTION public.admin_reply_and_close_support_ticket(p_ticket_id uuid, p_body text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare r jsonb; begin if not public.has_permission('support.close') then raise exception 'permission denied: support.close'; end if; r:=public.admin_reply_support_ticket(p_ticket_id,p_body,false); update public.support_tickets set status='closed',closed_at=now(),closed_by=auth.uid(),updated_at=now() where id=p_ticket_id; perform public.support_emit_system_message(p_ticket_id,'closing','{}'::jsonb); insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail) values(p_ticket_id,auth.uid(),'staff_closed','{}'::jsonb); return r||jsonb_build_object('closed',true,'status','closed'); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_reply_support_ticket(p_ticket_id uuid, p_body text, p_internal boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare mid uuid; begin if not public.has_permission('support.reply') and not public.has_permission('support.manage') then raise exception 'permission denied: support.reply'; end if; if nullif(btrim(p_body),'') is null then raise exception 'reply is required'; end if; if not exists(select 1 from public.support_tickets where id=p_ticket_id) then raise exception 'ticket not found'; end if; insert into public.support_ticket_messages(ticket_id,author_user_id,author_role,body,internal_note) values(p_ticket_id,auth.uid(),public.current_role(),p_body,p_internal) returning id into mid; if not p_internal then update public.support_tickets set status='customer_reply',last_reply_at=now(),last_staff_reply_at=now(),updated_at=now() where id=p_ticket_id; end if; return jsonb_build_object('ok',true,'message_id',mid,'status',case when p_internal then null else 'customer_reply' end); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_reply_ticket(p_ticket_id uuid, p_body text, p_internal boolean DEFAULT false, p_status text DEFAULT 'reviewing'::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare rid uuid; begin if public.current_role() not in ('support','admin','superadmin') then raise exception 'staff required'; end if; if length(trim(p_body))=0 then raise exception 'reply cannot be empty'; end if; insert into public.support_ticket_messages(ticket_id,author_user_id,author_role,body,internal_note) values(p_ticket_id,auth.uid(),public.current_role(),p_body,p_internal) returning id into rid; update public.support_tickets set status=case when p_internal then status else p_status end,last_staff_reply_at=case when p_internal then last_staff_reply_at else now() end,last_reply_at=case when p_internal then last_reply_at else now() end,updated_at=now(),closed_at=case when p_status='closed' then now() else null end where id=p_ticket_id; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),case when p_internal then 'ticket.note' else 'ticket.reply' end,'support_ticket',p_ticket_id::text,jsonb_build_object('message_id',rid,'status',p_status)); return jsonb_build_object('ok',true,'message_id',rid); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_review_order_cancellation(p_request_id uuid, p_decision text, p_staff_note text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare r public.order_cancellation_requests%rowtype; decision text:=lower(coalesce(p_decision,'')); sched timestamptz; result jsonb;\nbegin\n  if not public.has_permission('customers.cancellations') then raise exception 'permission denied: customers.cancellations'; end if;\n  if decision not in ('approve','deny') then raise exception 'invalid decision'; end if;\n  select * into r from public.order_cancellation_requests where id=p_request_id for update;\n  if not found then raise exception 'cancellation request not found'; end if;\n  if r.status<>'requested' then raise exception 'cancellation request has already been reviewed'; end if;\n  if decision='deny' then\n    update public.order_cancellation_requests set status='denied',staff_note=nullif(btrim(p_staff_note),''),reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now(),\n      refund_status=case when refund_amount_cents>0 then 'not_applicable' else refund_status end,refund_last_error=null\n      where id=r.id;\n    update public.orders set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cancellation_status','denied','scheduled_termination_at',null),updated_at=now() where id=r.order_id;\n    insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.cancellation.denied','order',r.order_id::text,jsonb_build_object('request_id',r.id,'staff_note',p_staff_note));\n    return jsonb_build_object('ok',true,'status','denied');\n  end if;\n  if r.requested_timing='immediate' then\n    if not public.has_permission('orders.terminate') then raise exception 'permission denied: orders.terminate'; end if;\n    result:=public.admin_order_service_action(r.order_id,'terminate',coalesce(nullif(btrim(p_staff_note),''),'Customer cancellation request approved'),false,null::timestamptz);\n    update public.payment_subscriptions set cancel_at_period_end=true,status='cancelled',next_charge_at=null,updated_at=now() where order_id=r.order_id and coalesce(status,'') not in ('cancelled','canceled','terminated','ended');\n    update public.order_cancellation_requests set status='completed',staff_note=nullif(btrim(p_staff_note),''),reviewed_by=auth.uid(),reviewed_at=now(),processed_at=now(),updated_at=now(),\n      refund_status=case when refund_amount_cents>0 then 'pending' else refund_status end,\n      refund_started_at=case when refund_amount_cents>0 then coalesce(refund_started_at,now()) else refund_started_at end,\n      refund_last_error=null\n      where id=r.id;\n    update public.orders set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cancellation_status','completed','cancellation_completed_at',now(),'scheduled_termination_at',null),updated_at=now() where id=r.order_id;\n    return jsonb_build_object('ok',true,'status','completed','termination',result,'refund_required',r.refund_amount_cents>0,'refund_preference',r.refund_preference,'refund_amount_cents',r.refund_amount_cents);\n  end if;\n  select next_charge_at into sched from public.payment_subscriptions where order_id=r.order_id and coalesce(status,'') not in ('cancelled','canceled','terminated','ended','inactive') order by created_at desc limit 1;\n  sched:=coalesce(r.scheduled_for,sched);\n  if sched is null then raise exception 'subscription billing cycle end is unavailable'; end if;\n  update public.payment_subscriptions set cancel_at_period_end=true,updated_at=now() where order_id=r.order_id and coalesce(status,'') not in ('cancelled','canceled','terminated','ended');\n  update public.order_cancellation_requests set status='approved_scheduled',scheduled_for=sched,staff_note=nullif(btrim(p_staff_note),''),reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=r.id;\n  update public.orders set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cancellation_status','approved_scheduled','scheduled_termination_at',sched,'recurring_enabled',false),updated_at=now() where id=r.order_id;\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.cancellation.scheduled','order',r.order_id::text,jsonb_build_object('request_id',r.id,'scheduled_for',sched,'staff_note',p_staff_note));\n  return jsonb_build_object('ok',true,'status','approved_scheduled','scheduled_for',sched);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_review_paid_order(p_order_id uuid, p_decision text, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare o public.orders%rowtype; inv public.invoices%rowtype; pay record; refunded bigint:=0; external_refund bigint:=0; bal bigint; begin\n if not public.has_permission('orders.approve') then raise exception 'permission denied'; end if;\n if p_decision not in ('approve','deny') then raise exception 'decision must be approve or deny'; end if;\n select * into o from public.orders where id=p_order_id for update; if not found then raise exception 'order not found'; end if;\n if o.status<>'pending_approval' or o.fulfillment_status<>'pending_approval' then raise exception 'order is not awaiting approval'; end if;\n select * into inv from public.invoices where order_id=o.id and status='paid' order by created_at desc limit 1 for update; if not found then raise exception 'paid invoice not found'; end if;\n if p_decision='approve' then\n   update public.orders set status='active',fulfillment_status='pending',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('approval_state','approved','approved_at',now(),'approved_by',auth.uid()),updated_at=now() where id=o.id;\n   update public.order_items set service_status='pending',updated_at=now() where order_id=o.id;\n   perform public.grant_paid_order_entitlements(o.id,o.auth_user_id);\n   insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.approval.approve','order',o.id::text,jsonb_build_object('reason',p_reason));\n   return jsonb_build_object('ok',true,'decision','approve','order_id',o.id);\n end if;\n if coalesce(btrim(p_reason),'')='' then raise exception 'denial reason required'; end if;\n for pay in select * from public.invoice_payments where invoice_id=inv.id and status='completed' order by created_at loop\n   if pay.method='account_credit' then\n     update public.account_balances set available_cents=available_cents+pay.amount_cents,lifetime_credit_cents=lifetime_credit_cents+pay.amount_cents,updated_at=now() where user_id=o.auth_user_id returning available_cents into bal;\n     insert into public.credit_ledger(user_id,direction,amount_cents,balance_after_cents,reason,reference_type,reference_id,created_by) values(o.auth_user_id,'credit',pay.amount_cents,bal,'Refund for denied order','invoice',inv.id::text,auth.uid());\n     update public.invoice_payments set status='refunded',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('refunded_at',now(),'refund_reason',p_reason,'refunded_by',auth.uid()) where id=pay.id;\n     refunded:=refunded+pay.amount_cents;\n   elsif pay.method in ('admin_override','free','coupon') then\n     update public.invoice_payments set status='refunded',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('refunded_at',now(),'refund_reason',p_reason,'noncash',true) where id=pay.id;\n   else\n     update public.invoice_payments set status='refund_pending',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('refund_requested_at',now(),'refund_reason',p_reason,'refund_requested_by',auth.uid()) where id=pay.id;\n     update public.payment_attempts set status='refund_pending',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('refund_reason',p_reason,'refund_requested_at',now()) where invoice_id=inv.id and status='completed' and amount_cents=pay.amount_cents;\n     external_refund:=external_refund+pay.amount_cents;\n   end if;\n end loop;\n update public.invoices set status='refunded',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('refund_reason',p_reason,'refund_pending_cents',external_refund),updated_at=now() where id=inv.id;\n update public.orders set status='terminated',payment_status='refunded',fulfillment_status='terminated',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('approval_state','denied','denied_at',now(),'denied_by',auth.uid(),'denial_reason',p_reason,'refund_pending_cents',external_refund),updated_at=now() where id=o.id;\n update public.order_items set service_status='terminated',updated_at=now() where order_id=o.id;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.approval.deny','order',o.id::text,jsonb_build_object('reason',p_reason,'refunded_cents',refunded,'refund_pending_cents',external_refund));\n return jsonb_build_object('ok',true,'decision','deny','order_id',o.id,'refunded_cents',refunded,'refund_pending_cents',external_refund);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_rotate_website_license(p_binding_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'extensions'\nAS $function$ declare k text; begin if not public.is_admin() then raise exception 'admin required'; end if; k:='OFS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4)); update public.license_bindings set license_key_hash=encode(digest(k,'sha256'),'hex'),license_key_last4=right(k,4),updated_at=now() where id=p_binding_id and api_source='website'; if not found then raise exception 'website licence not found'; end if; delete from public.license_installations where binding_id=p_binding_id; perform public.bump_license_revision(); return jsonb_build_object('license_key',k,'last4',right(k,4)); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_save_staff_member(p_user_id uuid, p_title text, p_department text, p_staff_notes text, p_status text, p_group_ids uuid[], p_primary_group_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  existing_staff boolean;\n  includes_superadmin boolean;\n  includes_admin boolean;\n  target_was_superadmin boolean;\n  active_superadmins integer;\n  primary_id uuid;\n  primary_slug text;\n  legacy_role text;\nbegin\n  if p_user_id is null or not exists(select 1 from auth.users where id=p_user_id) then raise exception 'User not found'; end if;\n  existing_staff := exists(select 1 from public.staff_members where user_id=p_user_id);\n\n  if existing_staff then\n    if not (public.has_permission('staff.manage') or public.has_permission('settings.permissions')) then raise exception 'Permission denied'; end if;\n  else\n    if not (public.has_permission('staff.invite') or public.has_permission('settings.permissions')) then raise exception 'Permission denied'; end if;\n  end if;\n\n  if p_status not in ('active','disabled') then raise exception 'Invalid staff status'; end if;\n  if p_group_ids is null or coalesce(array_length(p_group_ids,1),0)=0 then raise exception 'At least one staff group is required'; end if;\n  if exists(select 1 from unnest(p_group_ids) g left join public.staff_groups sg on sg.id=g where sg.id is null) then raise exception 'Invalid staff group'; end if;\n\n  select exists(select 1 from public.staff_groups where id=any(p_group_ids) and slug='superadmin') into includes_superadmin;\n  select exists(select 1 from public.staff_groups where id=any(p_group_ids) and slug='admin') into includes_admin;\n\n  if includes_superadmin and not public.has_permission('settings.permissions') then raise exception 'Only permission administrators can assign Superadmin'; end if;\n  if p_user_id=auth.uid() and p_status='disabled' then raise exception 'You cannot disable your own staff access'; end if;\n\n  select exists(\n    select 1 from public.staff_member_groups smg\n    join public.staff_groups sg on sg.id=smg.group_id\n    where smg.user_id=p_user_id and sg.slug='superadmin'\n  ) into target_was_superadmin;\n\n  if target_was_superadmin and (p_status='disabled' or not includes_superadmin) then\n    select count(distinct sm.user_id) into active_superadmins\n    from public.staff_members sm\n    join public.staff_member_groups smg on smg.user_id=sm.user_id\n    join public.staff_groups sg on sg.id=smg.group_id\n    where sm.status='active' and sg.slug='superadmin';\n    if active_superadmins<=1 then raise exception 'Cannot remove or disable the last active Superadmin'; end if;\n  end if;\n\n  primary_id := case when p_primary_group_id=any(p_group_ids) then p_primary_group_id else p_group_ids[1] end;\n  select slug into primary_slug from public.staff_groups where id=primary_id;\n\n  -- Staff Groups remain authoritative; preserve the distinct built-in legacy roles.\n  legacy_role := case\n    when includes_superadmin then 'superadmin'\n    when includes_admin then 'admin'\n    when primary_slug='senior-support' then 'senior-support'\n    else 'support'\n  end;\n\n  insert into public.staff_members(user_id,status,title,department,staff_notes,created_by,updated_at)\n  values(p_user_id,p_status,nullif(trim(coalesce(p_title,'')),''),nullif(trim(coalesce(p_department,'')),''),nullif(trim(coalesce(p_staff_notes,'')),''),auth.uid(),now())\n  on conflict(user_id) do update\n    set status=excluded.status,title=excluded.title,department=excluded.department,staff_notes=excluded.staff_notes,updated_at=now();\n\n  delete from public.staff_member_groups where user_id=p_user_id;\n  insert into public.staff_member_groups(user_id,group_id,is_primary)\n  select p_user_id,g,(g=primary_id) from unnest(p_group_ids) g;\n\n  update public.user_profiles set role=legacy_role where id=p_user_id;\n\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(auth.uid(),case when existing_staff then 'staff.member_updated' else 'staff.member_saved' end,'staff_member',p_user_id,\n    jsonb_build_object('groups',p_group_ids,'primary_group_id',primary_id,'primary_group_slug',primary_slug,'legacy_role',legacy_role,'status',p_status));\n\n  return jsonb_build_object('ok',true,'user_id',p_user_id,'primary_group_id',primary_id,'primary_role',primary_slug,'legacy_role',legacy_role);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_save_support_department(p_id uuid, p_name text, p_slug text, p_description text, p_email text, p_enabled boolean, p_client_can_close boolean, p_auto_close_hours integer, p_sort_order integer)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare did uuid; clean_slug text;\nbegin\n if not (public.has_permission('support.settings') or public.has_permission('support.departments.manage')) then raise exception 'permission denied: support.departments.manage'; end if;\n if nullif(trim(coalesce(p_name,'')),'') is null then raise exception 'department name is required'; end if;\n clean_slug:=lower(regexp_replace(coalesce(nullif(trim(p_slug),''),trim(p_name)),'[^a-zA-Z0-9]+','-','g')); clean_slug:=trim(both '-' from clean_slug); if clean_slug='' then raise exception 'department slug is required'; end if;\n if p_id is null then insert into public.support_departments(name,slug,description,email,enabled,client_can_close,auto_close_hours,sort_order) values(trim(p_name),clean_slug,nullif(trim(coalesce(p_description,'')),''),nullif(trim(coalesce(p_email,'')),''),coalesce(p_enabled,true),coalesce(p_client_can_close,true),case when p_auto_close_hours is null or p_auto_close_hours<=0 then null else p_auto_close_hours end,coalesce(p_sort_order,100)) returning id into did;\n else update public.support_departments set name=trim(p_name),slug=clean_slug,description=nullif(trim(coalesce(p_description,'')),''),email=nullif(trim(coalesce(p_email,'')),''),enabled=coalesce(p_enabled,true),client_can_close=coalesce(p_client_can_close,true),auto_close_hours=case when p_auto_close_hours is null or p_auto_close_hours<=0 then null else p_auto_close_hours end,sort_order=coalesce(p_sort_order,100),updated_at=now() where id=p_id returning id into did; if did is null then raise exception 'department not found'; end if; end if;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'support.department.save','support_department',did::text,jsonb_build_object('name',trim(p_name),'slug',clean_slug)); return did;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_send_support_system_message(p_ticket_id uuid, p_event_key text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ begin if not public.has_permission('support.reply') then raise exception 'permission denied: support.reply'; end if; if not exists(select 1 from public.support_tickets where id=p_ticket_id) then raise exception 'ticket not found'; end if; if not exists(select 1 from public.support_message_templates where event_key=p_event_key and enabled=true) then raise exception 'message template unavailable'; end if; perform public.support_emit_system_message(p_ticket_id,p_event_key,'{}'::jsonb); insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail) values(p_ticket_id,auth.uid(),'manual_system_message',jsonb_build_object('event_key',p_event_key)); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_set_account_enforcement(target_user uuid, new_state text, why text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select public.admin_set_account_enforcement_v2(target_user,new_state,why,null)\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_set_account_enforcement_v2(target_user uuid, new_state text, why text DEFAULT NULL::text, expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  target_role text;\n  changed_ids uuid[];\nbegin\n  if not public.has_permission('customers.enforce') then raise exception 'permission denied: customers.enforce'; end if;\n  if target_user=auth.uid() then raise exception 'you cannot enforce your own account'; end if;\n  select role into target_role from public.user_profiles where id=target_user;\n  if target_role is null then raise exception 'customer not found'; end if;\n  if target_role='superadmin' and public.current_role()<>'superadmin' then raise exception 'only superadmin can enforce another superadmin'; end if;\n  if new_state not in ('active','suspended','banned') then raise exception 'invalid state'; end if;\n  if new_state<>'active' and nullif(trim(coalesce(why,'')),'') is null then raise exception 'reason is required'; end if;\n  if expires_at is not null and expires_at<=now() then raise exception 'expiry must be in the future'; end if;\n\n  if new_state='active' then\n    update public.user_profiles\n       set status='active',suspension_reason=null,suspended_at=null,suspension_expires_at=null,\n           banned_at=null,ban_reason=null,ban_expires_at=null,updated_at=now()\n     where id=target_user;\n\n    with restored as (\n      update public.license_bindings\n         set desired_state='active',\n             remote_state=case when api_source='website' then 'active' else remote_state end,\n             suspension_reason=null,\n             updated_at=now()\n       where auth_user_id=target_user\n         and archived_at is null\n         and desired_state='suspended'\n         and suspension_reason like 'account_enforcement:%'\n       returning id,auth_user_id,license_id,api_source\n    )\n    select array_agg(id) into changed_ids from restored;\n\n    insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source)\n    select b.id,b.auth_user_id,b.license_id,'unblock','account enforcement cleared','account_enforcement'\n      from public.license_bindings b\n     where b.id=any(coalesce(changed_ids,'{}'::uuid[]))\n       and b.api_source<>'website'\n       and not exists(select 1 from public.license_enforcement_queue q where q.binding_id=b.id and q.action='unblock' and q.state in ('queued','running'));\n\n  elsif new_state='suspended' then\n    update public.user_profiles\n       set status='suspended',suspension_reason=trim(why),suspended_at=now(),suspension_expires_at=expires_at,\n           banned_at=null,ban_reason=null,ban_expires_at=null,updated_at=now()\n     where id=target_user;\n\n    with changed as (\n      update public.license_bindings\n         set desired_state='suspended',\n             remote_state=case when api_source='website' then 'suspended' else remote_state end,\n             suspension_reason='account_enforcement:suspended:'||trim(why),\n             updated_at=now()\n       where auth_user_id=target_user and archived_at is null and desired_state='active'\n       returning id,auth_user_id,license_id,api_source\n    )\n    select array_agg(id) into changed_ids from changed;\n\n    insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source)\n    select b.id,b.auth_user_id,b.license_id,'block','account suspended: '||trim(why),'account_enforcement'\n      from public.license_bindings b\n     where b.id=any(coalesce(changed_ids,'{}'::uuid[]))\n       and b.api_source<>'website'\n       and not exists(select 1 from public.license_enforcement_queue q where q.binding_id=b.id and q.action='block' and q.state in ('queued','running'));\n\n  else\n    update public.user_profiles\n       set status='suspended',suspension_reason=null,suspended_at=coalesce(suspended_at,now()),suspension_expires_at=null,\n           banned_at=now(),ban_reason=trim(why),ban_expires_at=expires_at,updated_at=now()\n     where id=target_user;\n\n    with changed as (\n      update public.license_bindings\n         set desired_state='suspended',\n             remote_state=case when api_source='website' then 'suspended' else remote_state end,\n             suspension_reason='account_enforcement:banned:'||trim(why),\n             updated_at=now()\n       where auth_user_id=target_user and archived_at is null and desired_state='active'\n       returning id,auth_user_id,license_id,api_source\n    )\n    select array_agg(id) into changed_ids from changed;\n\n    insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source)\n    select b.id,b.auth_user_id,b.license_id,'block','account banned: '||trim(why),'account_enforcement'\n      from public.license_bindings b\n     where b.id=any(coalesce(changed_ids,'{}'::uuid[]))\n       and b.api_source<>'website'\n       and not exists(select 1 from public.license_enforcement_queue q where q.binding_id=b.id and q.action='block' and q.state in ('queued','running'));\n  end if;\n\n  if coalesce(array_length(changed_ids,1),0)>0 then perform public.bump_license_revision(); end if;\n\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(auth.uid(),'customer.enforcement','user',target_user::text,\n    jsonb_build_object('state',new_state,'reason',why,'expires_at',expires_at,'license_bindings_changed',coalesce(array_length(changed_ids,1),0)));\n\n  return jsonb_build_object('ok',true,'state',new_state,'reason',why,'expires_at',expires_at,'license_bindings_changed',coalesce(array_length(changed_ids,1),0));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_set_billing_state(p_order_id uuid, p_state text, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare o public.orders%rowtype; inv public.invoices%rowtype; rem bigint; old_state text; begin if not public.has_permission('orders.edit') then raise exception 'permission denied: orders.edit'; end if; if p_state not in ('unpaid','overdue','paid','apaid','suspended','cancelled') then raise exception 'invalid billing state'; end if; select * into o from public.orders where id=p_order_id for update; if not found then raise exception 'order not found'; end if; select * into inv from public.invoices where order_id=p_order_id order by created_at desc limit 1 for update; if not found then raise exception 'invoice not found'; end if; old_state:=case when o.status='terminated' or inv.status in ('cancelled','void') then 'cancelled' when o.status='suspended' then 'suspended' when o.payment_status='paid_admin_override' then 'apaid' when o.payment_status like 'paid%' or inv.status='paid' then 'paid' when inv.status='overdue' or o.payment_status='overdue' then 'overdue' else 'unpaid' end; if old_state in ('paid','apaid','suspended','cancelled') and p_state<>old_state and not public.has_permission('billing.override_state') then raise exception 'permission denied: billing.override_state'; end if; if p_state='unpaid' then update public.invoices set status='unpaid',paid_cents=0,paid_at=null,updated_at=now() where id=inv.id; update public.orders set status='pending_payment',payment_status='unpaid',fulfillment_status=case when fulfillment_status='fulfilled' then 'held' else fulfillment_status end,updated_at=now() where id=o.id; elsif p_state='overdue' then update public.invoices set status='overdue',updated_at=now() where id=inv.id; update public.orders set status='pending_payment',payment_status='overdue',updated_at=now() where id=o.id; elsif p_state='paid' then if coalesce(inv.paid_cents,0)<coalesce(inv.total_cents,0) then raise exception 'invoice is not fully paid; record payment or use APAID override'; end if; update public.invoices set status='paid',paid_at=coalesce(paid_at,now()),updated_at=now() where id=inv.id; update public.orders set status='active',payment_status='paid',updated_at=now() where id=o.id; elsif p_state='apaid' then if not public.has_permission('orders.override_payment') then raise exception 'permission denied: orders.override_payment'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'APAID override reason is required'; end if; rem:=greatest(inv.total_cents-coalesce(inv.paid_cents,0),0); if rem>0 then insert into public.invoice_payments(invoice_id,auth_user_id,method,amount_cents,status,external_reference,metadata) values(inv.id,inv.auth_user_id,'admin_override',rem,'completed','ADMIN-OVERRIDE',jsonb_build_object('reason',p_reason,'actor',auth.uid(),'state_override',true)); end if; update public.invoices set status='paid',paid_cents=total_cents,paid_at=coalesce(paid_at,now()),updated_at=now() where id=inv.id; update public.orders set status='active',payment_status='paid_admin_override',updated_at=now() where id=o.id; elsif p_state='suspended' then if exists(select 1 from public.license_bindings where auth_user_id=o.auth_user_id and desired_state<>'revoked') and not public.has_permission('licenses.enforce') then raise exception 'permission denied: licenses.enforce'; end if; update public.invoices set status=case when status='paid' then status else 'overdue' end,updated_at=now() where id=inv.id; update public.orders set status='suspended',updated_at=now() where id=o.id; update public.license_bindings set desired_state='blocked',suspension_reason=coalesce(p_reason,'order suspended'),updated_at=now() where auth_user_id=o.auth_user_id and desired_state<>'revoked'; elsif p_state='cancelled' then if not public.has_permission('invoices.void') and not public.has_permission('billing.override_state') then raise exception 'permission denied: invoices.void'; end if; update public.invoices set status='cancelled',updated_at=now() where id=inv.id; update public.orders set status='terminated',payment_status=case when payment_status like 'paid%' then payment_status else 'cancelled' end,fulfillment_status='terminated',updated_at=now() where id=o.id; update public.license_bindings set desired_state='blocked',suspension_reason=coalesce(p_reason,'order terminated'),updated_at=now() where order_id=o.id and desired_state<>'revoked'; end if; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'billing.state_override','order',o.id::text,jsonb_build_object('from',old_state,'to',p_state,'reason',p_reason)); return jsonb_build_object('ok',true,'state',p_state); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_set_invoice_billing_state(p_invoice_id uuid, p_state text, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  inv public.invoices%rowtype;\n  rem bigint;\n  old_state text;\nbegin\n  if p_state not in ('unpaid','overdue','paid','apaid','suspended','cancelled') then\n    raise exception 'invalid billing state';\n  end if;\n\n  select * into inv\n  from public.invoices\n  where id=p_invoice_id\n  for update;\n\n  if not found then\n    raise exception 'invoice not found';\n  end if;\n\n  if inv.order_id is not null then\n    return public.admin_set_billing_state(inv.order_id,p_state,p_reason);\n  end if;\n\n  if not public.has_permission('invoices.edit') and not public.has_permission('orders.edit') then\n    raise exception 'permission denied: invoices.edit';\n  end if;\n\n  old_state:=case\n    when inv.status in ('cancelled','void') then 'cancelled'\n    when inv.status='paid' then 'paid'\n    when inv.status='overdue' then 'overdue'\n    else 'unpaid'\n  end;\n\n  if old_state in ('paid','cancelled') and p_state<>old_state\n     and not public.has_permission('billing.override_state') then\n    raise exception 'permission denied: billing.override_state';\n  end if;\n\n  if p_state='unpaid' then\n    update public.invoices\n    set status='unpaid',paid_cents=0,paid_at=null,updated_at=now()\n    where id=inv.id;\n\n  elsif p_state='overdue' then\n    update public.invoices\n    set status='overdue',updated_at=now()\n    where id=inv.id;\n\n  elsif p_state='paid' then\n    if coalesce(inv.paid_cents,0)<coalesce(inv.total_cents,0) then\n      raise exception 'invoice is not fully paid; record payment or use APAID override';\n    end if;\n    update public.invoices\n    set status='paid',paid_at=coalesce(paid_at,now()),updated_at=now()\n    where id=inv.id;\n\n  elsif p_state='apaid' then\n    if not public.has_permission('orders.override_payment') then\n      raise exception 'permission denied: orders.override_payment';\n    end if;\n    if nullif(trim(coalesce(p_reason,'')),'') is null then\n      raise exception 'APAID override reason is required';\n    end if;\n    rem:=greatest(coalesce(inv.total_cents,0)-coalesce(inv.paid_cents,0),0);\n    if rem>0 then\n      insert into public.invoice_payments(\n        invoice_id,auth_user_id,method,amount_cents,status,external_reference,metadata\n      ) values(\n        inv.id,inv.auth_user_id,'admin_override',rem,'completed','ADMIN-OVERRIDE',\n        jsonb_build_object('reason',p_reason,'actor',auth.uid(),'state_override',true,'standalone_invoice',true)\n      );\n    end if;\n    update public.invoices\n    set status='paid',paid_cents=total_cents,paid_at=coalesce(paid_at,now()),updated_at=now()\n    where id=inv.id;\n\n  elsif p_state='suspended' then\n    raise exception 'standalone invoices cannot be suspended because they have no linked order';\n\n  elsif p_state='cancelled' then\n    if not public.has_permission('invoices.void') and not public.has_permission('billing.override_state') then\n      raise exception 'permission denied: invoices.void';\n    end if;\n    update public.invoices\n    set status='cancelled',updated_at=now()\n    where id=inv.id;\n  end if;\n\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(\n    auth.uid(),'billing.state_override','invoice',inv.id::text,\n    jsonb_build_object('from',old_state,'to',p_state,'reason',p_reason,'standalone',true)\n  );\n\n  return jsonb_build_object('ok',true,'state',p_state,'invoice_id',inv.id,'standalone',true);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_set_staff_departments(p_user_id uuid, p_department_ids uuid[])\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare ids uuid[]:=coalesce(p_department_ids,'{}'::uuid[]);\nbegin\n  if not (public.has_permission('staff.manage') or public.has_permission('staff.invite') or public.has_permission('settings.permissions')) then\n    raise exception 'permission denied: staff department management';\n  end if;\n  if not exists(select 1 from public.staff_members where user_id=p_user_id) then raise exception 'staff member not found'; end if;\n  if exists(select 1 from unnest(ids) d left join public.support_departments sd on sd.id=d and sd.enabled=true where sd.id is null) then\n    raise exception 'one or more support departments are invalid';\n  end if;\n  delete from public.support_department_staff where user_id=p_user_id;\n  insert into public.support_department_staff(department_id,user_id,created_by)\n  select distinct d,p_user_id,auth.uid() from unnest(ids) d;\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(auth.uid(),'staff.departments_updated','staff_member',p_user_id::text,jsonb_build_object('department_ids',ids));\n  return jsonb_build_object('ok',true,'department_ids',to_jsonb(ids));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_set_support_department_members(p_department_id uuid, p_user_ids uuid[])\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid; count_added integer:=0; r integer; min_rank integer;\nbegin\n if not (public.has_permission('support.settings') or public.has_permission('support.departments.manage')) then raise exception 'permission denied: support.departments.manage'; end if;\n select min_support_rank into min_rank from public.support_departments where id=p_department_id;\n if min_rank is null then raise exception 'department not found'; end if;\n delete from public.support_department_staff where department_id=p_department_id;\n foreach uid in array coalesce(p_user_ids,'{}'::uuid[]) loop\n   r:=public.support_staff_rank(uid);\n   if r not in (1,2) then raise exception 'department membership is only for Support and Senior Support staff'; end if;\n   if r<min_rank then raise exception '% requires % or higher',p_department_id,public.support_staff_rank_label(min_rank); end if;\n   insert into public.support_department_staff(department_id,user_id,created_by) values(p_department_id,uid,auth.uid()) on conflict do nothing;\n   count_added:=count_added+1;\n end loop;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'support.department.members','support_department',p_department_id::text,jsonb_build_object('member_count',count_added,'user_ids',to_jsonb(coalesce(p_user_ids,'{}'::uuid[]))));\n return jsonb_build_object('ok',true,'member_count',count_added);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_set_support_department_routing(p_department_id uuid, p_allow_direct_create boolean, p_min_support_rank integer, p_escalation_department_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n if not (public.has_permission('support.settings') or public.has_permission('support.departments.manage')) then raise exception 'permission denied: support.departments.manage'; end if;\n if p_min_support_rank not between 1 and 4 then raise exception 'minimum support tier must be between 1 and 4'; end if;\n if p_escalation_department_id=p_department_id then raise exception 'department cannot escalate to itself'; end if;\n if p_escalation_department_id is not null and not exists(select 1 from public.support_departments where id=p_escalation_department_id and enabled=true) then raise exception 'escalation department not found'; end if;\n update public.support_departments set allow_direct_create=coalesce(p_allow_direct_create,true),min_support_rank=p_min_support_rank,escalation_department_id=p_escalation_department_id,updated_at=now() where id=p_department_id;\n if not found then raise exception 'department not found'; end if;\n delete from public.support_department_staff ds where ds.department_id=p_department_id and public.support_staff_rank(ds.user_id)<p_min_support_rank;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'support.department.routing','support_department',p_department_id::text,jsonb_build_object('allow_direct_create',p_allow_direct_create,'min_support_rank',p_min_support_rank,'escalation_department_id',p_escalation_department_id));\n return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_store_gateway_secret(p_gateway_code text, p_key text, p_value text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'vault'\nAS $function$\ndeclare gid uuid; sid uuid; refs jsonb; secname text;\nbegin\n  if not public.has_permission('payment_gateways.manage') then raise exception 'permission denied'; end if;\n  if nullif(btrim(coalesce(p_value,'')),'') is null then raise exception 'secret value required'; end if;\n  if p_key not in ('secret_key','webhook_secret','client_id','client_secret','webhook_id') then raise exception 'unsupported secret key'; end if;\n  select id into gid from public.payment_gateways where code=p_gateway_code;\n  if gid is null then raise exception 'gateway not found'; end if;\n  insert into public.payment_gateway_setups(gateway_id,updated_by) values(gid,auth.uid()) on conflict (gateway_id) do nothing;\n  select secret_refs into refs from public.payment_gateway_setups where gateway_id=gid for update;\n  sid := nullif(refs->>p_key,'')::uuid;\n  secname := 'orbitfs_gateway_'||regexp_replace(p_gateway_code,'[^a-zA-Z0-9_]+','_','g')||'_'||p_key;\n  if sid is null then\n    sid := vault.create_secret(p_value,secname,'OrbitFS payment gateway secret',null);\n  else\n    perform vault.update_secret(sid,p_value,secname,'OrbitFS payment gateway secret',null);\n  end if;\n  update public.payment_gateway_setups set secret_refs=jsonb_set(coalesce(secret_refs,'{}'::jsonb),array[p_key],to_jsonb(sid::text),true),setup_status='credentials_saved',last_verify_error=null,updated_by=auth.uid(),updated_at=now() where gateway_id=gid;\n  return jsonb_build_object('ok',true,'key',p_key,'configured',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_store_orbitfs_release_secret(p_key text, p_value text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private', 'vault'\nAS $function$\ndeclare sid uuid;\nbegin\n  if not (public.has_permission('licenses.manage') or public.has_permission('license_api.manage')) then raise exception 'permission denied'; end if;\n  if p_key not in ('supabase_client_secret','vercel_client_secret','panel_publish_token') then raise exception 'unsupported secret'; end if;\n  if nullif(btrim(coalesce(p_value,'')),'') is null then raise exception 'secret value required'; end if;\n  select secret_id into sid from private.orbitfs_release_secret_refs where key=p_key for update;\n  if sid is null then sid:=vault.create_secret(p_value,'orbitfs_release_'||p_key,'OrbitFS release system credential',null);\n  else perform vault.update_secret(sid,p_value,'orbitfs_release_'||p_key,'OrbitFS release system credential',null); end if;\n  insert into private.orbitfs_release_secret_refs(key,secret_id,updated_at) values(p_key,sid,now())\n  on conflict(key) do update set secret_id=excluded.secret_id,updated_at=now();\n  return jsonb_build_object('ok',true,'key',p_key,'configured',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_support_queue_snapshot()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); rank integer; tickets jsonb;\nbegin\n if uid is null or not public.has_permission('support.manage') then raise exception 'permission denied: support.manage'; end if;\n rank:=public.support_staff_rank(uid);\n select coalesce(jsonb_agg(to_jsonb(x) order by x.updated_at desc),'[]'::jsonb) into tickets\n from (\n   select t.id,t.ticket_number,t.user_id,t.department_id,t.assigned_to,t.claim_required,t.subject,t.status,t.priority,t.source,t.related_order_id,t.last_reply_at,t.created_at,t.updated_at,t.archived_at,t.escalation_level,t.escalation_reason,t.escalated_at,t.escalated_by,\n          d.name department_name,\n          coalesce(ap.display_name,trim(concat_ws(' ',ap.first_name,ap.last_name))) assigned_name,\n          case t.escalation_level when 3 then 'Superadmin' when 2 then 'Administrator' when 1 then 'Senior Support' else 'Support' end escalation_label\n   from public.support_tickets t\n   left join public.support_departments d on d.id=t.department_id\n   left join public.user_profiles ap on ap.id=t.assigned_to\n   where (rank>=3 or t.assigned_to=uid or public.support_user_has_department(uid,t.department_id) or (t.claim_required and rank>=2))\n     and t.escalation_level<=greatest(rank-1,0)\n ) x;\n return jsonb_build_object('tickets',tickets,'rank',rank,'rank_label',public.support_staff_rank_label(rank));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.admin_support_settings_snapshot()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare deps jsonb; people jsonb; templates jsonb;\nbegin\n if not (public.has_permission('support.settings') or public.has_permission('support.departments.manage')) then raise exception 'permission denied: support.departments.manage'; end if;\n select coalesce(jsonb_agg(jsonb_build_object(\n   'id',d.id,'name',d.name,'slug',d.slug,'description',d.description,'email',d.email,'enabled',d.enabled,\n   'client_can_close',d.client_can_close,'auto_close_hours',d.auto_close_hours,'sort_order',d.sort_order,\n   'allow_direct_create',d.allow_direct_create,'min_support_rank',d.min_support_rank,'escalation_department_id',d.escalation_department_id,\n   'member_ids',coalesce((select jsonb_agg(ds.user_id order by ds.created_at) from public.support_department_staff ds where ds.department_id=d.id),'[]'::jsonb)\n ) order by d.sort_order,d.name),'[]'::jsonb) into deps from public.support_departments d where d.enabled=true;\n select coalesce(jsonb_agg(jsonb_build_object('user_id',sm.user_id,'display_name',coalesce(up.display_name,trim(concat_ws(' ',up.first_name,up.last_name)),au.email,sm.user_id::text),'email',au.email,'title',sm.title,'status',sm.status,'rank',public.support_staff_rank(sm.user_id),'rank_label',public.support_staff_rank_label(public.support_staff_rank(sm.user_id))) order by public.support_staff_rank(sm.user_id) desc,coalesce(up.display_name,au.email)),'[]'::jsonb) into people from public.staff_members sm left join public.user_profiles up on up.id=sm.user_id left join auth.users au on au.id=sm.user_id where sm.status='active' and public.support_staff_rank(sm.user_id) in (1,2);\n select coalesce(jsonb_agg(to_jsonb(t) order by t.label),'[]'::jsonb) into templates from public.support_message_templates t;\n return jsonb_build_object('departments',deps,'staff',people,'templates',templates,'hierarchy',jsonb_build_array(\n   jsonb_build_object('rank',1,'slug','support','label','Support','description','Worker'),\n   jsonb_build_object('rank',2,'slug','senior-support','label','Senior Support','description','Supervisor'),\n   jsonb_build_object('rank',3,'slug','admin','label','Admin','description','Manager'),\n   jsonb_build_object('rank',4,'slug','superadmin','label','Superadmin','description','Boss / final escalation')));\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_unlock_website_license(p_binding_id uuid, p_component text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ begin if not public.is_admin() then raise exception 'admin required'; end if; if p_component is null then delete from public.license_installations where binding_id=p_binding_id; else delete from public.license_installations where binding_id=p_binding_id and component_key=p_component; end if; perform public.bump_license_revision(); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_gateway_setup(p_gateway_code text, p_environment text, p_currencies text[], p_webhook_config jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare gid uuid;\nbegin\n  if not public.has_permission('payment_gateways.manage') then raise exception 'permission denied'; end if;\n  if p_environment not in ('sandbox','live') then raise exception 'invalid environment'; end if;\n  select id into gid from public.payment_gateways where code=p_gateway_code;\n  if gid is null then raise exception 'gateway not found'; end if;\n  update public.payment_gateways set currencies=coalesce(p_currencies,array['AUD']::text[]),updated_at=now() where id=gid;\n  insert into public.payment_gateway_setups(gateway_id,environment,webhook_config,metadata,updated_by)\n  values(gid,p_environment,coalesce(p_webhook_config,'{}'::jsonb),coalesce(p_metadata,'{}'::jsonb),auth.uid())\n  on conflict (gateway_id) do update set environment=excluded.environment,webhook_config=excluded.webhook_config,metadata=excluded.metadata,updated_by=auth.uid(),updated_at=now();\n  return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_invoice_presentation(p_invoice_id uuid, p_presentation jsonb, p_reason text DEFAULT NULL::text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_old jsonb;\nbegin\n  if not public.has_permission('invoices.edit') then raise exception 'Permission denied'; end if;\n  select metadata into v_old from public.invoices where id=p_invoice_id for update;\n  if not found then raise exception 'Invoice not found'; end if;\n  update public.invoices\n     set metadata=jsonb_set(coalesce(metadata,'{}'::jsonb),'{presentation}',coalesce(p_presentation,'{}'::jsonb),true),updated_at=now()\n   where id=p_invoice_id;\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(auth.uid(),'invoice.presentation_updated','invoice',p_invoice_id,jsonb_build_object('reason',p_reason,'previous',coalesce(v_old->'presentation','{}'::jsonb),'presentation',coalesce(p_presentation,'{}'::jsonb)));\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_license_binding(p_binding_id uuid, p_desired_state text, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare b public.license_bindings%rowtype; act text; begin if not public.is_admin() then raise exception 'admin required'; end if; if p_desired_state not in ('active','blocked','suspended','revoked') then raise exception 'invalid desired state'; end if; select * into b from public.license_bindings where id=p_binding_id; if not found then raise exception 'licence binding not found'; end if; update public.license_bindings set desired_state=p_desired_state,remote_state=case when api_source='website' then p_desired_state else remote_state end,suspension_reason=case when p_desired_state='active' then null else p_reason end,updated_at=now() where id=p_binding_id; if b.api_source='website' then perform public.bump_license_revision(); act:='applied'; else act:=case when p_desired_state='active' then 'unblock' when p_desired_state='revoked' then 'revoke' else 'block' end; insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source,payload) values(b.id,b.auth_user_id,b.license_id,act,p_reason,'master_admin',jsonb_build_object('desired_state',p_desired_state)); end if; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'license.desired_state','license_binding',p_binding_id::text,jsonb_build_object('desired_state',p_desired_state,'reason',p_reason,'engine',b.api_source)); return jsonb_build_object('ok',true,'engine',b.api_source,'action',act); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_orbitfs_release_system(p_patch jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare outrow public.orbitfs_release_system_settings%rowtype;\nbegin\n  if not (public.has_permission('licenses.manage') or public.has_permission('licenses.edit') or public.has_permission('license_api.manage')) then raise exception 'permission denied'; end if;\n  update public.orbitfs_release_system_settings set\n    enabled=case when p_patch?'enabled' then (p_patch->>'enabled')::boolean else enabled end,\n    customer_deploy_enabled=case when p_patch?'customer_deploy_enabled' then (p_patch->>'customer_deploy_enabled')::boolean else customer_deploy_enabled end,\n    customer_updates_enabled=case when p_patch?'customer_updates_enabled' then (p_patch->>'customer_updates_enabled')::boolean else customer_updates_enabled end,\n    customer_rollbacks_enabled=case when p_patch?'customer_rollbacks_enabled' then (p_patch->>'customer_rollbacks_enabled')::boolean else customer_rollbacks_enabled end,\n    allow_existing_supabase_project=case when p_patch?'allow_existing_supabase_project' then (p_patch->>'allow_existing_supabase_project')::boolean else allow_existing_supabase_project end,\n    allow_create_supabase_project=case when p_patch?'allow_create_supabase_project' then (p_patch->>'allow_create_supabase_project')::boolean else allow_create_supabase_project end,\n    supabase_oauth_enabled=case when p_patch?'supabase_oauth_enabled' then (p_patch->>'supabase_oauth_enabled')::boolean else supabase_oauth_enabled end,\n    vercel_oauth_enabled=case when p_patch?'vercel_oauth_enabled' then (p_patch->>'vercel_oauth_enabled')::boolean else vercel_oauth_enabled end,\n    supabase_client_id=case when p_patch?'supabase_client_id' then nullif(btrim(p_patch->>'supabase_client_id'),'') else supabase_client_id end,\n    vercel_client_id=case when p_patch?'vercel_client_id' then nullif(btrim(p_patch->>'vercel_client_id'),'') else vercel_client_id end,\n    vercel_install_url=case when p_patch?'vercel_install_url' then nullif(btrim(p_patch->>'vercel_install_url'),'') else vercel_install_url end,\n    supabase_scopes=case when p_patch?'supabase_scopes' then coalesce(nullif(btrim(p_patch->>'supabase_scopes'),''),supabase_scopes) else supabase_scopes end,\n    default_supabase_region=case when p_patch?'default_supabase_region' then coalesce(nullif(btrim(p_patch->>'default_supabase_region'),''),default_supabase_region) else default_supabase_region end,\n    panel_project_prefix=case when p_patch?'panel_project_prefix' then coalesce(nullif(btrim(p_patch->>'panel_project_prefix'),''),panel_project_prefix) else panel_project_prefix end,\n    schema_version=case when p_patch?'schema_version' then coalesce(nullif(btrim(p_patch->>'schema_version'),''),schema_version) else schema_version end,\n    schema_bucket=case when p_patch?'schema_bucket' then coalesce(nullif(btrim(p_patch->>'schema_bucket'),''),schema_bucket) else schema_bucket end,\n    schema_path=case when p_patch?'schema_path' then coalesce(nullif(btrim(p_patch->>'schema_path'),''),schema_path) else schema_path end,\n    health_path=case when p_patch?'health_path' then coalesce(nullif(btrim(p_patch->>'health_path'),''),health_path) else health_path end,\n    release_channel=case when p_patch?'release_channel' then coalesce(nullif(btrim(p_patch->>'release_channel'),''),release_channel) else release_channel end,\n    metadata=case when p_patch?'metadata' and jsonb_typeof(p_patch->'metadata')='object' then p_patch->'metadata' else metadata end,\n    updated_by=auth.uid(), updated_at=now()\n  where id='primary' returning * into outrow;\n  return to_jsonb(outrow);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_order(p_order_id uuid, p_status text, p_notes text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare o public.orders%rowtype; begin if public.current_role() not in ('admin','superadmin') then raise exception 'admin required'; end if; if p_status not in ('pending_payment','active','suspended','cancelled') then raise exception 'invalid order status'; end if; select * into o from public.orders where id=p_order_id for update; if not found then raise exception 'order not found'; end if; if p_status='active' and o.payment_status not like 'paid%' then raise exception 'cannot activate unpaid order'; end if; update public.orders set status=p_status,notes=coalesce(p_notes,notes),updated_at=now() where id=p_order_id; if p_status in ('suspended','cancelled') then update public.license_bindings set desired_state='blocked',suspension_reason=coalesce(p_notes,p_status),updated_at=now() where order_id=p_order_id; insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source) select id,auth_user_id,license_id,'block',coalesce(p_notes,p_status),'admin_order' from public.license_bindings b where b.order_id=p_order_id and not exists(select 1 from public.license_enforcement_queue q where q.binding_id=b.id and q.action='block' and q.state='queued'); elsif p_status='active' then update public.license_bindings set desired_state='active',suspension_reason=null,updated_at=now() where order_id=p_order_id; insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source) select id,auth_user_id,license_id,'unblock','order reactivated','admin_order' from public.license_bindings b where b.order_id=p_order_id and not exists(select 1 from public.license_enforcement_queue q where q.binding_id=b.id and q.action='unblock' and q.state='queued'); end if; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.status','order',p_order_id::text,jsonb_build_object('status',p_status,'notes',p_notes)); return jsonb_build_object('ok',true,'status',p_status); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_staff_member(p_user_id uuid, p_title text, p_department text, p_staff_notes text, p_status text, p_group_ids uuid[], p_primary_group_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  primary_id uuid;\n  primary_slug text;\n  result jsonb;\n  includes_superadmin boolean;\nbegin\n  if not (public.has_permission('staff.manage') or public.has_permission('settings.permissions')) then\n    raise exception 'Permission denied';\n  end if;\n  if p_user_id=auth.uid() and p_status='disabled' then\n    raise exception 'You cannot disable your own staff access';\n  end if;\n  if p_status not in ('active','disabled') then raise exception 'Invalid staff status'; end if;\n  if p_group_ids is null or coalesce(array_length(p_group_ids,1),0)=0 then raise exception 'At least one staff group is required'; end if;\n  if exists(select 1 from unnest(p_group_ids) g left join public.staff_groups sg on sg.id=g where sg.id is null) then raise exception 'Invalid staff group'; end if;\n\n  select exists(select 1 from public.staff_groups where id=any(p_group_ids) and slug='superadmin') into includes_superadmin;\n  if includes_superadmin and not public.has_permission('settings.permissions') then\n    raise exception 'Only permission administrators can assign Superadmin';\n  end if;\n\n  primary_id:=case when p_primary_group_id=any(p_group_ids) then p_primary_group_id else p_group_ids[1] end;\n  select slug into primary_slug from public.staff_groups where id=primary_id;\n\n  update public.staff_members\n  set title=nullif(trim(p_title),''),department=nullif(trim(p_department),''),staff_notes=nullif(trim(p_staff_notes),''),status=p_status,updated_at=now()\n  where user_id=p_user_id;\n  if not found then raise exception 'Staff member not found'; end if;\n\n  delete from public.staff_member_groups where user_id=p_user_id and not(group_id=any(p_group_ids));\n  insert into public.staff_member_groups(user_id,group_id,is_primary)\n  select p_user_id,g,(g=primary_id) from unnest(p_group_ids) g\n  on conflict(user_id,group_id) do update set is_primary=excluded.is_primary;\n  update public.staff_member_groups set is_primary=(group_id=primary_id) where user_id=p_user_id;\n  update public.user_profiles set role=primary_slug where id=p_user_id;\n\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n  values(auth.uid(),'staff.member_updated','staff_member',p_user_id,jsonb_build_object('status',p_status,'groups',p_group_ids,'primary_group_id',primary_id));\n\n  select jsonb_build_object(\n    'user_id',sm.user_id,'title',sm.title,'department',sm.department,'staff_notes',sm.staff_notes,\n    'status',sm.status,'updated_at',sm.updated_at,\n    'group_ids',coalesce(jsonb_agg(smg.group_id order by smg.group_id),'[]'::jsonb),\n    'primary_group_id',primary_id\n  ) into result\n  from public.staff_members sm left join public.staff_member_groups smg on smg.user_id=sm.user_id\n  where sm.user_id=p_user_id\n  group by sm.user_id,sm.title,sm.department,sm.staff_notes,sm.status,sm.updated_at;\n  return result;\nend$function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_staff_note(p_note_id uuid, p_body text, p_visibility text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare n public.staff_notes%rowtype; begin select * into n from public.staff_notes where id=p_note_id and deleted_at is null for update; if not found then raise exception 'note not found'; end if; if not public.staff_note_permission(n.entity_type,'manage') then raise exception 'permission denied'; end if; if p_visibility='customer' and not public.has_permission('notes.external') and public.current_role()<>'superadmin' then raise exception 'permission denied: notes.external'; end if; if p_visibility not in ('internal','customer') or coalesce(btrim(p_body),'')='' then raise exception 'invalid note'; end if; update public.staff_notes set body=btrim(p_body),visibility=p_visibility,updated_at=now() where id=p_note_id; insert into public.staff_note_revisions(note_id,body,visibility,revision_type,changed_by) values(p_note_id,btrim(p_body),p_visibility,'edited',auth.uid()); insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'note.edit',n.entity_type,n.entity_id::text,jsonb_build_object('note_id',p_note_id,'visibility',p_visibility)); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_support_ticket(p_ticket_id uuid, p_subject text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_department_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_assigned_to uuid DEFAULT NULL::uuid, p_assignment_action text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare old public.support_tickets%rowtype; staff_name text; dept_name text; target_department uuid; actor_rank integer; department_changed boolean;\nbegin\n if not public.has_permission('support.manage') then raise exception 'permission denied: support.manage'; end if;\n select * into old from public.support_tickets where id=p_ticket_id for update; if not found then raise exception 'ticket not found'; end if;\n if not public.support_staff_can_access_ticket(p_ticket_id,auth.uid()) then raise exception 'ticket is outside your support department or escalation level'; end if;\n actor_rank:=public.support_staff_rank(auth.uid()); department_changed:=p_department_id is not null and p_department_id is distinct from old.department_id;\n if p_subject is not null and p_subject<>old.subject and not public.has_permission('support.ticket_edit') then raise exception 'permission denied: support.ticket_edit'; end if;\n if p_priority is not null and p_priority<>old.priority and not public.has_permission('support.priority') then raise exception 'permission denied: support.priority'; end if;\n if department_changed and not public.has_permission('support.department') then raise exception 'permission denied: support.department'; end if;\n if p_status is not null and p_status<>old.status and not public.has_permission('support.close') then raise exception 'permission denied: support.close'; end if;\n if p_assignment_action='claim' and not public.has_permission('support.claim') then raise exception 'permission denied: support.claim'; end if;\n if p_assignment_action='assign' and not public.has_permission('support.assign') then raise exception 'permission denied: support.assign'; end if;\n if p_assignment_action in ('transfer','unassign') and not public.has_permission('support.transfer') then raise exception 'permission denied: support.transfer'; end if;\n if old.claim_required and p_assignment_action in ('assign','transfer') then raise exception 'this ticket must be claimed by the current department before it can be assigned or transferred'; end if;\n if p_assignment_action='claim' then\n   if p_assigned_to is distinct from auth.uid() then raise exception 'a ticket can only be claimed by the signed-in staff member'; end if;\n   if old.claim_required then\n     if old.escalation_level>0 and actor_rank<old.escalation_level+1 then raise exception 'this escalated ticket requires % or higher',public.support_staff_rank_label(old.escalation_level+1); end if;\n     if old.escalation_level=0 and actor_rank<2 and not public.support_user_has_department(auth.uid(),old.department_id) then raise exception 'this ticket must be claimed by the destination department or Senior Support+'; end if;\n   end if;\n end if;\n if p_priority is not null and p_priority not in ('low','normal','high','urgent') then raise exception 'invalid priority'; end if;\n if p_status is not null and p_status not in ('open','closed','on_hold','pending','customer_reply','staff_reply') then raise exception 'invalid status'; end if;\n if p_department_id is not null and not exists(select 1 from public.support_departments where id=p_department_id and enabled=true) then raise exception 'invalid department'; end if;\n target_department:=coalesce(p_department_id,old.department_id);\n if department_changed and actor_rank<3 and not public.support_user_has_department(auth.uid(),p_department_id) then raise exception 'you are not assigned to the destination support department or do not meet its minimum tier'; end if;\n if p_assigned_to is not null then\n   if not exists(select 1 from public.staff_members where user_id=p_assigned_to and status='active') or public.support_staff_rank(p_assigned_to)<=0 then raise exception 'invalid staff member'; end if;\n   if public.support_staff_rank(p_assigned_to)<3 and not public.support_user_has_department(p_assigned_to,target_department) then raise exception 'staff member is not assigned to this department'; end if;\n   if public.support_staff_rank(p_assigned_to)<=old.escalation_level then raise exception 'staff member is below the ticket escalation tier'; end if;\n end if;\n update public.support_tickets set\n   subject=coalesce(p_subject,subject),priority=coalesce(p_priority,priority),department_id=coalesce(p_department_id,department_id),status=coalesce(p_status,status),\n   assigned_to=case when department_changed then null when p_assignment_action='unassign' then null when p_assigned_to is not null then p_assigned_to else assigned_to end,\n   claim_required=case when department_changed then true when p_assignment_action='claim' then false else claim_required end,\n   closed_at=case when p_status='closed' then now() when p_status is not null and p_status<>'closed' then null else closed_at end,\n   closed_by=case when p_status='closed' then auth.uid() when p_status is not null and p_status<>'closed' then null else closed_by end,updated_at=now()\n where id=p_ticket_id;\n if p_priority is not null and p_priority<>old.priority then perform public.support_emit_system_message(p_ticket_id,'priority_changed',jsonb_build_object('priority',p_priority)); end if;\n if department_changed then select name into dept_name from public.support_departments where id=p_department_id; perform public.support_emit_system_message(p_ticket_id,'department_changed',jsonb_build_object('department',dept_name,'status','claim_required')); end if;\n if p_assigned_to is not null and p_assigned_to is distinct from old.assigned_to then select display_name into staff_name from public.user_profiles where id=p_assigned_to; perform public.support_emit_system_message(p_ticket_id,case when p_assignment_action='claim' then 'claimed' when old.assigned_to is null then 'assigned' else 'transferred' end,jsonb_build_object('staff',coalesce(staff_name,'Support staff'))); end if;\n if p_status='closed' and old.status<>'closed' then perform public.support_emit_system_message(p_ticket_id,'closing','{}'::jsonb); end if;\n insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail) values(p_ticket_id,auth.uid(),case when department_changed then 'department_transferred' else 'ticket_updated' end,jsonb_build_object('subject',p_subject,'priority',p_priority,'from_department_id',old.department_id,'department_id',p_department_id,'status',p_status,'assigned_to',p_assigned_to,'assignment_action',p_assignment_action,'claim_required',case when department_changed then true when p_assignment_action='claim' then false else old.claim_required end));\n return jsonb_build_object('ok',true,'claim_required',case when department_changed then true when p_assignment_action='claim' then false else old.claim_required end,'department_changed',department_changed);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.admin_update_support_ticket_details(p_ticket_id uuid, p_subject text, p_related_order_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare t public.support_tickets%rowtype; begin if not public.has_permission('support.ticket_edit') then raise exception 'permission denied: support.ticket_edit'; end if; select * into t from public.support_tickets where id=p_ticket_id for update; if not found then raise exception 'ticket not found'; end if; if nullif(btrim(p_subject),'') is null then raise exception 'subject is required'; end if; if p_related_order_id is not null and not exists(select 1 from public.orders where id=p_related_order_id and auth_user_id=t.user_id) then raise exception 'order does not belong to ticket customer'; end if; update public.support_tickets set subject=p_subject,related_order_id=p_related_order_id,updated_at=now() where id=p_ticket_id; insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail) values(p_ticket_id,auth.uid(),'ticket_details_changed',jsonb_build_object('subject',p_subject,'related_order_id',p_related_order_id)); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.admin_void_invoice(p_invoice_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare inv public.invoices%rowtype; begin if not public.has_permission('invoices.void') then raise exception 'permission denied: invoices.void'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'void reason is required'; end if; select * into inv from public.invoices where id=p_invoice_id for update; if not found then raise exception 'invoice not found'; end if; if inv.paid_cents>0 and not public.has_permission('billing.override_state') then raise exception 'permission denied: billing.override_state'; end if; update public.invoices set status='void',notes=concat_ws(E'\\n',notes,p_reason),updated_at=now() where id=inv.id; update public.orders set status='terminated',fulfillment_status='terminated',updated_at=now() where id=inv.order_id; insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'invoice.void','invoice',inv.id::text,jsonb_build_object('reason',p_reason)); return jsonb_build_object('ok',true); end $function$\n\nCREATE OR REPLACE FUNCTION public.apply_account_enforcement()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ begin if new.banned_at is not null and old.banned_at is null then update public.license_bindings set desired_state='blocked',suspension_reason=coalesce(new.ban_reason,'account banned'),updated_at=now() where auth_user_id=new.id and desired_state<>'revoked'; perform public.queue_account_license_action(new.id,'block',coalesce(new.ban_reason,'account banned'),'account_ban'); elsif new.banned_at is null and old.banned_at is not null and new.status='active' then update public.license_bindings set desired_state='active',suspension_reason=null,updated_at=now() where auth_user_id=new.id and desired_state in ('suspended','blocked'); perform public.queue_account_license_action(new.id,'unblock','account ban removed','account_restore'); elsif new.status='suspended' and old.status is distinct from 'suspended' then update public.license_bindings set desired_state='suspended',suspension_reason=coalesce(new.suspension_reason,'account suspended'),updated_at=now() where auth_user_id=new.id and desired_state<>'revoked'; perform public.queue_account_license_action(new.id,'block',coalesce(new.suspension_reason,'account suspended'),'account_suspend'); elsif new.status='active' and old.status='suspended' and new.banned_at is null then update public.license_bindings set desired_state='active',suspension_reason=null,updated_at=now() where auth_user_id=new.id and desired_state in ('suspended','blocked'); perform public.queue_account_license_action(new.id,'unblock','account restored','account_restore'); end if; return new; end $function$\n\nCREATE OR REPLACE FUNCTION public.apply_coupon_to_invoice(p_invoice_id uuid, p_coupon_code text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); inv public.invoices%rowtype; c public.coupons%rowtype; used_count integer; discount bigint:=0; new_total bigint:=0; product_match boolean;\nbegin\n if uid is null then raise exception 'authentication required'; end if;\n select * into inv from public.invoices where id=p_invoice_id and auth_user_id=uid for update; if not found then raise exception 'invoice not found'; end if;\n if inv.status not in ('unpaid','overdue') then raise exception 'coupon can only be applied to an unpaid invoice'; end if;\n if coalesce(inv.paid_cents,0)>0 then raise exception 'coupon cannot be applied after a payment has been recorded'; end if;\n if exists(select 1 from public.coupon_redemptions where invoice_id=inv.id) then raise exception 'this invoice already has a coupon applied'; end if;\n select * into c from public.coupons where lower(code)=lower(btrim(p_coupon_code)) and active=true and discount_type in ('percent','fixed') and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()) and inv.subtotal_cents>=min_order_cents;\n if not found then raise exception 'coupon is invalid for invoice discounts, expired, not yet active, or below its minimum spend'; end if;\n if cardinality(c.product_ids)>0 then select exists(select 1 from public.order_items oi where oi.order_id=inv.order_id and oi.product_id=any(c.product_ids)) into product_match; if not product_match then raise exception 'coupon is not available for the products on this invoice'; end if; end if;\n select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id; if c.max_redemptions is not null and used_count>=c.max_redemptions then raise exception 'coupon redemption limit reached'; end if;\n select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id and auth_user_id=uid; if used_count>=c.per_user_limit then raise exception 'coupon usage limit reached for this account'; end if;\n if c.discount_type='percent' then discount:=least(inv.subtotal_cents,round(inv.subtotal_cents*(c.discount_value::numeric/100))); else discount:=least(inv.subtotal_cents,c.discount_value); end if;\n new_total:=greatest(0,inv.subtotal_cents+coalesce(inv.tax_cents,0)-discount);\n update public.invoices set discount_cents=discount,total_cents=new_total,status=case when new_total=0 then 'paid' else status end,paid_at=case when new_total=0 then coalesce(paid_at,now()) else paid_at end,updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('coupon_code',c.code,'coupon_type',c.discount_type,'coupon_value',c.discount_value,'settled_by_coupon',new_total=0) where id=inv.id;\n update public.orders set total_cents=new_total,payment_status=case when new_total=0 then 'paid' else payment_status end,updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('coupon_code',c.code,'discount_cents',discount,'coupon_type',c.discount_type,'coupon_value',c.discount_value) where id=inv.order_id;\n insert into public.coupon_redemptions(coupon_id,invoice_id,auth_user_id,discount_cents,credit_cents) values(c.id,inv.id,uid,discount,0);\n return jsonb_build_object('ok',true,'code',c.code,'discount_type',c.discount_type,'discount_value',c.discount_value,'discount_cents',discount,'total_cents',new_total,'invoice_status',case when new_total=0 then 'paid' else inv.status end);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.apply_wallet_credit_to_invoice(p_invoice_id uuid, p_amount_cents bigint DEFAULT NULL::bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  uid uuid:=auth.uid();\n  inv public.invoices%rowtype;\n  bal public.account_balances%rowtype;\n  due bigint;\n  apply_amount bigint;\n  new_paid bigint;\n  new_balance bigint;\n  allow_credit boolean:=true;\n  allow_partial boolean:=true;\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  select coalesce((select (value#>>'{}')::boolean from public.app_settings where key='billing.allow_account_credit'),true) into allow_credit;\n  select coalesce((select (value#>>'{}')::boolean from public.app_settings where key='billing.allow_partial_payments'),true) into allow_partial;\n  if not allow_credit then raise exception 'Wallet payments are disabled'; end if;\n\n  select * into inv from public.invoices where id=p_invoice_id and auth_user_id=uid for update;\n  if not found then raise exception 'invoice not found'; end if;\n  if coalesce((inv.metadata->>'wallet_recharge')::boolean,false) then raise exception 'wallet recharge cannot be paid using Wallet credit'; end if;\n  if inv.status='paid' then return jsonb_build_object('status','paid','invoice_id',inv.id,'applied_cents',0,'remaining_cents',0,'fully_paid',true); end if;\n\n  due:=greatest(0,coalesce(inv.total_cents,0)-coalesce(inv.paid_cents,0));\n  if due<=0 then raise exception 'nothing due'; end if;\n  select * into bal from public.account_balances where user_id=uid for update;\n  if not found or coalesce(bal.available_cents,0)<=0 then raise exception 'no Wallet credit available'; end if;\n\n  apply_amount:=least(due,coalesce(bal.available_cents,0),case when p_amount_cents is null then due else greatest(0,p_amount_cents) end);\n  if apply_amount<=0 then raise exception 'no Wallet credit selected'; end if;\n  if apply_amount<due and not allow_partial then raise exception 'partial payments are disabled'; end if;\n\n  update public.account_balances\n     set available_cents=available_cents-apply_amount,\n         lifetime_debit_cents=lifetime_debit_cents+apply_amount,\n         updated_at=now()\n   where user_id=uid\n   returning available_cents into new_balance;\n\n  insert into public.credit_ledger(user_id,direction,amount_cents,balance_after_cents,reason,reference_type,reference_id,metadata,created_by)\n  values(uid,'debit',apply_amount,new_balance,case when apply_amount<due then 'Partial invoice payment' else 'Invoice payment' end,'invoice',inv.id::text,\n         jsonb_build_object('split_payment',apply_amount<due,'invoice_total_cents',inv.total_cents,'invoice_due_before_cents',due),uid);\n\n  insert into public.invoice_payments(invoice_id,auth_user_id,method,amount_cents,status,metadata)\n  values(inv.id,uid,'account_credit',apply_amount,'completed',jsonb_build_object('split_payment',apply_amount<due,'wallet_balance_after_cents',new_balance));\n\n  new_paid:=coalesce(inv.paid_cents,0)+apply_amount;\n  update public.invoices\n     set paid_cents=new_paid,\n         status=case when new_paid>=total_cents then 'paid' else 'partial' end,\n         paid_at=case when new_paid>=total_cents then coalesce(paid_at,now()) else paid_at end,\n         updated_at=now()\n   where id=inv.id;\n\n  if inv.order_id is not null then\n    if new_paid>=inv.total_cents then\n      update public.orders\n         set payment_status=case when coalesce(inv.paid_cents,0)=0 and apply_amount>=inv.total_cents then 'paid_credit' else 'paid_mixed' end,\n             updated_at=now()\n       where id=inv.order_id;\n      perform public.grant_paid_order_entitlements(inv.order_id,uid);\n    else\n      update public.orders set payment_status='partial',status='pending_payment',updated_at=now() where id=inv.order_id;\n    end if;\n  end if;\n\n  return jsonb_build_object('status',case when new_paid>=inv.total_cents then 'paid' else 'partial' end,'invoice_id',inv.id,'order_id',inv.order_id,\n    'applied_cents',apply_amount,'paid_cents',new_paid,'remaining_cents',greatest(0,inv.total_cents-new_paid),'wallet_balance_cents',new_balance,'fully_paid',new_paid>=inv.total_cents);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.assign_customer_number()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\nbegin\n  if new.customer_number is null or btrim(new.customer_number)='' then\n    new.customer_number := 'OrbitFS-CUSTOMER-' || lpad(nextval('public.customer_number_seq')::text,4,'0');\n  end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.attach_support_file(p_ticket_id uuid, p_message_id uuid, p_file_name text, p_storage_path text, p_mime_type text, p_file_size_bytes bigint)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare uid uuid:=auth.uid(); rid uuid; begin if uid is null then raise exception 'authentication required'; end if; if not public.is_staff() and not exists(select 1 from public.support_tickets where id=p_ticket_id and user_id=uid) then raise exception 'ticket not found'; end if; insert into public.support_attachments(ticket_id,message_id,uploader_user_id,file_name,storage_path,mime_type,file_size_bytes) values(p_ticket_id,p_message_id,uid,p_file_name,p_storage_path,p_mime_type,p_file_size_bytes) returning id into rid; return rid; end $function$\n\nCREATE OR REPLACE FUNCTION public.available_payment_gateways(p_invoice_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); inv public.invoices%rowtype; out jsonb; is_wallet boolean:=false;\nbegin\n if uid is null then raise exception 'authentication required'; end if;\n select * into inv from public.invoices where id=p_invoice_id and auth_user_id=uid; if not found then raise exception 'invoice not found'; end if;\n if inv.status in ('refunded','void','cancelled') then return '[]'::jsonb; end if;\n is_wallet:=coalesce((inv.metadata->>'wallet_recharge')::boolean,false);\n select coalesce(jsonb_agg(jsonb_build_object('code',g.code,'name',g.display_name,'description',g.description,'provider',g.provider,'supports_recurring',g.supports_recurring,'fee_fixed_cents',g.fee_fixed_cents,'fee_percent',g.fee_percent,'public_config',g.public_config,'instructions',case when g.provider='manual' then g.instructions else null end) order by g.sort_order,g.display_name),'[]'::jsonb) into out\n from public.payment_gateways g where g.enabled=true and inv.currency=any(g.currencies) and (not is_wallet or g.provider<>'account_credit');\n return out;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.bump_license_revision()\n RETURNS void\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ update public.license_revision set revision=revision+1,updated_at=now() where id=1 $function$\n\nCREATE OR REPLACE FUNCTION public.buy_product_with_credit(p_product_id uuid, p_configuration jsonb DEFAULT '{}'::jsonb)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare uid uuid:=auth.uid(); prod public.products%rowtype; bal public.account_balances%rowtype; cust uuid; ord uuid; item uuid; total bigint; begin if uid is null then raise exception 'authentication required'; end if; select * into prod from public.products where id=p_product_id and active=true; if not found then raise exception 'product unavailable'; end if; total:=prod.price_cents; select * into bal from public.account_balances where user_id=uid for update; if bal.available_cents < total then raise exception 'insufficient credit'; end if; select id into cust from public.customers where auth_user_id=uid limit 1; insert into public.orders(order_number,customer_id,auth_user_id,status,payment_status,fulfillment_status,subtotal_cents,total_cents,currency,metadata) values('ORB-'||lpad(nextval('public.order_number_seq')::text,6,'0'),cust,uid,'active','paid_credit','pending',total,total,prod.currency,jsonb_build_object('payment_method','account_credit')) returning id into ord; insert into public.order_items(order_id,product_id,product_name,product_slug,license_product_key,quantity,unit_price_cents,total_cents,configuration) values(ord,prod.id,prod.name,prod.slug,prod.license_product_key,1,total,total,p_configuration) returning id into item; update public.account_balances set available_cents=available_cents-total,lifetime_debit_cents=lifetime_debit_cents+total,updated_at=now() where user_id=uid; insert into public.credit_ledger(user_id,direction,amount_cents,balance_after_cents,reason,reference_type,reference_id,created_by) select uid,'debit',total,available_cents,'Product purchase','order',ord::text,uid from public.account_balances where user_id=uid; insert into public.license_fulfillments(order_id,order_item_id,auth_user_id,state,metadata) values(ord,item,uid,'pending',jsonb_build_object('license_product_key',prod.license_product_key,'configuration',p_configuration)); return ord; end; $function$\n\nCREATE OR REPLACE FUNCTION public.can_download_product(p_product_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select auth.uid() is not null and (\n    public.is_staff()\n    or exists (\n      select 1 from public.download_entitlements d\n      where d.auth_user_id=auth.uid()\n        and d.product_id=p_product_id\n        and d.status='active'\n        and d.revoked_at is null\n    )\n  );\n$function$\n\nCREATE OR REPLACE FUNCTION public.cancellation_refund_plan(p_request_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  r public.order_cancellation_requests%rowtype;\n  inv public.invoices%rowtype;\n  committed bigint:=0;\n  processed_since bigint:=0;\n  remaining_target bigint:=0;\n  lines jsonb:='[]'::jsonb;\nbegin\n  if not public.has_permission('customers.cancellations') then raise exception 'permission denied: customers.cancellations'; end if;\n  select * into r from public.order_cancellation_requests where id=p_request_id;\n  if not found then raise exception 'cancellation request not found'; end if;\n  select * into inv from public.invoices where order_id=r.order_id order by created_at desc limit 1;\n  if inv.id is null then raise exception 'invoice not found'; end if;\n  select coalesce(sum(amount_cents),0) into committed from public.invoice_refunds where invoice_id=inv.id and status in ('pending','processing','completed','succeeded');\n  processed_since:=greatest(0,committed-coalesce(r.refund_baseline_cents,0));\n  remaining_target:=greatest(0,coalesce(r.refund_amount_cents,0)-processed_since);\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'payment_id',p.id,'method',p.method,'amount_cents',p.amount_cents,'external_reference',p.external_reference,\n    'refunded_cents',coalesce(rr.refunded,0),'refundable_cents',greatest(0,p.amount_cents-coalesce(rr.refunded,0))\n  ) order by p.created_at),'[]'::jsonb) into lines\n  from public.invoice_payments p\n  left join lateral (\n    select coalesce(sum(x.amount_cents),0) refunded from public.invoice_refunds x\n     where x.payment_id=p.id and x.status in ('pending','processing','completed','succeeded')\n  ) rr on true\n  where p.invoice_id=inv.id and p.status='completed' and p.method in ('account_credit','stripe','paypal') and p.amount_cents>coalesce(rr.refunded,0);\n  return jsonb_build_object(\n    'request_id',r.id,'order_id',r.order_id,'invoice_id',inv.id,'invoice_number',inv.invoice_number,'currency',inv.currency,\n    'refund_preference',r.refund_preference,'refund_status',r.refund_status,'refund_amount_cents',r.refund_amount_cents,\n    'refund_processed_cents',processed_since,'remaining_cents',remaining_target,'payments',lines,\n    'refund_required',r.refund_amount_cents>0\n  );\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.canonical_license_component_key(p_key text)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\nAS $function$\n  select case lower(coalesce(p_key,''))\n    when 'orbitfs_panel' then 'orbitfs_base'\n    when 'orbitfs_base' then 'orbitfs_base'\n    when 'orbitfs_sorter' then 'orbitfs_apex'\n    when 'orbitfs_apex' then 'orbitfs_apex'\n    when 'orbitfs_studio' then 'orbitfs_studio'\n    when 'orbitfs_mcp' then 'orbitfs_mcp'\n    else lower(coalesce(p_key,''))\n  end\n$function$\n\nCREATE OR REPLACE FUNCTION public.cart_summary()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); cid uuid; subtotal bigint:=0; discount bigint:=0; eligible bigint:=0; c public.coupons%rowtype; used_count integer; items jsonb:='[]'::jsonb; r record; line bigint; coupon text;\nbegin\n if uid is null then raise exception 'authentication required'; end if;\n cid:=public.get_or_create_cart(); select coupon_code into coupon from public.shopping_carts where id=cid;\n for r in select i.*,p.name,p.slug,p.price_cents,p.currency,p.metadata,p.license_product_key from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid order by case when public.canonical_license_component_key(p.license_product_key)='orbitfs_base' then 0 else 1 end,p.name loop\n   line:=coalesce(r.price_cents,0)*r.quantity; subtotal:=subtotal+line;\n   items:=items||jsonb_build_array(jsonb_build_object('id',r.id,'product_id',r.product_id,'name',r.name,'slug',r.slug,'quantity',r.quantity,'configuration',r.configuration,'line_total_cents',line,'currency',r.currency,'license_product_key',public.canonical_license_component_key(r.license_product_key)));\n end loop;\n if coupon is not null and subtotal>0 then\n   select * into c from public.coupons where lower(code)=lower(coupon) and active=true and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()) and subtotal>=min_order_cents;\n   if found then\n     select coalesce(sum(coalesce(p.price_cents,0)*i.quantity),0) into eligible from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid and (cardinality(c.product_ids)=0 or p.id=any(c.product_ids));\n     select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id; if c.max_redemptions is not null and used_count>=c.max_redemptions then raise exception 'coupon redemption limit reached'; end if;\n     select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id and auth_user_id=uid; if used_count>=c.per_user_limit then raise exception 'coupon already used'; end if;\n     if eligible<=0 then raise exception 'coupon does not apply to products in this basket'; end if;\n     if c.discount_type='percent' then discount:=least(eligible,round(eligible*(c.discount_value::numeric/100))); else discount:=least(eligible,c.discount_value); end if;\n   else raise exception 'invalid or unavailable coupon'; end if;\n end if;\n return jsonb_build_object('cart_id',cid,'items',items,'subtotal_cents',subtotal,'discount_cents',discount,'total_cents',greatest(0,subtotal-discount),'coupon_code',coupon,'item_count',jsonb_array_length(items));\nend $function$\n\nCREATE OR REPLACE FUNCTION public.checkout_cart(p_pay_with_credit boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); cid uuid; sumry jsonb; subtotal bigint; discount bigint; total bigint; cust uuid; ord uuid; inv uuid; ordno text; invno text; order_prefix text:='ORB-'; invoice_prefix text:='INV-'; due_days integer:=7; r record; oi uuid; c public.coupons%rowtype; coupon text; has_base boolean; payres jsonb; currency_code text; currency_count integer; is_gift boolean; gift_email text;\nbegin\n if uid is null then raise exception 'authentication required'; end if; if not public.account_can_order(uid) then raise exception 'account is not allowed to place new orders'; end if;\n cid:=public.get_or_create_cart(); if not exists(select 1 from public.shopping_cart_items where cart_id=cid) then raise exception 'basket is empty'; end if;\n select count(distinct p.currency),min(p.currency) into currency_count,currency_code from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid; if currency_count>1 then raise exception 'basket contains products in multiple currencies'; end if; if currency_code is null then raise exception 'basket currency unavailable'; end if;\n has_base:=exists(select 1 from public.products p join public.shopping_cart_items i on i.product_id=p.id where i.cart_id=cid and p.license_product_key in ('orbitfs_panel','orbitfs_base') and not coalesce((i.configuration->>'gift')::boolean,false)) or exists(select 1 from public.products p where p.license_product_key in ('orbitfs_panel','orbitfs_base') and public.user_has_active_product(uid,p.id));\n for r in select i.*,p.name,p.slug,p.price_cents,p.currency,p.metadata,p.license_product_key from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid loop\n  is_gift:=coalesce((r.configuration->>'gift')::boolean,false);\n  gift_email:=lower(trim(coalesce(r.configuration->>'gift_recipient_email','')));\n  if is_gift then\n    if gift_email='' or gift_email !~* '^[A-Z0-9._%+\\-]+@[A-Z0-9.\\-]+\\.[A-Z]{2,}$' then raise exception 'enter a valid gift recipient email for %',r.name; end if;\n  else\n    if not coalesce((r.metadata->>'allow_repeat_purchase')::boolean,false) and public.user_has_active_product(uid,r.product_id) then raise exception 'you already own active product %',r.name; end if;\n    if r.license_product_key not in ('orbitfs_panel','orbitfs_base') and not has_base then raise exception '% requires OrbitFS Base. Add Base to the basket or activate an existing Base service first.',r.name; end if;\n    if exists(select 1 from public.invoices x join public.order_items xoi on xoi.order_id=x.order_id where x.auth_user_id=uid and xoi.product_id=r.product_id and x.status in ('unpaid','partial','overdue')) then raise exception 'an unpaid invoice already exists for %',r.name; end if;\n  end if;\n end loop;\n sumry:=public.cart_summary(); subtotal:=(sumry->>'subtotal_cents')::bigint; discount:=(sumry->>'discount_cents')::bigint; total:=(sumry->>'total_cents')::bigint; coupon:=sumry->>'coupon_code';\n select coalesce((select (value#>>'{}')::int from public.app_settings where key='invoice.due_days'),7) into due_days; select coalesce((select trim(both '\\"' from value::text) from public.app_settings where key='billing.order_prefix'),'ORB-') into order_prefix; select coalesce((select trim(both '\\"' from value::text) from public.app_settings where key='invoice.prefix'),'INV-') into invoice_prefix; select id into cust from public.customers where auth_user_id=uid limit 1;\n ordno:=order_prefix||lpad(nextval('public.order_number_seq')::text,6,'0'); insert into public.orders(order_number,customer_id,auth_user_id,status,payment_status,fulfillment_status,subtotal_cents,total_cents,currency,metadata) values(ordno,cust,uid,case when total=0 then 'active' else 'pending_payment' end,case when total=0 then 'paid_free' else 'unpaid' end,'pending',subtotal,total,currency_code,jsonb_build_object('basket_checkout',true,'coupon_code',coupon,'contains_gifts',exists(select 1 from public.shopping_cart_items i where i.cart_id=cid and coalesce((i.configuration->>'gift')::boolean,false)))) returning id into ord;\n invno:=invoice_prefix||lpad(nextval('public.invoice_number_seq')::text,6,'0'); insert into public.invoices(invoice_number,order_id,auth_user_id,status,subtotal_cents,discount_cents,total_cents,paid_cents,currency,due_at,paid_at) values(invno,ord,uid,case when total=0 then 'paid' else 'unpaid' end,subtotal,discount,total,0,currency_code,case when total=0 then now() else now()+make_interval(days=>due_days) end,case when total=0 then now() else null end) returning id into inv;\n for r in select i.*,p.name,p.slug,p.price_cents,p.license_product_key from public.shopping_cart_items i join public.products p on p.id=i.product_id where i.cart_id=cid order by case when p.license_product_key in ('orbitfs_panel','orbitfs_base') then 0 else 1 end,p.name loop\n   insert into public.order_items(order_id,product_id,product_name,product_slug,license_product_key,quantity,unit_price_cents,total_cents,configuration,service_status) values(ord,r.product_id,r.name,r.slug,r.license_product_key,r.quantity,coalesce(r.price_cents,0),coalesce(r.price_cents,0)*r.quantity,r.configuration,case when coalesce((r.configuration->>'gift')::boolean,false) then 'pending_gift' else 'pending' end) returning id into oi;\n   insert into public.invoice_items(invoice_id,order_item_id,description,quantity,unit_price_cents,total_cents) values(inv,oi,r.name,r.quantity,coalesce(r.price_cents,0),coalesce(r.price_cents,0)*r.quantity);\n   if coalesce((r.configuration->>'gift')::boolean,false) then\n     insert into public.gift_deliveries(source_order_id,source_order_item_id,purchaser_user_id,recipient_email,status,metadata) values(ord,oi,uid,lower(trim(r.configuration->>'gift_recipient_email')),'pending',jsonb_build_object('product_id',r.product_id,'product_name',r.name)) on conflict(source_order_item_id) do nothing;\n   end if;\n end loop;\n if coupon is not null then select * into c from public.coupons where lower(code)=lower(coupon) limit 1; if c.id is not null then insert into public.coupon_redemptions(coupon_id,invoice_id,auth_user_id,discount_cents) values(c.id,inv,uid,discount); end if; end if;\n delete from public.shopping_cart_items where cart_id=cid; update public.shopping_carts set coupon_code=null,updated_at=now() where id=cid;\n if total=0 then perform public.grant_paid_order_entitlements(ord,uid); elsif p_pay_with_credit then payres:=public.pay_invoice_with_credit(inv); end if;\n return jsonb_build_object('order_id',ord,'order_number',ordno,'invoice_id',inv,'invoice_number',invno,'subtotal_cents',subtotal,'discount_cents',discount,'total_cents',total,'currency',currency_code,'paid',total=0 or coalesce(payres->>'status','')='paid','contains_gifts',exists(select 1 from public.gift_deliveries where source_order_id=ord));\nend $function$\n\nCREATE OR REPLACE FUNCTION public.checkout_payment_gateways(p_currency text DEFAULT 'AUD'::text)\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select coalesce(jsonb_agg(jsonb_build_object('code',code,'name',display_name,'description',description,'provider',provider,'fee_fixed_cents',fee_fixed_cents,'fee_percent',fee_percent,'supports_recurring',supports_recurring,'instructions',case when provider='manual' then instructions else null end) order by sort_order,display_name),'[]'::jsonb) from public.payment_gateways where enabled=true and p_currency=any(currencies) $function$\n\nCREATE OR REPLACE FUNCTION public.clear_cart()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); begin\n delete from public.shopping_cart_items i using public.shopping_carts c where i.cart_id=c.id and c.auth_user_id=uid;\n update public.shopping_carts set coupon_code=null,updated_at=now() where auth_user_id=uid;\n return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.complete_payment_attempt(p_attempt_id uuid, p_provider_reference text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  a public.payment_attempts%rowtype;\n  inv public.invoices%rowtype;\n  wr public.wallet_recharges%rowtype;\n  newpaid bigint;\n  apply_amount bigint;\n  newbal bigint;\nbegin\n  if auth.role()<>'service_role' and not public.has_permission('payments.manage') then raise exception 'permission denied'; end if;\n  select * into a from public.payment_attempts where id=p_attempt_id for update;\n  if not found then raise exception 'payment attempt not found'; end if;\n\n  if a.wallet_recharge_id is not null then\n    select * into wr from public.wallet_recharges where id=a.wallet_recharge_id for update;\n    if not found then raise exception 'wallet recharge not found'; end if;\n    if wr.status='succeeded' then\n      update public.payment_attempts set status='succeeded',completed_at=coalesce(completed_at,now()),updated_at=now() where id=a.id and status<>'succeeded';\n      return jsonb_build_object('ok',true,'already_completed',true,'wallet_recharge_id',wr.id,'receipt_number',wr.receipt_number,'wallet_balance_cents',wr.balance_after_cents,'paid',true,'invoice_id',null,'order_id',null);\n    end if;\n    if a.amount_cents<>wr.amount_cents then raise exception 'wallet recharge payment amount mismatch'; end if;\n    newbal:=public.wallet_credit(\n      wr.auth_user_id,\n      wr.amount_cents,\n      'Account Credit - Recharge',\n      'wallet_recharge',\n      wr.id::text,\n      coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('receipt_number',wr.receipt_number,'gateway_code',a.gateway_code,'provider_reference',p_provider_reference,'payment_attempt_id',a.id),\n      wr.auth_user_id\n    );\n    update public.wallet_recharges\n      set status='succeeded',gateway_code=a.gateway_code,provider_reference=coalesce(p_provider_reference,provider_reference),credited_cents=amount_cents,balance_after_cents=newbal,completed_at=now(),updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb)\n      where id=wr.id;\n    update public.payment_attempts\n      set status='succeeded',provider_reference=coalesce(p_provider_reference,provider_reference),failure_code=null,failure_message=null,metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),completed_at=now(),updated_at=now()\n      where id=a.id;\n    insert into public.payment_events(payment_attempt_id,gateway_code,event_type,payload)\n      values(a.id,a.gateway_code,'payment.succeeded',coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('provider_reference',p_provider_reference,'wallet_recharge_id',wr.id,'receipt_number',wr.receipt_number,'amount_cents',wr.amount_cents));\n    return jsonb_build_object('ok',true,'paid',true,'wallet_recharge_id',wr.id,'receipt_number',wr.receipt_number,'wallet_balance_cents',newbal,'amount_cents',wr.amount_cents,'invoice_id',null,'order_id',null);\n  end if;\n\n  if a.status='succeeded' then return jsonb_build_object('ok',true,'already_completed',true,'invoice_id',a.invoice_id); end if;\n  select * into inv from public.invoices where id=a.invoice_id for update;\n  if not found then raise exception 'invoice not found'; end if;\n  apply_amount:=greatest(0,least(a.amount_cents,inv.total_cents-inv.paid_cents));\n  if apply_amount>0 then\n    insert into public.invoice_payments(invoice_id,auth_user_id,method,amount_cents,status,external_reference,metadata)\n      values(inv.id,a.auth_user_id,a.gateway_code,apply_amount,'completed',p_provider_reference,p_metadata);\n    newpaid:=inv.paid_cents+apply_amount;\n    update public.invoices\n      set paid_cents=newpaid,status=case when newpaid>=total_cents then 'paid' else 'partial' end,\n          paid_at=case when newpaid>=total_cents then now() else paid_at end,updated_at=now()\n      where id=inv.id;\n  else\n    newpaid:=inv.paid_cents;\n  end if;\n  update public.payment_attempts\n    set status='succeeded',provider_reference=coalesce(p_provider_reference,provider_reference),failure_code=null,failure_message=null,\n        metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('applied_amount_cents',apply_amount,'duplicate_or_excess',apply_amount<a.amount_cents),\n        completed_at=now(),updated_at=now()\n    where id=a.id;\n  insert into public.payment_events(payment_attempt_id,gateway_code,event_type,payload)\n    values(a.id,a.gateway_code,case when apply_amount<a.amount_cents then 'payment.succeeded.excess' else 'payment.succeeded' end,\n           coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('provider_reference',p_provider_reference,'applied_amount_cents',apply_amount,'attempt_amount_cents',a.amount_cents));\n  return jsonb_build_object('ok',true,'invoice_id',inv.id,'order_id',inv.order_id,'paid_cents',newpaid,'fully_paid',newpaid>=inv.total_cents,'wallet_recharge',false,'wallet_balance_cents',null,'applied_amount_cents',apply_amount);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.create_binding_from_fulfillment()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare oi public.order_items%rowtype; begin select * into oi from public.order_items where id=new.order_item_id; if new.auth_user_id is not null and oi.license_product_key is not null then insert into public.license_bindings(auth_user_id,fulfillment_id,order_id,order_item_id,license_id,license_product_key,desired_state,remote_state,components) values(new.auth_user_id,new.id,new.order_id,new.order_item_id,new.license_id,oi.license_product_key,case when new.state='fulfilled' then 'active' else 'pending' end,case when new.state='fulfilled' then 'active' else 'unknown' end,jsonb_build_object(oi.license_product_key,true)) on conflict(fulfillment_id) do update set license_id=excluded.license_id,desired_state=excluded.desired_state,remote_state=excluded.remote_state,updated_at=now(); if new.state in ('pending','queued') then insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,payload,source) select b.id,b.auth_user_id,b.license_id,'issue','paid order ready for licence issue',jsonb_build_object('productKey',b.license_product_key,'orderId',new.order_id),'order_fulfillment' from public.license_bindings b where b.fulfillment_id=new.id and not exists(select 1 from public.license_enforcement_queue q where q.binding_id=b.id and q.action='issue' and q.state in ('queued','running')); end if; end if; return new; end $function$\n\nCREATE OR REPLACE FUNCTION public.create_order_invoice(p_product_id uuid, p_configuration jsonb DEFAULT '{}'::jsonb, p_coupon_code text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare uid uuid:=auth.uid(); prod public.products%rowtype; cust uuid; ord uuid; item uuid; inv uuid; invno text; ordno text; subtotal bigint; option_total bigint:=0; discount bigint:=0; total bigint; c public.coupons%rowtype; used_count integer; dep record; opt record; selected text; choice jsonb; due_days integer:=7; order_prefix text:='ORB-'; invoice_prefix text:='INV-'; allow_repeat boolean:=false; is_free boolean:=false; begin if uid is null then raise exception 'authentication required'; end if; if not public.account_can_order(uid) then raise exception 'account is not allowed to place new orders'; end if; select * into prod from public.products where id=p_product_id and active=true; if not found then raise exception 'product unavailable'; end if; allow_repeat:=coalesce((prod.metadata->>'allow_repeat_purchase')::boolean,false); is_free:=coalesce((prod.metadata->>'free_product')::boolean,false); if prod.price_cents is null and not is_free then raise exception 'product pricing has not been configured'; end if; if not allow_repeat and exists(select 1 from public.download_entitlements de where de.auth_user_id=uid and de.product_id=prod.id and de.status='active') then raise exception 'you already own this product'; end if; if exists(select 1 from public.invoices i join public.order_items oi on oi.order_id=i.order_id where i.auth_user_id=uid and oi.product_id=prod.id and i.status in ('unpaid','partial','overdue')) then raise exception 'an unpaid invoice already exists for this product'; end if; for dep in select pd.requires_product_id,p.name from public.product_dependencies pd join public.products p on p.id=pd.requires_product_id where pd.product_id=prod.id loop if not exists(select 1 from public.download_entitlements de where de.auth_user_id=uid and de.product_id=dep.requires_product_id and de.status='active') then raise exception 'This product requires an active % entitlement first',dep.name; end if; end loop; subtotal:=coalesce(prod.price_cents,0); for opt in select * from public.product_options where product_id=prod.id and active=true order by sort_order loop selected:=p_configuration->>opt.key; if opt.required and (selected is null or btrim(selected)='') then raise exception 'Required option missing: %',opt.label; end if; if selected is not null and btrim(selected)<>'' then if opt.option_type='select' and jsonb_array_length(opt.choices)>0 then select x into choice from jsonb_array_elements(opt.choices) x where (jsonb_typeof(x)='string' and trim(both '"' from x::text)=selected) or (jsonb_typeof(x)='object' and x->>'value'=selected) limit 1; if choice is null then raise exception 'Invalid choice for %',opt.label; end if; option_total:=option_total+coalesce(case when jsonb_typeof(choice)='object' then nullif(choice->>'price_delta_cents','')::bigint else null end,opt.price_delta_cents,0); else option_total:=option_total+coalesce(opt.price_delta_cents,0); end if; end if; end loop; subtotal:=subtotal+option_total; if p_coupon_code is not null and btrim(p_coupon_code)<>'' then select * into c from public.coupons where lower(code)=lower(btrim(p_coupon_code)) and active=true and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()) and discount_type in ('percent','fixed') and subtotal>=min_order_cents and (cardinality(product_ids)=0 or prod.id=any(product_ids)); if not found then raise exception 'invalid or unavailable coupon'; end if; select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id; if c.max_redemptions is not null and used_count>=c.max_redemptions then raise exception 'coupon redemption limit reached'; end if; select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id and auth_user_id=uid; if used_count>=c.per_user_limit then raise exception 'coupon already used'; end if; if c.discount_type='percent' then discount:=least(subtotal,round(subtotal*(c.discount_value::numeric/100))); else discount:=least(subtotal,c.discount_value); end if; end if; total:=greatest(0,subtotal-discount); select coalesce((select (value#>>'{}')::int from public.app_settings where key='invoice.due_days'),7) into due_days; select coalesce((select trim(both '"' from value::text) from public.app_settings where key='billing.order_prefix'),'ORB-') into order_prefix; select coalesce((select trim(both '"' from value::text) from public.app_settings where key='invoice.prefix'),'INV-') into invoice_prefix; select id into cust from public.customers where auth_user_id=uid limit 1; ordno:=order_prefix||lpad(nextval('public.order_number_seq')::text,6,'0'); insert into public.orders(order_number,customer_id,auth_user_id,status,payment_status,fulfillment_status,subtotal_cents,total_cents,currency,metadata) values(ordno,cust,uid,case when total=0 then 'active' else 'pending_payment' end,case when total=0 then 'paid_free' else 'unpaid' end,'pending',subtotal,total,prod.currency,jsonb_build_object('configuration',p_configuration,'option_total_cents',option_total)) returning id into ord; insert into public.order_items(order_id,product_id,product_name,product_slug,license_product_key,quantity,unit_price_cents,total_cents,configuration) values(ord,prod.id,prod.name,prod.slug,prod.license_product_key,1,subtotal,total,p_configuration) returning id into item; invno:=invoice_prefix||lpad(nextval('public.invoice_number_seq')::text,6,'0'); insert into public.invoices(invoice_number,order_id,auth_user_id,status,subtotal_cents,discount_cents,total_cents,paid_cents,currency,due_at,paid_at) values(invno,ord,uid,case when total=0 then 'paid' else 'unpaid' end,subtotal,discount,total,case when total=0 then 0 else 0 end,prod.currency,case when total=0 then now() else now()+make_interval(days=>due_days) end,case when total=0 then now() else null end) returning id into inv; insert into public.invoice_items(invoice_id,order_item_id,description,quantity,unit_price_cents,total_cents) values(inv,item,prod.name,1,subtotal,total); if c.id is not null then insert into public.coupon_redemptions(coupon_id,invoice_id,auth_user_id,discount_cents) values(c.id,inv,uid,discount); end if; if total=0 then perform public.grant_paid_order_entitlements(ord,uid); end if; return jsonb_build_object('order_id',ord,'order_number',ordno,'invoice_id',inv,'invoice_number',invno,'total_cents',total,'discount_cents',discount,'option_total_cents',option_total,'paid',total=0); end $function$\n\nCREATE OR REPLACE FUNCTION public.create_support_ticket(p_department_id uuid, p_subject text, p_priority text, p_body text, p_related_order_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); tid uuid; num bigint; mid uuid;\nbegin\n if uid is null then raise exception 'authentication required'; end if;\n if coalesce(trim(p_subject),'')='' or coalesce(trim(p_body),'')='' then raise exception 'subject and message are required'; end if;\n if p_priority not in ('low','normal','high','urgent') then raise exception 'invalid priority'; end if;\n if not exists(select 1 from public.support_departments where id=p_department_id and enabled=true and allow_direct_create=true) then raise exception 'this department cannot be selected when opening a ticket'; end if;\n if p_related_order_id is not null and not exists(select 1 from public.orders where id=p_related_order_id and auth_user_id=uid) then raise exception 'order not found'; end if;\n insert into public.support_tickets(user_id,department_id,subject,status,priority,source,related_order_id,last_client_reply_at,last_reply_at)\n values(uid,p_department_id,trim(p_subject),'open',p_priority,'portal',p_related_order_id,now(),now()) returning id,ticket_number into tid,num;\n insert into public.support_ticket_messages(ticket_id,author_user_id,author_role,body,internal_note,attachments)\n values(tid,uid,'user',p_body,false,'[]'::jsonb) returning id into mid;\n perform public.support_emit_system_message(tid,'welcome','{}'::jsonb);\n insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail)\n values(tid,uid,'created',jsonb_build_object('priority',p_priority,'department_id',p_department_id,'message_id',mid));\n return jsonb_build_object('id',tid,'ticket_number',num);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.create_wallet_recharge(p_amount_cents bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  uid uuid:=auth.uid();\n  rid uuid;\n  receipt text;\n  currency text:='AUD';\n  minc bigint:=500;\n  maxc bigint:=100000;\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  select coalesce((select (value#>>'{}')::bigint from public.app_settings where key='billing.minimum_credit_topup_cents'),500) into minc;\n  select coalesce((select (value#>>'{}')::bigint from public.app_settings where key='billing.maximum_credit_topup_cents'),100000) into maxc;\n  select coalesce((select trim(both '"' from value::text) from public.app_settings where key='billing.currency'),'AUD') into currency;\n  if p_amount_cents<minc or p_amount_cents>maxc then raise exception 'wallet recharge must be between % and % cents',minc,maxc; end if;\n  receipt:='WAL-RCPT-'||lpad(nextval('public.wallet_recharge_number_seq')::text,6,'0');\n  insert into public.wallet_recharges(receipt_number,auth_user_id,amount_cents,currency,status,metadata)\n  values(receipt,uid,p_amount_cents,upper(currency),'pending',jsonb_build_object('source','account_settings'))\n  returning id into rid;\n  return jsonb_build_object('ok',true,'recharge_id',rid,'receipt_number',receipt,'amount_cents',p_amount_cents,'currency',upper(currency),'status','pending');\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public."current_role"()\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select coalesce(\n    (\n      select sg.slug\n      from public.staff_members sm\n      join public.staff_member_groups smg on smg.user_id=sm.user_id\n      join public.staff_groups sg on sg.id=smg.group_id\n      where sm.user_id=auth.uid() and sm.status='active'\n      order by smg.is_primary desc, sg.sort_order asc, sg.slug asc\n      limit 1\n    ),\n    case when exists(select 1 from public.staff_members sm where sm.user_id=auth.uid()) then 'user' else\n      coalesce((select case when up.role <> 'user' then up.role else null end from public.user_profiles up where up.id=auth.uid()),'user') end\n  )\n$function$\n\nCREATE OR REPLACE FUNCTION public.customer_close_support_ticket(p_ticket_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare t public.support_tickets%rowtype; can_close boolean;\nbegin\n  select * into t from public.support_tickets where id=p_ticket_id and user_id=auth.uid() for update;\n  if not found then raise exception 'ticket not found'; end if;\n  if t.status='closed' then return jsonb_build_object('ok',true,'status','closed'); end if;\n  select d.client_can_close into can_close from public.support_departments d where d.id=t.department_id;\n  if coalesce(can_close,false)=false then raise exception 'this support department requires staff to close the ticket'; end if;\n  update public.support_tickets set status='closed',closed_at=now(),closed_by=auth.uid(),updated_at=now() where id=t.id;\n  perform public.support_emit_system_message(t.id,'closing','{}'::jsonb);\n  insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail) values(t.id,auth.uid(),'customer_closed','{}'::jsonb);\n  return jsonb_build_object('ok',true,'status','closed');\nend $function$\n\nCREATE OR REPLACE FUNCTION public.customer_order_cancellation_context(p_order_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  uid uuid:=auth.uid();\n  o public.orders%rowtype;\n  inv public.invoices%rowtype;\n  req jsonb;\n  sub jsonb;\n  committed bigint:=0;\n  refundable bigint:=0;\n  refund_required boolean:=false;\n  original_available boolean:=false;\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  select * into o from public.orders where id=p_order_id and auth_user_id=uid;\n  if not found then raise exception 'order not found'; end if;\n\n  select * into inv from public.invoices where order_id=o.id and auth_user_id=uid order by created_at desc limit 1;\n  if inv.id is not null then\n    select coalesce(sum(amount_cents),0) into committed\n      from public.invoice_refunds\n     where invoice_id=inv.id and status in ('pending','processing','completed','succeeded');\n    refundable:=greatest(0,coalesce(inv.paid_cents,0)-committed);\n    refund_required:=inv.status='partial' and coalesce(inv.paid_cents,0)>0 and refundable>0 and o.activated_at is null;\n    if refund_required then\n      select exists(\n        select 1\n          from public.invoice_payments p\n          left join lateral (\n            select coalesce(sum(r.amount_cents),0) refunded\n              from public.invoice_refunds r\n             where r.payment_id=p.id and r.status in ('pending','processing','completed','succeeded')\n          ) rr on true\n         where p.invoice_id=inv.id and p.status='completed'\n           and p.method in ('account_credit','stripe','paypal')\n           and p.amount_cents>coalesce(rr.refunded,0)\n      ) into original_available;\n    end if;\n  end if;\n\n  select to_jsonb(r) into req from (\n    select id,status,reason,staff_note,requested_timing,scheduled_for,reviewed_at,processed_at,created_at,\n           refund_preference,refund_status,refund_amount_cents,refund_processed_cents,refund_last_error,refund_completed_at\n      from public.order_cancellation_requests\n     where order_id=o.id order by created_at desc limit 1\n  ) r;\n  select to_jsonb(s) into sub from (\n    select id,status,interval_unit,interval_count,next_charge_at,cancel_at_period_end\n      from public.payment_subscriptions\n     where order_id=o.id and coalesce(status,'') not in ('cancelled','canceled','terminated','ended','inactive')\n     order by created_at desc limit 1\n  ) s;\n\n  return jsonb_build_object(\n    'request',req,'subscription',sub,'is_subscription',sub is not null,\n    'can_end_of_cycle',coalesce((sub->>'next_charge_at') is not null,false),\n    'invoice',case when inv.id is null then null else jsonb_build_object(\n      'id',inv.id,'invoice_number',inv.invoice_number,'status',inv.status,'total_cents',inv.total_cents,\n      'paid_cents',inv.paid_cents,'currency',inv.currency,'refundable_cents',refundable\n    ) end,\n    'order_activated',o.activated_at is not null,\n    'refund_required',refund_required,\n    'refund_amount_cents',case when refund_required then refundable else 0 end,\n    'can_refund_original',original_available,\n    'can_refund_wallet',refund_required\n  );\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.customer_reply_support_ticket(p_ticket_id uuid, p_body text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare t public.support_tickets%rowtype; mid uuid; was_closed boolean; begin if nullif(btrim(p_body),'') is null then raise exception 'reply is required'; end if; select * into t from public.support_tickets where id=p_ticket_id and user_id=auth.uid() for update; if not found then raise exception 'ticket not found'; end if; was_closed:=t.status='closed'; if was_closed then update public.support_tickets set status='open',closed_at=null,closed_by=null,reopened_at=now(),updated_at=now() where id=t.id; perform public.support_emit_system_message(t.id,'reopened','{}'::jsonb); insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail) values(t.id,auth.uid(),'customer_reopened','{}'::jsonb); end if; insert into public.support_ticket_messages(ticket_id,author_user_id,author_role,body,internal_note) values(t.id,auth.uid(),'user',p_body,false) returning id into mid; update public.support_tickets set status='staff_reply',last_reply_at=now(),last_client_reply_at=now(),updated_at=now() where id=t.id; return jsonb_build_object('ok',true,'message_id',mid,'reopened',was_closed,'status','staff_reply'); end $function$\n\nCREATE OR REPLACE FUNCTION public.customer_retrieve_website_key(p_binding_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare k text; begin select license_key into k from public.license_key_delivery where binding_id=p_binding_id and auth_user_id=auth.uid(); if k is null then raise exception 'no unretrieved website licence key available'; end if; delete from public.license_key_delivery where binding_id=p_binding_id and auth_user_id=auth.uid(); return jsonb_build_object('license_key',k); end $function$\n\nCREATE OR REPLACE FUNCTION public.default_invoice_policy()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$ begin if new.metadata is null then new.metadata:='{}'::jsonb; end if; if not (new.metadata ? 'billing_reason') and new.order_id is not null then new.metadata:=new.metadata||jsonb_build_object('billing_reason','new_order','suspends_license',false); end if; return new; end $function$\n\nCREATE OR REPLACE FUNCTION public.dispatch_mail_event_outbox()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'net'\nAS $function$\ndeclare\n  r record;\n  n integer:=0;\n  v_site text;\nbegin\n  select rtrim(coalesce(value #>> '{}','https://orbitfs.cc'),'/')\n    into v_site\n    from public.app_settings\n    where key='site.public_url';\n  v_site:=coalesce(nullif(v_site,''),'https://orbitfs.cc');\n\n  update public.mail_event_outbox\n    set state='failed',last_error=coalesce(last_error,'Processing timed out'),next_attempt_at=now()\n    where state='processing' and next_attempt_at<=now();\n\n  for r in\n    select id,dispatch_token\n    from public.mail_event_outbox\n    where state in ('pending','failed') and next_attempt_at<=now() and attempts<10\n    order by created_at\n    limit 25\n    for update skip locked\n  loop\n    update public.mail_event_outbox\n      set attempts=attempts+1,next_attempt_at=now()+interval '5 minutes'\n      where id=r.id;\n    perform net.http_post(\n      url:=v_site||'/api/mail/outbox',\n      body:=jsonb_build_object('id',r.id,'token',r.dispatch_token),\n      headers:='{"Content-Type":"application/json"}'::jsonb,\n      timeout_milliseconds:=15000\n    );\n    n:=n+1;\n  end loop;\n  return n;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.enforce_staff_group_invariants()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if old.slug='superadmin' then\n    new.slug:='superadmin';\n    new.is_system:=true;\n    new.permissions:=coalesce(new.permissions,'{}'::jsonb) || jsonb_build_object('all',true,'admin.access',true,'settings.permissions',true);\n  end if;\n  return new;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.enqueue_mail_event(p_event_key text, p_related_type text, p_related_id text, p_auth_user_id uuid, p_payload jsonb, p_dedupe_key text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_id uuid;\nbegin\n  insert into public.mail_event_outbox(event_key,related_type,related_id,auth_user_id,payload,dedupe_key)\n  values(p_event_key,p_related_type,p_related_id,p_auth_user_id,coalesce(p_payload,'{}'::jsonb),p_dedupe_key)\n  on conflict(dedupe_key) do update set payload=excluded.payload\n  returning id into v_id;\n  return v_id;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.ensure_orbitfs_installation(p_binding_id uuid)\n RETURNS orbitfs_installations\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  b public.license_bindings%rowtype;\n  result public.orbitfs_installations%rowtype;\n  caller uuid:=auth.uid();\n  base_allowed boolean:=false;\n  cfg public.orbitfs_release_system_settings%rowtype;\n  reusable_id uuid;\nbegin\n  select * into cfg from public.orbitfs_release_system_settings where id='primary';\n  if not coalesce(cfg.enabled,false) or not coalesce(cfg.customer_deploy_enabled,false) then raise exception 'OrbitFS deployment system is currently disabled'; end if;\n  select * into b from public.license_bindings where id=p_binding_id and archived_at is null;\n  if not found then raise exception 'Licence not found'; end if;\n  if caller is null then raise exception 'Authentication required'; end if;\n  if b.auth_user_id<>caller and not public.has_permission('licenses.edit') then raise exception 'Not allowed to create this OrbitFS installation'; end if;\n  base_allowed:=b.license_product_key='orbitfs_base' or coalesce((b.components->>'orbitfs_base')::boolean,false) or coalesce((b.components->>'orbitfs_panel')::boolean,false);\n  if not base_allowed then raise exception 'This licence does not include OrbitFS Base'; end if;\n\n  select * into result from public.orbitfs_installations where license_binding_id=b.id and component_key='orbitfs_base';\n  if found then\n    if result.state='pending' then update public.orbitfs_installations set state='awaiting_supabase',updated_at=now() where id=result.id returning * into result; end if;\n    return result;\n  end if;\n\n  select i.id into reusable_id\n  from public.orbitfs_installations i\n  left join public.license_bindings oldb on oldb.id=i.license_binding_id\n  where i.auth_user_id=b.auth_user_id\n    and i.component_key='orbitfs_base'\n    and (oldb.id is null or oldb.archived_at is not null)\n  order by\n    case\n      when i.release_version is not null or i.state='ready' then 50\n      when i.vercel_project_id is not null then 40\n      when i.database_initialized_at is not null then 30\n      when i.supabase_project_ref is not null then 20\n      else 10\n    end desc,\n    i.updated_at desc\n  limit 1;\n\n  if reusable_id is not null then\n    update public.orbitfs_installations\n    set license_binding_id=b.id,\n        order_id=b.order_id,\n        order_item_id=b.order_item_id,\n        updated_at=now()\n    where id=reusable_id\n    returning * into result;\n    return result;\n  end if;\n\n  insert into public.orbitfs_installations(auth_user_id,license_binding_id,order_id,order_item_id,component_key,installation_id,state)\n  values(b.auth_user_id,b.id,b.order_id,b.order_item_id,'orbitfs_base','ofs_'||replace(gen_random_uuid()::text,'-',''),'awaiting_supabase') returning * into result;\n  return result;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.expire_account_enforcement()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  ids uuid[];\n  restored integer:=0;\n  users_restored integer:=0;\nbegin\n  select array_agg(id) into ids\n  from public.user_profiles\n  where\n    (banned_at is not null and ban_expires_at is not null and ban_expires_at<=now())\n    or\n    (status='suspended' and banned_at is null and suspension_expires_at is not null and suspension_expires_at<=now());\n\n  if coalesce(array_length(ids,1),0)=0 then\n    return jsonb_build_object('users_restored',0,'licenses_restored',0);\n  end if;\n\n  update public.user_profiles\n     set status='active',suspension_reason=null,suspended_at=null,suspension_expires_at=null,\n         banned_at=null,ban_reason=null,ban_expires_at=null,updated_at=now()\n   where id=any(ids);\n  get diagnostics users_restored=row_count;\n\n  with changed as (\n    update public.license_bindings\n       set desired_state='active',\n           remote_state=case when api_source='website' then 'active' else remote_state end,\n           suspension_reason=null,\n           updated_at=now()\n     where auth_user_id=any(ids)\n       and archived_at is null\n       and desired_state='suspended'\n       and suspension_reason like 'account_enforcement:%'\n     returning id,auth_user_id,license_id,api_source\n  )\n  select count(*) into restored from changed;\n\n  insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source)\n  select b.id,b.auth_user_id,b.license_id,'unblock','account enforcement expired','account_enforcement'\n    from public.license_bindings b\n   where b.auth_user_id=any(ids)\n     and b.api_source<>'website'\n     and b.updated_at>now()-interval '1 minute'\n     and b.desired_state='active'\n     and not exists(select 1 from public.license_enforcement_queue q where q.binding_id=b.id and q.action='unblock' and q.state in ('queued','running'));\n\n  if restored>0 then perform public.bump_license_revision(); end if;\n  return jsonb_build_object('users_restored',users_restored,'licenses_restored',restored);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.finalize_cancellation_refund(p_request_id uuid, p_error text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  r public.order_cancellation_requests%rowtype;\n  inv public.invoices%rowtype;\n  committed bigint:=0;\n  processed_since bigint:=0;\n  has_pending boolean:=false;\n  st text;\nbegin\n  if not public.has_permission('customers.cancellations') then raise exception 'permission denied: customers.cancellations'; end if;\n  select * into r from public.order_cancellation_requests where id=p_request_id for update;\n  if not found then raise exception 'cancellation request not found'; end if;\n  select * into inv from public.invoices where order_id=r.order_id order by created_at desc limit 1;\n  select coalesce(sum(amount_cents),0),bool_or(status in ('pending','processing')) into committed,has_pending\n    from public.invoice_refunds where invoice_id=inv.id and status in ('pending','processing','completed','succeeded');\n  processed_since:=least(r.refund_amount_cents,greatest(0,committed-coalesce(r.refund_baseline_cents,0)));\n  if r.refund_amount_cents<=0 then st:='not_required';\n  elsif processed_since>=r.refund_amount_cents then st:=case when coalesce(has_pending,false) then 'processing' else 'completed' end;\n  elsif coalesce(btrim(p_error),'')<>'' then st:=case when processed_since>0 then 'partial_failed' else 'failed' end;\n  else st:='pending'; end if;\n  update public.order_cancellation_requests set refund_status=st,refund_processed_cents=processed_since,\n    refund_last_error=nullif(btrim(p_error),''),refund_completed_at=case when st='completed' then coalesce(refund_completed_at,now()) else refund_completed_at end,\n    updated_at=now() where id=r.id;\n  return jsonb_build_object('ok',true,'status',st,'processed_cents',processed_since,'target_cents',r.refund_amount_cents,'error',nullif(btrim(p_error),''));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.fulfill_gift_order_item(p_source_order_item_id uuid, p_recipient_user_id uuid, p_account_created boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare src public.order_items%rowtype; src_order public.orders%rowtype; gd public.gift_deliveries%rowtype; recipient_customer uuid; recipient_order uuid; recipient_item uuid; recipient_order_no text; clean_config jsonb; email text;\nbegin\n if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n select * into src from public.order_items where id=p_source_order_item_id; if not found then raise exception 'gift source item not found'; end if;\n select * into src_order from public.orders where id=src.order_id; if not found then raise exception 'gift source order not found'; end if;\n if src_order.payment_status not like 'paid%' and src_order.payment_status<>'paid_free' then raise exception 'gift order is not paid'; end if;\n select * into gd from public.gift_deliveries where source_order_item_id=src.id for update; if not found then raise exception 'gift delivery not found'; end if;\n if gd.status='delivered' then return jsonb_build_object('ok',true,'already_delivered',true,'recipient_order_id',gd.recipient_order_id); end if;\n select email into email from auth.users where id=p_recipient_user_id; if email is null then raise exception 'recipient user not found'; end if;\n if lower(email)<>lower(gd.recipient_email) then raise exception 'recipient account email does not match gift email'; end if;\n select id into recipient_customer from public.customers where auth_user_id=p_recipient_user_id limit 1;\n recipient_order_no:='GFT-'||lpad(nextval('public.order_number_seq')::text,6,'0');\n insert into public.orders(order_number,customer_id,auth_user_id,status,payment_status,fulfillment_status,subtotal_cents,total_cents,currency,metadata)\n values(recipient_order_no,recipient_customer,p_recipient_user_id,'active','paid_gift','pending',0,0,src_order.currency,jsonb_build_object('gift_received',true,'gift_source_order_id',src_order.id,'gift_source_order_number',src_order.order_number,'purchaser_user_id',gd.purchaser_user_id)) returning id into recipient_order;\n clean_config:=coalesce(src.configuration,'{}'::jsonb)-'gift'-'gift_recipient_email';\n insert into public.order_items(order_id,product_id,product_name,product_slug,license_product_key,quantity,unit_price_cents,total_cents,configuration,service_status,metadata)\n values(recipient_order,src.product_id,src.product_name,src.product_slug,src.license_product_key,src.quantity,0,0,clean_config,'pending',jsonb_build_object('gift_source_order_item_id',src.id,'gift_original_price_cents',src.total_cents)) returning id into recipient_item;\n perform public.grant_paid_order_entitlements(recipient_order,p_recipient_user_id);\n update public.gift_deliveries set recipient_user_id=p_recipient_user_id,recipient_order_id=recipient_order,status='delivered',account_created=p_account_created,error=null,delivered_at=now(),updated_at=now() where id=gd.id;\n update public.order_items set service_status='gift_delivered',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('gift_recipient_user_id',p_recipient_user_id,'gift_recipient_order_id',recipient_order) where id=src.id;\n if not exists(select 1 from public.gift_deliveries where source_order_id=src.order_id and status<>'delivered') then update public.orders set fulfillment_status='fulfilled',updated_at=now() where id=src.order_id; end if;\n return jsonb_build_object('ok',true,'recipient_order_id',recipient_order,'recipient_order_item_id',recipient_item,'recipient_user_id',p_recipient_user_id,'account_created',p_account_created);\nexception when others then\n update public.gift_deliveries set status='failed',error=sqlerrm,updated_at=now() where source_order_item_id=p_source_order_item_id;\n raise;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.get_my_staff_access()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select jsonb_build_object(\n    'is_staff', exists(select 1 from public.staff_members sm where sm.user_id=auth.uid() and sm.status='active'),\n    'status', coalesce((select sm.status from public.staff_members sm where sm.user_id=auth.uid()),'none'),\n    'primary_role', public.current_role(),\n    'groups', coalesce((\n      select jsonb_agg(jsonb_build_object('id',sg.id,'slug',sg.slug,'name',sg.name,'is_primary',smg.is_primary) order by smg.is_primary desc,sg.sort_order,sg.name)\n      from public.staff_member_groups smg\n      join public.staff_groups sg on sg.id=smg.group_id\n      join public.staff_members sm on sm.user_id=smg.user_id\n      where smg.user_id=auth.uid() and sm.status='active'\n    ),'[]'::jsonb),\n    'permissions', coalesce((\n      select jsonb_object_agg(k,true)\n      from (\n        select distinct key as k\n        from public.staff_member_groups smg\n        join public.staff_groups sg on sg.id=smg.group_id\n        join public.staff_members sm on sm.user_id=smg.user_id\n        cross join lateral jsonb_each_text(sg.permissions)\n        where smg.user_id=auth.uid() and sm.status='active' and value='true'\n        union\n        select 'mail.view'\n        where exists(\n          select 1 from public.mail_accounts a\n          join public.staff_members sm on sm.user_id=auth.uid() and sm.status='active'\n          where a.kind='personal' and a.active=true and a.assigned_user_id=auth.uid()\n        )\n        union\n        select 'mail.send'\n        where exists(\n          select 1 from public.mail_accounts a\n          join public.staff_members sm on sm.user_id=auth.uid() and sm.status='active'\n          where a.kind='personal' and a.active=true and a.assigned_user_id=auth.uid()\n        )\n      ) x\n    ),'{}'::jsonb)\n  )\n$function$\n\nCREATE OR REPLACE FUNCTION public.get_or_create_cart()\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); cid uuid; begin\n if uid is null then raise exception 'authentication required'; end if;\n select id into cid from public.shopping_carts where auth_user_id=uid;\n if cid is null then insert into public.shopping_carts(auth_user_id) values(uid) returning id into cid; end if;\n return cid;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.gift_recipient_lookup(p_email text)\n RETURNS uuid\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\n select id from auth.users where lower(email)=lower(trim(p_email)) limit 1\n$function$\n\nCREATE OR REPLACE FUNCTION public.grant_paid_order_entitlements(p_order_id uuid, p_user_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare approved boolean; has_gifts boolean;\nbegin\n if public.order_requires_manual_approval(p_order_id) then select coalesce(metadata->>'approval_state','')='approved' into approved from public.orders where id=p_order_id; if not coalesce(approved,false) then update public.orders set status='pending_approval',fulfillment_status='pending_approval',metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('approval_required',true,'approval_state','pending'),updated_at=now() where id=p_order_id; update public.order_items set service_status='pending_approval' where order_id=p_order_id; return; end if; end if;\n perform public.grant_paid_order_entitlements_core(p_order_id,p_user_id);\n update public.order_items set service_status=case when coalesce((configuration->>'gift')::boolean,false) then 'pending_gift' else 'active' end where order_id=p_order_id;\n select exists(select 1 from public.order_items where order_id=p_order_id and coalesce((configuration->>'gift')::boolean,false)) into has_gifts;\n update public.orders set status='active',fulfillment_status=case when has_gifts then 'pending_gift' when exists(select 1 from public.license_bindings where order_id=p_order_id and api_source='website' and archived_at is null) then 'fulfilled' else fulfillment_status end,activated_at=coalesce(activated_at,now()),metadata=(coalesce(metadata,'{}'::jsonb)-'provisioning_error'-'provisioning_failed_at'),updated_at=now() where id=p_order_id;\n perform public.sync_order_service_status(p_order_id);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.grant_paid_order_entitlements_core(p_order_id uuid, p_user_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'extensions'\nAS $function$\ndeclare r record; fid uuid; bid uuid; comp jsonb; has_base boolean; remote_id text; qid bigint; api_enabled boolean; api_mode text; k text;\nbegin\n select id,components,license_id into bid,comp,remote_id from public.license_bindings where auth_user_id=p_user_id and desired_state<>'revoked' order by (order_id=p_order_id) desc, created_at asc limit 1;\n has_base:=exists(select 1 from public.download_entitlements de join public.products p on p.id=de.product_id where de.auth_user_id=p_user_id and de.status='active' and p.license_product_key in ('orbitfs_panel','orbitfs_base'));\n for r in select oi.* from public.order_items oi where oi.order_id=p_order_id order by case when oi.license_product_key in ('orbitfs_panel','orbitfs_base') then 0 else 1 end,oi.id loop\n   if coalesce((r.configuration->>'gift')::boolean,false) then continue; end if;\n   select license_api_enabled,license_api_mode into api_enabled,api_mode from public.products where id=r.product_id;\n   if r.license_product_key not in ('orbitfs_panel','orbitfs_base') and not has_base then raise exception 'addon fulfilment requires an active OrbitFS Base entitlement'; end if;\n   fid:=null;\n   insert into public.license_fulfillments(order_id,order_item_id,auth_user_id,state,metadata) select r.order_id,r.id,p_user_id,'pending',jsonb_build_object('license_product_key',r.license_product_key,'configuration',r.configuration) where not exists(select 1 from public.license_fulfillments lf where lf.order_item_id=r.id) returning id into fid;\n   if fid is null then select id into fid from public.license_fulfillments where order_item_id=r.id limit 1; end if;\n   if bid is null then\n     if r.license_product_key not in ('orbitfs_panel','orbitfs_base') then raise exception 'OrbitFS Base licence binding is missing'; end if;\n     comp:=jsonb_build_object('orbitfs_base',true);\n     if api_enabled and api_mode='website' then\n       k:='OFS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4));\n       insert into public.license_bindings(auth_user_id,fulfillment_id,order_id,order_item_id,license_product_key,desired_state,remote_state,components,label,license_key_hash,license_key_last4,api_source) values(p_user_id,fid,p_order_id,r.id,'orbitfs_base','active','active',comp,'OrbitFS licence',encode(digest(k,'sha256'),'hex'),right(k,4),'website') returning id,license_id into bid,remote_id;\n       insert into public.license_key_delivery(binding_id,auth_user_id,license_key) values(bid,p_user_id,k) on conflict(binding_id) do update set license_key=excluded.license_key,created_at=now();\n       update public.license_fulfillments set state='fulfilled',metadata=metadata||jsonb_build_object('engine','website','binding_id',bid),updated_at=now() where id=fid; perform public.bump_license_revision();\n     else\n       insert into public.license_bindings(auth_user_id,fulfillment_id,order_id,order_item_id,license_product_key,desired_state,remote_state,components,api_source) values(p_user_id,fid,p_order_id,r.id,'orbitfs_base','pending','unknown',comp,'legacy') returning id,license_id into bid,remote_id;\n       insert into public.license_enforcement_queue(binding_id,auth_user_id,action,reason,source,payload) values(bid,p_user_id,'issue','paid Base entitlement','payment',jsonb_build_object('components',comp)) returning id into qid;\n     end if;\n     has_base:=true;\n   else\n     comp:=coalesce(comp,'{}'::jsonb)||jsonb_build_object(case r.license_product_key when 'orbitfs_panel' then 'orbitfs_base' when 'orbitfs_sorter' then 'orbitfs_apex' else r.license_product_key end,true);\n     update public.license_bindings set components=comp,updated_at=now() where id=bid returning license_id into remote_id;\n     if exists(select 1 from public.license_bindings where id=bid and api_source='website') then update public.license_fulfillments set state='fulfilled',metadata=metadata||jsonb_build_object('engine','website','binding_id',bid),updated_at=now() where id=fid; perform public.bump_license_revision();\n     elsif remote_id is null then update public.license_enforcement_queue set action='issue',payload=jsonb_build_object('components',comp),reason='paid products pending initial OrbitFS licence issue' where id=(select q.id from public.license_enforcement_queue q where q.binding_id=bid and q.state='queued' and q.action in ('issue','provision_license') order by q.id desc limit 1); if not found then insert into public.license_enforcement_queue(binding_id,auth_user_id,action,reason,source,payload) values(bid,p_user_id,'issue','paid products pending initial OrbitFS licence issue','payment',jsonb_build_object('components',comp)); end if;\n     else insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source,payload) select b.id,b.auth_user_id,b.license_id,'update_components','paid addon entitlement','payment',jsonb_build_object('components',comp) from public.license_bindings b where b.id=bid and not exists(select 1 from public.license_enforcement_queue q where q.binding_id=b.id and q.state in ('queued','running') and q.action='update_components' and q.payload->'components'=comp); end if;\n   end if;\n   update public.license_fulfillments set metadata=metadata||jsonb_build_object('binding_id',bid),updated_at=now() where id=fid;\n   insert into public.download_entitlements(auth_user_id,order_id,order_item_id,product_id,status,metadata) values(p_user_id,p_order_id,r.id,r.product_id,'active',jsonb_build_object('license_product_key',case r.license_product_key when 'orbitfs_panel' then 'orbitfs_base' when 'orbitfs_sorter' then 'orbitfs_apex' else r.license_product_key end,'binding_id',bid)) on conflict(auth_user_id,order_item_id) do update set status='active',revoked_at=null,reason=null;\n end loop;\n update public.orders set fulfillment_status=case when exists(select 1 from public.license_bindings where id=bid and api_source='website') then 'fulfilled' else 'queued' end,updated_at=now() where id=p_order_id;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ begin insert into public.user_profiles(id,first_name,last_name,display_name) values(new.id,new.raw_user_meta_data->>'first_name',new.raw_user_meta_data->>'last_name',coalesce(new.raw_user_meta_data->>'display_name',new.raw_user_meta_data->>'first_name')) on conflict (id) do nothing; insert into public.account_balances(user_id) values(new.id) on conflict (user_id) do nothing; insert into public.customers(auth_user_id,email,name) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'display_name',new.email)) on conflict (auth_user_id) do update set email=excluded.email,name=excluded.name,updated_at=now(); insert into public.user_preferences(user_id) values(new.id) on conflict (user_id) do nothing; return new; end; $function$\n\nCREATE OR REPLACE FUNCTION public.has_permission(p_permission text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare result boolean;\nbegin\n  if exists(select 1 from public.staff_members where user_id=auth.uid()) then\n    return exists (\n      select 1\n      from public.staff_members sm\n      join public.staff_member_groups smg on smg.user_id=sm.user_id\n      join public.staff_groups sg on sg.id=smg.group_id\n      where sm.user_id=auth.uid() and sm.status='active'\n        and (coalesce((sg.permissions->>'all')::boolean,false) or coalesce((sg.permissions->>p_permission)::boolean,false))\n    );\n  end if;\n  select coalesce((rp.permissions->>'all')::boolean,false) or coalesce((rp.permissions->>p_permission)::boolean,false)\n    into result from public.user_profiles up join public.role_permissions rp on rp.role=up.role\n    where up.id=auth.uid() and up.role <> 'user';\n  return coalesce(result,false);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.invoice_paid_entitlement_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  wallet_amount bigint;\n  wallet_balance bigint;\nbegin\n  if new.status='paid' and old.status is distinct from 'paid' then\n    if coalesce((new.metadata->>'wallet_recharge')::boolean,false) then\n      if not coalesce((new.metadata->>'wallet_credited')::boolean,false) then\n        wallet_amount:=coalesce((new.metadata->>'wallet_amount_cents')::bigint,new.total_cents);\n        wallet_balance:=public.wallet_credit(\n          new.auth_user_id,\n          wallet_amount,\n          'Account Credit - Recharge',\n          'invoice',\n          new.id::text,\n          jsonb_build_object('invoice_number',new.invoice_number,'wallet_recharge',true),\n          new.auth_user_id\n        );\n        update public.invoices\n          set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('wallet_credited',true,'wallet_balance_after_cents',wallet_balance),\n              updated_at=now()\n          where id=new.id;\n      end if;\n      update public.orders\n        set status='completed',payment_status=case when payment_status='paid_admin_override' then payment_status else 'paid' end,\n            fulfillment_status='fulfilled',activated_at=coalesce(activated_at,now()),updated_at=now()\n        where id=new.order_id;\n      update public.order_items set service_status='fulfilled' where order_id=new.order_id;\n      return new;\n    end if;\n\n    if public.order_requires_manual_approval(new.order_id) then\n      update public.orders\n        set status='pending_approval',payment_status=case when payment_status='paid_admin_override' then payment_status else 'paid' end,\n            fulfillment_status='pending_approval',\n            metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('approval_required',true,'approval_state','pending','paid_at',coalesce(new.paid_at,now())),updated_at=now()\n        where id=new.order_id;\n      update public.order_items set service_status='pending_approval' where order_id=new.order_id;\n    else\n      update public.orders\n        set payment_status=case when payment_status='paid_admin_override' then payment_status else 'paid' end,\n            status='active',updated_at=now()\n        where id=new.order_id;\n      begin\n        perform public.grant_paid_order_entitlements(new.order_id,new.auth_user_id);\n        update public.orders set metadata=coalesce(metadata,'{}'::jsonb)-'provisioning_error'-'provisioning_failed_at',updated_at=now() where id=new.order_id;\n      exception when others then\n        update public.orders\n          set status='paid_pending_service',fulfillment_status='blocked',\n              metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('provisioning_error',sqlerrm,'provisioning_failed_at',now()),updated_at=now()\n          where id=new.order_id;\n        update public.order_items set service_status='blocked' where order_id=new.order_id;\n      end;\n    end if;\n  end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.invoice_refund_status_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  perform public.sync_invoice_refund_status(coalesce(new.invoice_id,old.invoice_id));\n  return coalesce(new,old);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.is_admin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select public.current_role() in ('admin','superadmin') $function$\n\nCREATE OR REPLACE FUNCTION public.is_staff()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select public.current_role() in ('support','admin','superadmin') $function$\n\nCREATE OR REPLACE FUNCTION public.is_superadmin()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select public.current_role()='superadmin' $function$\n\nCREATE OR REPLACE FUNCTION public.is_support()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select public.current_role()='support' $function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_create_account(p_address text, p_display_name text, p_kind text DEFAULT 'shared'::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_address text:=lower(trim(coalesce(p_address,'')));\n  v_display_name text:=trim(coalesce(p_display_name,''));\n  v_kind text:=trim(coalesce(p_kind,'shared'));\nbegin\n  if not public.is_staff() or not public.has_permission('mail.settings') then\n    raise exception 'Mail settings permission required';\n  end if;\n  if v_address='' or v_address !~ '^[^@[:space:]]+@[^@[:space:]]+\\.[^@[:space:]]+$' then\n    raise exception 'A valid mailbox address is required';\n  end if;\n  if v_display_name='' then v_display_name:=split_part(v_address,'@',1); end if;\n  if v_kind='' then v_kind:='shared'; end if;\n\n  insert into public.mail_accounts(address,display_name,kind,active)\n  values(v_address,v_display_name,v_kind,true);\n  return true;\nexception\n  when unique_violation then raise exception 'Mailbox already exists';\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_create_account(p_address text, p_display_name text, p_kind text, p_assigned_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_address text:=lower(trim(coalesce(p_address,'')));\n  v_display_name text:=trim(coalesce(p_display_name,''));\n  v_kind text:=lower(trim(coalesce(p_kind,'shared')));\n  v_assignee uuid:=p_assigned_user_id;\nbegin\n  if not public.is_staff() or not public.has_permission('mail.settings') then\n    raise exception 'Mail settings permission required';\n  end if;\n  if v_address='' or v_address !~ '^[^@[:space:]]+@[^@[:space:]]+\\.[^@[:space:]]+$' then\n    raise exception 'A valid mailbox address is required';\n  end if;\n  if v_kind not in ('shared','no-reply','personal','system') then\n    raise exception 'Invalid mailbox type';\n  end if;\n  if v_kind='personal' then\n    if v_assignee is null or not exists(select 1 from public.staff_members where user_id=v_assignee and status='active') then\n      raise exception 'Personal mailboxes require an active staff member';\n    end if;\n  else\n    v_assignee:=null;\n  end if;\n  if v_display_name='' then v_display_name:=split_part(v_address,'@',1); end if;\n\n  insert into public.mail_accounts(address,display_name,kind,active,assigned_user_id)\n  values(v_address,v_display_name,v_kind,true,v_assignee);\n  return true;\nexception\n  when unique_violation then raise exception 'Mailbox already exists';\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_delete_account(p_address text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_address text:=lower(trim(coalesce(p_address,'')));\nbegin\n  if not public.is_staff() or not public.has_permission('mail.settings') then\n    raise exception 'Mail settings permission required';\n  end if;\n  if v_address='' then raise exception 'Mailbox address is required'; end if;\n\n  delete from public.mail_accounts where lower(address)=v_address;\n  if not found then raise exception 'Mailbox not found'; end if;\n  return true;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_queue_action(p_action text, p_outbox_id uuid DEFAULT NULL::uuid, p_log_id uuid DEFAULT NULL::uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare n integer:=0; m integer:=0;\nbegin\n if not (public.is_staff() and (public.has_permission('all') or public.has_permission('mail.queue.manage'))) then raise exception 'Mail queue management denied'; end if;\n if p_action='retry' then\n  update public.mail_event_outbox set state='pending',attempts=0,next_attempt_at=now(),last_error=null,processed_at=null where id=p_outbox_id and state<>'sent'; get diagnostics n=row_count; return jsonb_build_object('ok',n>0,'updated',n);\n elsif p_action='clear' then\n  update public.mail_delivery_log l set status='cancelled',error=coalesce(l.error,'Cleared from Mail queue by administrator') where l.status='preparing' and exists(select 1 from public.mail_event_outbox e where e.id=p_outbox_id and e.event_key=l.event_type and e.related_type=l.related_type and e.related_id=l.related_id);\n  delete from public.mail_event_outbox where id=p_outbox_id and state<>'sent'; get diagnostics n=row_count; return jsonb_build_object('ok',n>0,'cleared',n);\n elsif p_action='clear_queue' then\n  update public.mail_delivery_log l set status='cancelled',error=coalesce(l.error,'Queue cleared by administrator') where l.status='preparing' and exists(select 1 from public.mail_event_outbox e where e.event_key=l.event_type and e.related_type=l.related_type and e.related_id=l.related_id and e.state<>'sent'); get diagnostics m=row_count;\n  delete from public.mail_event_outbox where state<>'sent'; get diagnostics n=row_count; return jsonb_build_object('ok',true,'cleared_queue_items',n,'cancelled_preparing_logs',m);\n elsif p_action='retry_all' then\n  update public.mail_event_outbox set state='pending',attempts=0,next_attempt_at=now(),last_error=null,processed_at=null where state in ('failed','processing') or (state='pending' and next_attempt_at<now()-interval '5 minutes'); get diagnostics n=row_count; return jsonb_build_object('ok',true,'updated',n);\n elsif p_action='clear_failed' then\n  update public.mail_delivery_log set status='cancelled',error=coalesce(error,'Cleared from Mail queue by administrator') where status='preparing' and created_at<now()-interval '5 minutes';\n  delete from public.mail_event_outbox where state='failed' and attempts>=10; get diagnostics n=row_count; return jsonb_build_object('ok',true,'cleared',n);\n elsif p_action='clear_log' then\n  update public.mail_delivery_log set status='cancelled',error=coalesce(error,'Cleared by administrator') where id=p_log_id and status='preparing'; get diagnostics n=row_count; return jsonb_build_object('ok',n>0,'updated',n);\n end if;\n raise exception 'Unknown mail queue action';\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_queue_snapshot()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nselect case when public.is_staff() and (public.has_permission('all') or public.has_permission('mail.queue.view') or public.has_permission('mail.queue.manage')) then\n jsonb_build_object(\n  'can_manage',public.has_permission('all') or public.has_permission('mail.queue.manage'),\n  'summary',jsonb_build_object(\n    'pending',(select count(*) from public.mail_event_outbox where state='pending'),\n    'processing',(select count(*) from public.mail_event_outbox where state='processing'),\n    'failed',(select count(*) from public.mail_event_outbox where state='failed'),\n    'stuck',(select count(*) from public.mail_event_outbox where (state='processing' and next_attempt_at<=now()) or (state in ('pending','failed') and next_attempt_at<now()-interval '5 minutes'))\n  ),\n  'queue',coalesce((select jsonb_agg(to_jsonb(q) order by q.created_at desc) from (\n    select e.id,e.event_key,e.related_type,e.related_id,e.auth_user_id,e.state,e.attempts,e.next_attempt_at,e.last_error,e.created_at,e.processed_at,\n      case when (e.state='processing' and e.next_attempt_at<=now()) or (e.state in ('pending','failed') and e.next_attempt_at<now()-interval '5 minutes') then true else false end stuck,\n      l.id log_id,l.reference_id,l.status delivery_status,l.recipient,l.sender,l.subject,l.provider_id,l.error delivery_error,l.sent_at,l.created_at delivery_created_at\n    from public.mail_event_outbox e\n    left join lateral (select * from public.mail_delivery_log l where l.event_type=e.event_key and l.related_type=e.related_type and l.related_id=e.related_id order by l.created_at desc limit 1) l on true\n    where e.state<>'sent' order by e.created_at desc limit 200\n  ) q),'[]'::jsonb),\n  'stuck_logs',coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (\n    select l.* from public.mail_delivery_log l where l.status='preparing' and l.created_at<now()-interval '5 minutes' order by l.created_at desc limit 100\n  ) x),'[]'::jsonb)\n ) else null end\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_save_automation(p_event_key text, p_template_key text, p_enabled boolean)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n if not public.has_permission('mail.settings') then raise exception 'permission denied: mail.settings'; end if;\n if not exists(select 1 from public.mail_automations where event_key=p_event_key) then raise exception 'unknown mail automation event'; end if;\n if p_template_key is not null and not exists(select 1 from public.mail_templates where template_key=p_template_key) then raise exception 'unknown mail template'; end if;\n update public.mail_automations set template_key=p_template_key,enabled=coalesce(p_enabled,false),updated_at=now(),updated_by=auth.uid() where event_key=p_event_key;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_save_settings(p_rows jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare r jsonb;\nbegin\n if not public.is_staff() or not public.has_permission('mail.settings') then raise exception 'Mail settings permission required'; end if;\n for r in select * from jsonb_array_elements(coalesce(p_rows,'[]'::jsonb)) loop\n   insert into public.mail_settings(key,value,updated_at) values(r->>'key',coalesce(r->'value','{}'::jsonb),now())\n   on conflict(key) do update set value=excluded.value,updated_at=now();\n end loop;\n return true;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_set_access(p_account text, p_user_id uuid, p_can_view boolean, p_can_send boolean, p_can_manage boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare aid uuid;\nbegin\n if not public.is_staff() or not public.has_permission('mail.users') then raise exception 'Mail user permission required'; end if;\n select id into aid from public.mail_accounts where lower(address)=lower(p_account) limit 1;\n if aid is null then raise exception 'Mailbox not found'; end if;\n if not p_can_view and not p_can_send and not p_can_manage then\n   delete from public.mail_account_access where mail_account_id=aid and user_id=p_user_id;\n else\n   insert into public.mail_account_access(mail_account_id,user_id,can_view,can_send,can_manage)\n   values(aid,p_user_id,p_can_view,p_can_send,p_can_manage)\n   on conflict(mail_account_id,user_id) do update set can_view=excluded.can_view,can_send=excluded.can_send,can_manage=excluded.can_manage;\n end if;\n return true;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_snapshot()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n select case when public.is_staff() and (\n   public.has_permission('all') or public.has_permission('mail.admin') or public.has_permission('mail.settings')\n   or public.has_permission('mail.templates') or public.has_permission('mail.queue.view') or public.has_permission('mail.queue.manage')\n ) then jsonb_build_object(\n   'capabilities',jsonb_build_object(\n     'admin',public.has_permission('all') or public.has_permission('mail.admin'),\n     'settings',public.has_permission('all') or public.has_permission('mail.settings'),\n     'templates',public.has_permission('all') or public.has_permission('mail.templates'),\n     'queueView',public.has_permission('all') or public.has_permission('mail.queue.view') or public.has_permission('mail.queue.manage'),\n     'queueManage',public.has_permission('all') or public.has_permission('mail.queue.manage')\n   ),\n   'accounts',case when public.has_permission('all') or public.has_permission('mail.settings') then coalesce((select jsonb_agg(to_jsonb(a) order by a.address) from public.mail_accounts a),'[]'::jsonb) else '[]'::jsonb end,\n   'settings',case when public.has_permission('all') or public.has_permission('mail.settings') then coalesce((select jsonb_agg(to_jsonb(s) order by s.key) from public.mail_settings s),'[]'::jsonb) else '[]'::jsonb end,\n   'templates',case when public.has_permission('all') or public.has_permission('mail.templates') or public.has_permission('mail.settings') then coalesce((select jsonb_agg(to_jsonb(t) order by t.category,t.name) from public.mail_templates t),'[]'::jsonb) else '[]'::jsonb end,\n   'automations',case when public.has_permission('all') or public.has_permission('mail.settings') then coalesce((select jsonb_agg(to_jsonb(a) order by a.category,a.name) from public.mail_automations a),'[]'::jsonb) else '[]'::jsonb end,\n   'users',case when public.has_permission('all') or public.has_permission('mail.settings') then coalesce((\n     select jsonb_agg(jsonb_build_object(\n       'id',sm.user_id,\n       'display_name',coalesce(nullif(trim(up.display_name),''),nullif(trim(concat_ws(' ',up.first_name,up.last_name)),''),u.email),\n       'email',u.email,\n       'title',sm.title,\n       'department',sm.department\n     ) order by coalesce(nullif(trim(up.display_name),''),nullif(trim(concat_ws(' ',up.first_name,up.last_name)),''),u.email))\n     from public.staff_members sm\n     left join public.user_profiles up on up.id=sm.user_id\n     left join auth.users u on u.id=sm.user_id\n     where sm.status='active'\n   ),'[]'::jsonb) else '[]'::jsonb end,\n   'access','[]'::jsonb,\n   'logs',case when public.has_permission('all') or public.has_permission('mail.admin') or public.has_permission('mail.queue.view') or public.has_permission('mail.queue.manage') then coalesce((select jsonb_agg(to_jsonb(l) order by l.created_at desc) from (select * from public.mail_delivery_log order by created_at desc limit 50) l),'[]'::jsonb) else '[]'::jsonb end\n ) else null end\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_update_account(p_address text, p_display_name text, p_kind text, p_active boolean)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n if not public.is_staff() or not public.has_permission('mail.settings') then raise exception 'Mail settings permission required'; end if;\n update public.mail_accounts set display_name=coalesce(nullif(trim(p_display_name),''),display_name),kind=coalesce(nullif(trim(p_kind),''),kind),active=p_active,updated_at=now() where lower(address)=lower(p_address);\n if not found then raise exception 'Mailbox not found'; end if;\n return true;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_update_account(p_address text, p_display_name text, p_kind text, p_active boolean, p_assigned_user_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_kind text:=lower(trim(coalesce(p_kind,'shared')));\n  v_assignee uuid:=p_assigned_user_id;\nbegin\n  if not public.is_staff() or not public.has_permission('mail.settings') then\n    raise exception 'Mail settings permission required';\n  end if;\n  if v_kind not in ('shared','no-reply','personal','system') then\n    raise exception 'Invalid mailbox type';\n  end if;\n  if v_kind='personal' then\n    if v_assignee is null or not exists(select 1 from public.staff_members where user_id=v_assignee and status='active') then\n      raise exception 'Personal mailboxes require an active staff member';\n    end if;\n  else\n    v_assignee:=null;\n  end if;\n\n  update public.mail_accounts\n  set display_name=coalesce(nullif(trim(p_display_name),''),display_name),\n      kind=v_kind,\n      active=p_active,\n      assigned_user_id=v_assignee,\n      updated_at=now()\n  where lower(address)=lower(p_address);\n  if not found then raise exception 'Mailbox not found'; end if;\n  return true;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_admin_upsert_template(p_template jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n if not public.is_staff() or not public.has_permission('mail.templates') then raise exception 'Mail template permission required'; end if;\n if coalesce(p_template->>'template_key','')='' or coalesce(p_template->>'name','')='' or coalesce(p_template->>'subject','')='' then raise exception 'Template key, name and subject are required'; end if;\n insert into public.mail_templates(template_key,name,category,subject,html,text_body,from_account,enabled,updated_at)\n values(p_template->>'template_key',p_template->>'name',coalesce(p_template->>'category','General'),p_template->>'subject',nullif(p_template->>'html',''),nullif(p_template->>'text_body',''),coalesce(nullif(p_template->>'from_account',''),'noreply@orbitfs.cc'),coalesce((p_template->>'enabled')::boolean,true),now())\n on conflict(template_key) do update set name=excluded.name,category=excluded.category,subject=excluded.subject,html=excluded.html,text_body=excluded.text_body,from_account=excluded.from_account,enabled=excluded.enabled,updated_at=now();\n return true;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_auth_context()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select case when coalesce((public.get_my_staff_access()->>'is_staff')::boolean,false)\n    then jsonb_build_object(\n      'user_id',auth.uid(),\n      'role',coalesce(public.get_my_staff_access()->>'primary_role','user'),\n      'permissions',coalesce(public.get_my_staff_access()->'permissions','{}'::jsonb)\n    ) else null end\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_can_send_address_admin(p_address text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare local_part text;\nbegin\n  if auth.uid() is null or not public.is_staff() then return false; end if;\n  if public.has_permission('all') then return true; end if;\n  local_part:=split_part(lower(p_address),'@',1);\n  if not exists(select 1 from public.mail_accounts where lower(address)=lower(p_address) and active=true) then return false; end if;\n  return public.has_permission('mail.admin.send')\n     and public.has_permission('mail.account.'||local_part||'.send');\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_can_use_address(p_address text, p_send boolean DEFAULT false)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  local_part text;\n  account_kind text;\n  account_assignee uuid;\nbegin\n  if auth.uid() is null or not public.is_staff() then return false; end if;\n  if public.has_permission('all') then return true; end if;\n\n  select kind,assigned_user_id into account_kind,account_assignee\n  from public.mail_accounts\n  where lower(address)=lower(p_address) and active=true;\n  if not found then return false; end if;\n\n  if account_kind='personal' and account_assignee=auth.uid() then return true; end if;\n\n  local_part:=split_part(lower(p_address),'@',1);\n  if p_send then\n    return public.has_permission('mail.view')\n       and public.has_permission('mail.send')\n       and public.has_permission('mail.account.'||local_part||'.send');\n  end if;\n\n  return public.has_permission('mail.view')\n     and (public.has_permission('mail.account.'||local_part||'.view')\n          or public.has_permission('mail.account.'||local_part||'.send'));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_event_cancellation_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare ev text;\nbegin\n  if tg_op='INSERT' then ev:='cancellation.requested';\n  elsif old.status is distinct from new.status then\n    ev:=case new.status when 'approved_scheduled' then 'cancellation.scheduled' when 'denied' then 'cancellation.denied' when 'completed' then 'cancellation.completed' else null end;\n  end if;\n  if ev is not null then\n    perform public.enqueue_mail_event(ev,'cancellation',new.id::text,new.auth_user_id,jsonb_build_object('order_id',new.order_id,'reason',new.reason,'staff_note',new.staff_note,'scheduled_for',new.scheduled_for),ev||':'||new.id::text);\n  end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_event_customer_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  perform public.enqueue_mail_event('customer.created','customer',new.auth_user_id::text,new.auth_user_id,jsonb_build_object('customer_name',coalesce(new.name,'Customer')),'customer.created:'||new.auth_user_id::text);\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_event_invoice_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare stamp text:=to_char(coalesce(new.updated_at,now()),'YYYYMMDDHH24MISSUS');\nbegin\n  if tg_op='INSERT' then\n    perform public.enqueue_mail_event('invoice.created','invoice',new.id::text,new.auth_user_id,jsonb_build_object('invoice_number',new.invoice_number,'invoice_total_cents',new.total_cents,'invoice_due_cents',greatest(0,new.total_cents-coalesce(new.paid_cents,0)),'currency',new.currency,'due_at',new.due_at),'invoice.created:'||new.id::text);\n    return new;\n  end if;\n  if old.status is distinct from new.status then\n    if new.status='paid' then\n      perform public.enqueue_mail_event('invoice.paid','invoice',new.id::text,new.auth_user_id,jsonb_build_object('invoice_number',new.invoice_number,'invoice_total_cents',new.total_cents,'invoice_due_cents',0,'currency',new.currency,'due_at',new.due_at),'invoice.paid:'||new.id::text);\n    elsif new.status='overdue' then\n      perform public.enqueue_mail_event('invoice.overdue','invoice',new.id::text,new.auth_user_id,jsonb_build_object('invoice_number',new.invoice_number,'invoice_total_cents',new.total_cents,'invoice_due_cents',greatest(0,new.total_cents-coalesce(new.paid_cents,0)),'currency',new.currency,'due_at',new.due_at),'invoice.overdue:'||new.id::text||':'||stamp);\n    elsif new.status in ('cancelled','void') then\n      perform public.enqueue_mail_event('invoice.cancelled','invoice',new.id::text,new.auth_user_id,jsonb_build_object('invoice_number',new.invoice_number),'invoice.cancelled:'||new.id::text||':'||stamp);\n    end if;\n  end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_event_order_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare stamp text:=to_char(coalesce(new.updated_at,now()),'YYYYMMDDHH24MISSUS'); new_state text; old_state text; reason text:=coalesce(new.termination_reason,'');\nbegin\n  if tg_op='INSERT' then\n    perform public.enqueue_mail_event('order.created','order',new.id::text,new.auth_user_id,jsonb_build_object('order_number',new.order_number,'order_total_cents',new.total_cents,'currency',new.currency),'order.created:'||new.id::text);\n    return new;\n  end if;\n  if coalesce(old.payment_status,'') !~ '^paid' and coalesce(new.payment_status,'') ~ '^paid' then\n    perform public.enqueue_mail_event('order.paid','order',new.id::text,new.auth_user_id,jsonb_build_object('order_number',new.order_number,'order_total_cents',new.total_cents,'currency',new.currency),'order.paid:'||new.id::text);\n  end if;\n  if old.status is distinct from new.status or old.service_status is distinct from new.service_status then\n    old_state:=case when old.status='terminated' or old.service_status='terminated' then 'terminated' when old.status='suspended' or old.service_status='suspended' then 'suspended' when old.status='active' or old.service_status='active' then 'active' else coalesce(old.service_status,old.status,'') end;\n    new_state:=case when new.status='terminated' or new.service_status='terminated' then 'terminated' when new.status='suspended' or new.service_status='suspended' then 'suspended' when new.status='active' or new.service_status='active' then 'active' else coalesce(new.service_status,new.status,'') end;\n    if old_state is distinct from new_state then\n      if new_state='suspended' then\n        perform public.enqueue_mail_event('service.suspended','order',new.id::text,new.auth_user_id,jsonb_build_object('order_number',new.order_number,'reason',coalesce(nullif(reason,''),'Service suspended')),'service.suspended:'||new.id::text||':'||stamp);\n      elsif new_state='active' then\n        perform public.enqueue_mail_event(case when old_state='suspended' then 'service.restored' else 'service.activated' end,'order',new.id::text,new.auth_user_id,jsonb_build_object('order_number',new.order_number),'service.active:'||new.id::text||':'||stamp);\n      elsif new_state='terminated' and coalesce(new.metadata->>'cancellation_status','') not in ('requested','approved_scheduled','completed') and not (coalesce(new.payment_status,'')='cancelled' and lower(coalesce(reason,'')) like '%payment%') then\n        perform public.enqueue_mail_event('service.terminated','order',new.id::text,new.auth_user_id,jsonb_build_object('order_number',new.order_number,'reason',reason),'service.terminated:'||new.id::text||':'||stamp);\n      end if;\n    end if;\n  end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_event_refund_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  inv public.invoices%rowtype;\n  timing_text text;\n  method_text text;\n  status_text text;\nbegin\n  if tg_op='UPDATE' and old.status is not distinct from new.status then return new; end if;\n  if new.status not in ('pending','processing','completed','succeeded') then return new; end if;\n  select * into inv from public.invoices where id=new.invoice_id;\n  method_text:=case new.method when 'wallet' then 'OrbitFS Wallet' when 'account_credit' then 'OrbitFS Wallet (original Wallet payment)' when 'stripe' then 'Original card / Stripe payment' when 'paypal' then 'Original PayPal payment' else replace(initcap(new.method),'_',' ') end;\n  status_text:=case when new.status in ('completed','succeeded') then 'Completed' else 'Processing' end;\n  timing_text:=case when new.method in ('wallet','account_credit') then 'Wallet refunds are available as OrbitFS Wallet credit immediately.' else 'The refund has been submitted to the original payment provider. It may not appear instantly; processing time depends on the provider and your bank or card issuer.' end;\n  perform public.enqueue_mail_event(\n    'invoice.refund','invoice',new.invoice_id::text,new.auth_user_id,\n    jsonb_build_object(\n      'refund_amount',to_char(new.amount_cents::numeric/100,'FM999999990.00')||' '||coalesce(inv.currency,'AUD'),\n      'refund_method',method_text,'refund_status',status_text,\n      'refund_reference',coalesce(new.external_reference,'OrbitFS-'||upper(substr(replace(new.id::text,'-',''),1,10))),\n      'refund_timing',timing_text\n    ),\n    'invoice.refund:'||new.id::text||':'||new.status\n  );\n  return new;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_event_support_message_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid;\nbegin\n  if coalesce(new.internal_note,false)=false and coalesce(new.author_role,'') not in ('user','system') then\n    select user_id into uid from public.support_tickets where id=new.ticket_id;\n    perform public.enqueue_mail_event('support.ticket.replied','support_ticket',new.ticket_id::text,uid,jsonb_build_object('message_id',new.id,'reply_preview',left(new.body,600)),'support.ticket.replied:'||new.id::text);\n  end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_event_support_ticket_trigger()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare stamp text:=to_char(coalesce(new.updated_at,now()),'YYYYMMDDHH24MISSUS'); ev text;\nbegin\n  if tg_op='INSERT' then ev:='support.ticket.created';\n  elsif old.status is distinct from new.status then\n    if new.status='closed' then ev:='support.ticket.closed'; elsif old.status='closed' and new.status<>'closed' then ev:='support.ticket.reopened'; end if;\n  end if;\n  if ev is not null then perform public.enqueue_mail_event(ev,'support_ticket',new.id::text,new.user_id,jsonb_build_object('ticket_number',new.ticket_number,'ticket_subject',new.subject),ev||':'||new.id::text||':'||case when tg_op='INSERT' then 'created' else stamp end); end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_finalize_delivery(p_log_id uuid, p_provider_id text, p_status text, p_error text, p_sent_at timestamp with time zone, p_subject text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if auth.role()='service_role' then\n    update public.mail_delivery_log set provider_id=p_provider_id,status=p_status,error=p_error,sent_at=p_sent_at,subject=coalesce(nullif(p_subject,''),subject) where id=p_log_id;\n  else\n    if auth.uid() is null or not public.is_staff() then raise exception 'Mail access denied'; end if;\n    update public.mail_delivery_log set provider_id=p_provider_id,status=p_status,error=p_error,sent_at=p_sent_at,subject=coalesce(nullif(p_subject,''),subject) where id=p_log_id and sent_by_user_id=auth.uid();\n  end if;\n  if not found then raise exception 'Mail delivery record not found'; end if;\n  return true;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_get_automation(p_event_key text)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n select case when a.enabled then jsonb_build_object(\n   'event_key',a.event_key,'name',a.name,'category',a.category,'template_key',a.template_key,'enabled',a.enabled,'variables',a.variables\n ) else null end\n from public.mail_automations a where a.event_key=p_event_key\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_get_message(p_id uuid, p_address text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare m public.mail_messages; begin\n  if not public.mail_can_use_address(p_address,false) then raise exception 'Mail access denied'; end if;\n  select * into m from public.mail_messages where id=p_id and lower(mailbox_address)=lower(p_address);\n  if m.id is null then return null; end if;\n  update public.mail_messages set is_read=true where id=m.id;\n  return to_jsonb(m) || jsonb_build_object('is_read',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_get_message_states(p_address text)\n RETURNS SETOF mail_message_state\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if not public.mail_can_use_address(lower(p_address), false) then raise exception 'Mail access denied'; end if;\n  return query select * from public.mail_message_state where mailbox_address=lower(p_address);\nend;$function$\n\nCREATE OR REPLACE FUNCTION public.mail_get_outbox(p_address text)\n RETURNS SETOF mail_delivery_log\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if not public.mail_can_use_address(lower(p_address), false) then raise exception 'Mail access denied'; end if;\n  return query select * from public.mail_delivery_log\n    where lower(sender)=lower(p_address) and status not in ('sent','delivered')\n    order by created_at desc limit 100;\nend;$function$\n\nCREATE OR REPLACE FUNCTION public.mail_get_template(p_template_key text)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select case when auth.role()='service_role' or (\n    auth.uid() is not null and public.is_staff() and (\n      public.has_permission('mail.view') or public.has_permission('orders.view') or public.has_permission('orders.edit') or public.has_permission('invoices.view') or public.has_permission('invoices.edit') or public.has_permission('support.reply') or public.has_permission('customers.edit')\n    )\n  ) then (select to_jsonb(t) from public.mail_templates t where t.template_key=p_template_key and t.enabled=true limit 1) else null end\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_has_any_system_permission()\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n select public.has_permission('all')\n    or public.has_permission('mail.view')\n    or public.has_permission('mail.admin')\n    or public.has_permission('mail.admin.send')\n    or public.has_permission('mail.settings')\n    or public.has_permission('mail.templates')\n    or public.has_permission('mail.queue.view')\n    or public.has_permission('mail.queue.manage')\n    or exists(select 1 from public.mail_accounts a where a.kind='personal' and a.active=true and a.assigned_user_id=auth.uid());\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_list_messages(p_address text, p_folder text DEFAULT 'inbox'::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)\n RETURNS TABLE(id uuid, provider_id text, mailbox_address text, direction text, from_address text, to_addresses jsonb, subject text, message_id text, status text, is_read boolean, event_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if not public.mail_can_use_address(p_address,false) then raise exception 'Mail access denied'; end if;\n  return query\n  select m.id,m.provider_id,m.mailbox_address,m.direction,m.from_address,m.to_addresses,m.subject,m.message_id,m.status,m.is_read,coalesce(m.received_at,m.sent_at,m.created_at)\n  from public.mail_messages m\n  where lower(m.mailbox_address)=lower(p_address)\n    and m.direction=case when p_folder='sent' then 'outbound' else 'inbound' end\n  order by coalesce(m.received_at,m.sent_at,m.created_at) desc\n  limit greatest(1,least(p_limit,200)) offset greatest(p_offset,0);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_log_delivery(p_provider_id text, p_template_key text, p_event_type text, p_related_type text, p_related_id text, p_recipient text, p_sender text, p_subject text, p_status text, p_error text, p_sent_at timestamp with time zone)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if auth.uid() is null or not public.is_staff() or not (\n    public.has_permission('mail.view') or public.has_permission('orders.view') or public.has_permission('orders.edit') or public.has_permission('invoices.view') or public.has_permission('invoices.edit') or public.has_permission('support.reply') or public.has_permission('customers.edit')\n  ) then raise exception 'Mail access denied'; end if;\n  insert into public.mail_delivery_log(provider_id,template_key,event_type,related_type,related_id,recipient,sender,subject,status,error,sent_at)\n  values(p_provider_id,p_template_key,p_event_type,p_related_type,p_related_id,p_recipient,p_sender,p_subject,p_status,p_error,p_sent_at);\n  return true;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_log_delivery(p_provider_id text, p_template_key text, p_event_type text, p_related_type text, p_related_id text, p_recipient text, p_sender text, p_subject text, p_status text, p_error text, p_sent_at timestamp with time zone, p_reference_id text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_uid uuid := auth.uid();\n  v_email text := auth.jwt()->>'email';\n  v_name text;\n  v_ref text := nullif(trim(coalesce(p_reference_id,'')),'');\nbegin\n  if v_uid is null or not public.is_staff() or not (\n    public.has_permission('mail.view') or public.has_permission('orders.view') or public.has_permission('orders.edit') or public.has_permission('invoices.view') or public.has_permission('invoices.edit') or public.has_permission('support.reply') or public.has_permission('customers.edit')\n  ) then raise exception 'Mail access denied'; end if;\n  if v_ref is null then v_ref := public.mail_new_reference_id(); end if;\n  select coalesce(nullif(display_name,''),nullif(first_name,''),v_email) into v_name from public.user_profiles where id=v_uid;\n  insert into public.mail_delivery_log(provider_id,template_key,event_type,related_type,related_id,recipient,sender,subject,status,error,sent_at,reference_id,sent_by_user_id,sent_by_email,sent_by_name)\n  values(p_provider_id,p_template_key,p_event_type,p_related_type,p_related_id,p_recipient,p_sender,p_subject,p_status,p_error,p_sent_at,v_ref,v_uid,v_email,v_name);\n  return true;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_log_support_delivery(p_ticket_id uuid, p_provider_id text, p_template_key text, p_event_type text, p_recipient text, p_sender text, p_subject text, p_status text, p_error text, p_sent_at timestamp with time zone)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_owner uuid;\nbegin\n select user_id into v_owner from public.support_tickets where id=p_ticket_id;\n if v_owner is null then raise exception 'ticket not found'; end if;\n if auth.uid()<>v_owner and not public.has_permission('support.manage') and not public.has_permission('support.reply') and not public.has_permission('support.close') then raise exception 'permission denied'; end if;\n insert into public.mail_delivery_log(provider_id,template_key,event_type,related_type,related_id,recipient,sender,subject,status,error,sent_at)\n values(p_provider_id,p_template_key,p_event_type,'support_ticket',p_ticket_id::text,p_recipient,p_sender,p_subject,p_status,p_error,p_sent_at);\n return true;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_new_reference_id()\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v text;\nbegin\n  loop\n    v := 'OFM-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,8));\n    exit when not exists(select 1 from public.mail_delivery_log where reference_id=v);\n  end loop;\n  return v;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_outbox_finalize(p_id uuid, p_token uuid, p_log_id uuid, p_provider_id text, p_status text, p_error text, p_subject text DEFAULT NULL::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if not exists(select 1 from public.mail_event_outbox where id=p_id and dispatch_token=p_token) then raise exception 'invalid mail dispatch'; end if;\n  update public.mail_delivery_log\n  set provider_id=p_provider_id,status=p_status,error=p_error,\n      subject=coalesce(nullif(p_subject,''),subject),\n      sent_at=case when p_status='sent' then now() else null end\n  where id=p_log_id;\n  if not found then raise exception 'mail delivery record not found'; end if;\n  update public.mail_event_outbox\n  set state=case when p_status='sent' then 'sent' else 'failed' end,\n      processed_at=case when p_status='sent' then now() else null end,\n      last_error=p_error,\n      next_attempt_at=case when p_status='sent' then next_attempt_at else now()+interval '5 minutes' end\n  where id=p_id;\n  return true;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_outbox_prepare(p_id uuid, p_token uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  e public.mail_event_outbox%rowtype;\n  a public.mail_automations%rowtype;\n  t public.mail_templates%rowtype;\n  c public.customers%rowtype;\n  p public.user_profiles%rowtype;\n  o public.orders%rowtype;\n  i public.invoices%rowtype;\n  cr public.order_cancellation_requests%rowtype;\n  st public.support_tickets%rowtype;\n  v_vars jsonb;\n  v_recipient text;\n  v_name text;\n  v_sender text;\n  v_log uuid:=gen_random_uuid();\n  v_ref text:='OFM-'||upper(substr(replace(v_log::text,'-',''),1,8));\n  v_site text;\nbegin\n  select rtrim(coalesce(value #>> '{}','https://orbitfs.cc'),'/')\n    into v_site\n    from public.app_settings\n    where key='site.public_url';\n  v_site:=coalesce(nullif(v_site,''),'https://orbitfs.cc');\n\n  select * into e from public.mail_event_outbox where id=p_id and dispatch_token=p_token for update;\n  if not found then raise exception 'invalid mail dispatch'; end if;\n  if e.state='sent' then return jsonb_build_object('skip',true,'reason','already_processed'); end if;\n\n  if exists(\n    select 1 from public.mail_delivery_log l\n    where l.event_type=e.event_key\n      and l.related_type=e.related_type\n      and l.related_id=e.related_id\n      and l.status='sent'\n      and l.created_at>=e.created_at-interval '2 minutes'\n  ) then\n    update public.mail_event_outbox set state='sent',processed_at=now(),last_error=null where id=e.id;\n    return jsonb_build_object('skip',true,'reason','already_delivered');\n  end if;\n\n  select * into a from public.mail_automations where event_key=e.event_key and enabled=true;\n  if not found or a.template_key is null then raise exception 'mail automation missing or disabled: %',e.event_key; end if;\n  select * into t from public.mail_templates where template_key=a.template_key and enabled=true;\n  if not found then raise exception 'mail template missing or disabled: %',a.template_key; end if;\n\n  v_sender:=t.from_account;\n  if e.auth_user_id is not null then\n    select * into c from public.customers where auth_user_id=e.auth_user_id limit 1;\n    select * into p from public.user_profiles where id=e.auth_user_id;\n  end if;\n  v_recipient:=c.email;\n  v_name:=coalesce(nullif(c.name,''),nullif(p.display_name,''),nullif(concat_ws(' ',p.first_name,p.last_name),''),'Customer');\n  v_vars:=coalesce(e.payload,'{}'::jsonb)||jsonb_build_object('customer_name',v_name,'site_url',v_site);\n\n  if e.related_type='order' then\n    select * into o from public.orders where id=e.related_id::uuid;\n    v_vars:=v_vars||jsonb_build_object(\n      'order_number',coalesce(o.order_number,''),\n      'order_total',to_char(coalesce(o.total_cents,0)::numeric/100,'FM$999999990.00'),\n      'reason',coalesce(v_vars->>'reason',o.termination_reason,'')\n    );\n  elsif e.related_type='invoice' then\n    select * into i from public.invoices where id=e.related_id::uuid;\n    v_vars:=v_vars||jsonb_build_object(\n      'invoice_number',coalesce(i.invoice_number,''),\n      'invoice_total',to_char(coalesce(i.total_cents,0)::numeric/100,'FM$999999990.00'),\n      'invoice_due',to_char(greatest(0,coalesce(i.total_cents,0)-coalesce(i.paid_cents,0))::numeric/100,'FM$999999990.00'),\n      'due_date',coalesce(to_char(i.due_at at time zone 'Australia/Sydney','DD/MM/YYYY'),'No due date'),\n      'invoice_url',v_site||'/portal/invoices/'||i.id::text\n    );\n  elsif e.related_type='cancellation' then\n    select * into cr from public.order_cancellation_requests where id=e.related_id::uuid;\n    select * into o from public.orders where id=cr.order_id;\n    v_vars:=v_vars||jsonb_build_object(\n      'order_number',coalesce(o.order_number,''),\n      'reason',coalesce(cr.reason,''),\n      'staff_note',coalesce(nullif(cr.staff_note,''),'No additional note was provided.'),\n      'scheduled_for',coalesce(to_char(cr.scheduled_for at time zone 'Australia/Sydney','DD/MM/YYYY HH24:MI'),'')\n    );\n  elsif e.related_type='support_ticket' then\n    select * into st from public.support_tickets where id=e.related_id::uuid;\n    select coalesce(d.email,t.from_account) into v_sender from public.support_departments d where d.id=st.department_id;\n    v_sender:=coalesce(v_sender,t.from_account);\n    v_vars:=v_vars||jsonb_build_object(\n      'ticket_number',coalesce(st.ticket_number::text,''),\n      'ticket_subject',coalesce(st.subject,''),\n      'reply_preview',coalesce(v_vars->>'reply_preview',''),\n      'ticket_url',v_site||'/portal/support/'||st.id::text\n    );\n  end if;\n\n  if coalesce(v_recipient,'')='' then raise exception 'customer email unavailable'; end if;\n\n  insert into public.mail_delivery_log(\n    id,provider_id,template_key,event_type,related_type,related_id,recipient,sender,subject,status,error,sent_at,reference_id,sent_by_user_id,sent_by_email,sent_by_name\n  ) values(\n    v_log,null,t.template_key,e.event_key,e.related_type,e.related_id,v_recipient,v_sender,t.subject,'preparing',null,null,v_ref,null,'system@orbitfs.cc','System Automation'\n  );\n\n  update public.mail_event_outbox\n    set state='processing',last_error=null,next_attempt_at=now()+interval '5 minutes'\n    where id=e.id;\n\n  return jsonb_build_object(\n    'skip',false,'outbox_id',e.id,'log_id',v_log,'reference_id',v_ref,\n    'event_key',e.event_key,'related_type',e.related_type,'related_id',e.related_id,\n    'recipient',v_recipient,'template_key',t.template_key,'from_account',v_sender,\n    'subject',t.subject,'text_body',t.text_body,'html',t.html,'vars',v_vars\n  );\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_prepare_delivery(p_template_key text, p_event_type text, p_related_type text, p_related_id text, p_recipient text, p_sender text, p_subject text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  v_uid uuid:=auth.uid();\n  v_role text:=auth.role();\n  v_email text:=auth.jwt()->>'email';\n  v_name text;\n  v_id uuid:=gen_random_uuid();\n  v_ref text:='OFM-'||upper(substr(replace(v_id::text,'-',''),1,8));\nbegin\n  if v_role<>'service_role' and (v_uid is null or not public.is_staff() or not (\n    public.has_permission('mail.view') or public.has_permission('orders.view') or public.has_permission('orders.edit') or public.has_permission('invoices.view') or public.has_permission('invoices.edit') or public.has_permission('support.reply') or public.has_permission('customers.edit')\n  )) then raise exception 'Mail access denied'; end if;\n  if v_role='service_role' then\n    v_uid:=null;v_email:='system@orbitfs.cc';v_name:='System Automation';\n  else\n    select coalesce(nullif(display_name,''),nullif(first_name,''),v_email) into v_name from public.user_profiles where id=v_uid;\n  end if;\n  insert into public.mail_delivery_log(id,provider_id,template_key,event_type,related_type,related_id,recipient,sender,subject,status,error,sent_at,reference_id,sent_by_user_id,sent_by_email,sent_by_name)\n  values(v_id,null,p_template_key,p_event_type,p_related_type,p_related_id,p_recipient,p_sender,p_subject,'preparing',null,null,v_ref,v_uid,v_email,v_name);\n  return jsonb_build_object('id',v_id,'reference_id',v_ref,'sent_by_user_id',v_uid,'sent_by_email',v_email,'sent_by_name',v_name);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_purge_expired_trash(p_address text)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare n integer;\nbegin\n if not public.mail_can_use_address(lower(p_address), false) then raise exception 'Mail access denied'; end if;\n update public.mail_message_state set folder='deleted',updated_at=now() where mailbox_address=lower(p_address) and folder='trash' and purge_after is not null and purge_after<=now();\n get diagnostics n=row_count; return n;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_record_sender_meta(p_address text, p_provider_id text, p_email text, p_ip text DEFAULT NULL::text)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare dom text; chk jsonb; ipval inet;\nbegin\n if not public.mail_can_use_address(lower(p_address), false) then raise exception 'Mail access denied'; end if;\n dom:=split_part(lower(coalesce(p_email,'')),'@',2);\n begin ipval:=nullif(p_ip,'')::inet; exception when others then ipval:=null; end;\n chk:=public.mail_spam_check(lower(p_address),lower(coalesce(p_email,'')),case when ipval is null then null else host(ipval) end);\n insert into public.mail_message_state(provider_id,mailbox_address,direction,folder,sender_ip,sender_domain,spam_score,spam_reason)\n values(p_provider_id,lower(p_address),'inbound',case when chk->>'decision'='blocked' then 'spam' else 'inbox' end,ipval,dom,coalesce((chk->>'score')::int,0),case when jsonb_array_length(coalesce(chk->'reasons','[]'::jsonb))>0 then chk->'reasons'->>0 else null end)\n on conflict(provider_id) do update set sender_ip=coalesce(excluded.sender_ip,mail_message_state.sender_ip),sender_domain=excluded.sender_domain,spam_score=greatest(mail_message_state.spam_score,excluded.spam_score),spam_reason=coalesce(excluded.spam_reason,mail_message_state.spam_reason),folder=case when chk->>'decision'='blocked' then 'spam' else mail_message_state.folder end,updated_at=now();\n if chk->>'decision'='blocked' then insert into public.mail_spam_events(provider_id,mailbox_address,sender_email,sender_domain,sender_ip,decision,score,reasons) values(p_provider_id,lower(p_address),lower(p_email),dom,ipval,'blocked',coalesce((chk->>'score')::int,100),coalesce(chk->'reasons','[]'::jsonb)); end if;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_runtime_config()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select jsonb_build_object(\n    'outbound', coalesce((select value from public.mail_settings where key='outbound'), '{}'::jsonb),\n    'inbound', coalesce((select value from public.mail_settings where key='inbound'), '{}'::jsonb),\n    'provider', coalesce((select value from public.mail_settings where key='provider'), '{}'::jsonb)\n  );\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_sender_identity(p_address text)\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select jsonb_build_object(\n    'address', lower(coalesce(a.address,p_address)),\n    'display_name', coalesce(nullif(a.display_name,''), nullif((select value->>'sender_name' from public.mail_settings where key='outbound'),''), 'OrbitFS')\n  )\n  from (select 1) x\n  left join public.mail_accounts a on lower(a.address)=lower(p_address) and a.active=true\n  limit 1;\n$function$\n\nCREATE OR REPLACE FUNCTION public.mail_set_message_state(p_address text, p_provider_id text, p_direction text, p_action text, p_folder text DEFAULT NULL::text)\n RETURNS mail_message_state\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v public.mail_message_state; base_folder text;\nbegin\n if not public.mail_can_use_address(lower(p_address), false) then raise exception 'Mail access denied'; end if;\n if p_direction not in ('inbound','outbound') then raise exception 'Invalid direction'; end if;\n base_folder:=case when p_direction='outbound' then 'sent' else 'inbox' end;\n insert into public.mail_message_state(provider_id,mailbox_address,direction,folder) values(p_provider_id,lower(p_address),p_direction,base_folder) on conflict(provider_id) do nothing;\n if p_action='read' then update public.mail_message_state set is_read=true,updated_at=now() where provider_id=p_provider_id and mailbox_address=lower(p_address);\n elsif p_action='unread' then update public.mail_message_state set is_read=false,updated_at=now() where provider_id=p_provider_id and mailbox_address=lower(p_address);\n elsif p_action='trash' then update public.mail_message_state set previous_folder=case when folder<>'trash' then folder else previous_folder end,folder='trash',trashed_at=coalesce(trashed_at,now()),purge_after=coalesce(purge_after,now()+interval '20 days'),updated_at=now() where provider_id=p_provider_id and mailbox_address=lower(p_address);\n elsif p_action='restore' then update public.mail_message_state set folder=coalesce(previous_folder,base_folder),previous_folder=null,trashed_at=null,purge_after=null,updated_at=now() where provider_id=p_provider_id and mailbox_address=lower(p_address);\n elsif p_action='spam' then update public.mail_message_state set previous_folder=case when folder<>'spam' then folder else previous_folder end,folder='spam',spam_score=greatest(spam_score,100),spam_reason='Marked as spam',updated_at=now() where provider_id=p_provider_id and mailbox_address=lower(p_address);\n   insert into public.mail_spam_events(provider_id,mailbox_address,decision,score,reasons) values(p_provider_id,lower(p_address),'manual_spam',100,'["Marked as spam by user"]'::jsonb);\n elsif p_action='not_spam' then update public.mail_message_state set folder='inbox',previous_folder=null,spam_score=0,spam_reason=null,updated_at=now() where provider_id=p_provider_id and mailbox_address=lower(p_address);\n   insert into public.mail_spam_events(provider_id,mailbox_address,decision,score,reasons) values(p_provider_id,lower(p_address),'manual_not_spam',0,'["Marked as not spam by user"]'::jsonb);\n elsif p_action='move' then\n   if p_folder='trash' then raise exception 'Use Delete to move mail to Trash'; end if;\n   if p_folder not in ('inbox','outbox','sent','spam') then raise exception 'Invalid folder'; end if;\n   update public.mail_message_state set previous_folder=folder,folder=p_folder,updated_at=now() where provider_id=p_provider_id and mailbox_address=lower(p_address);\n elsif p_action='delete_forever' then\n   update public.mail_message_state set previous_folder=folder,folder='deleted',updated_at=now() where provider_id=p_provider_id and mailbox_address=lower(p_address) and folder='trash';\n else raise exception 'Unknown action'; end if;\n select * into v from public.mail_message_state where provider_id=p_provider_id and mailbox_address=lower(p_address); return v;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_spam_admin(action text, payload jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare ctx jsonb; perms jsonb; rid uuid;\nbegin\n ctx:=public.mail_auth_context(); perms:=coalesce(ctx->'permissions','{}'::jsonb);\n if not (coalesce((perms->>'all')::boolean,false) or coalesce((perms->>'mail.admin')::boolean,false) or coalesce((perms->>'mail.settings')::boolean,false)) then raise exception 'Mail spam administration denied'; end if;\n if action='list' then return jsonb_build_object('rules',(select coalesce(jsonb_agg(to_jsonb(r) order by r.created_at desc),'[]'::jsonb) from public.mail_spam_rules r),'events',(select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at desc),'[]'::jsonb) from (select * from public.mail_spam_events order by created_at desc limit 200) e));\n elsif action='upsert' then insert into public.mail_spam_rules(scope,mailbox_address,rule_type,value,action,reason,active,created_by) values(coalesce(payload->>'scope','global'),nullif(lower(payload->>'mailbox_address'),''),payload->>'rule_type',lower(payload->>'value'),coalesce(payload->>'action','block'),payload->>'reason',coalesce((payload->>'active')::boolean,true),auth.uid()) on conflict(scope,mailbox_address,rule_type,value) do update set action=excluded.action,reason=excluded.reason,active=excluded.active,updated_at=now() returning id into rid; return jsonb_build_object('ok',true,'id',rid);\n elsif action='delete' then delete from public.mail_spam_rules where id=(payload->>'id')::uuid; return jsonb_build_object('ok',true);\n end if;\n raise exception 'Unknown action';\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_spam_check(p_mailbox text, p_email text, p_ip text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare dom text; r record; score int:=0; reasons jsonb:='[]'::jsonb; decision text:='allowed';\nbegin\n dom:=split_part(lower(coalesce(p_email,'')),'@',2);\n for r in select * from public.mail_spam_rules where active and (scope='global' or lower(mailbox_address)=lower(p_mailbox)) and ((rule_type='email' and lower(value)=lower(p_email)) or (rule_type='domain' and lower(value)=dom) or (rule_type='ip' and p_ip is not null and value=p_ip)) order by case action when 'allow' then 0 else 1 end loop\n   if r.action='allow' then return jsonb_build_object('decision','allowed','score',0,'reasons',jsonb_build_array('allowlist')); end if;\n   score:=100; decision:='blocked'; reasons:=reasons||jsonb_build_array(coalesce(r.reason,r.rule_type||' blocked'));\n end loop;\n return jsonb_build_object('decision',decision,'score',score,'reasons',reasons);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_store_sent_message(p_provider_id text, p_address text, p_to jsonb, p_subject text, p_text text, p_html text, p_message_id text, p_in_reply_to text, p_status text DEFAULT 'sent'::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare mid uuid; begin\n  if not public.mail_can_use_address(p_address,true) then raise exception 'Mail send denied'; end if;\n  insert into public.mail_messages(provider_id,mailbox_address,direction,from_address,to_addresses,subject,text_body,html_body,message_id,in_reply_to,status,is_read,sent_at)\n  values(p_provider_id,lower(p_address),'outbound',lower(p_address),coalesce(p_to,'[]'::jsonb),coalesce(p_subject,''),p_text,p_html,p_message_id,p_in_reply_to,p_status,true,now())\n  on conflict(provider_id) do update set status=excluded.status\n  returning id into mid;\n  return mid;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.mail_visible_accounts()\n RETURNS TABLE(id uuid, address text, display_name text, kind text, active boolean, can_send boolean, can_manage boolean)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n select a.id,a.address,a.display_name,a.kind,a.active,\n        public.mail_can_use_address(a.address,true) as can_send,\n        (public.has_permission('all') or public.has_permission('mail.settings')) as can_manage\n from public.mail_accounts a\n where a.active=true and public.mail_can_use_address(a.address,false)\n order by a.address\n$function$\n\nCREATE OR REPLACE FUNCTION public.notification_admin_recipient_options(p_query text DEFAULT ''::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare rows_json jsonb;\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  if not public.has_permission('notifications.send') then raise exception 'permission denied'; end if;\n\n  select coalesce(jsonb_agg(to_jsonb(x) order by x.kind desc,x.label,x.email),'[]'::jsonb)\n    into rows_json\n  from (\n    select au.id,\n      coalesce(nullif(btrim(up.display_name),''),nullif(btrim(concat_ws(' ',up.first_name,up.last_name)),''),au.email,au.id::text) as label,\n      au.email,\n      up.customer_number,\n      case when sm.user_id is not null and sm.status='active' then 'staff' else 'customer' end as kind,\n      case when sm.user_id is not null and sm.status='active' then sm.status else coalesce(up.status,'active') end as status\n    from auth.users au\n    left join public.user_profiles up on up.id=au.id\n    left join public.staff_members sm on sm.user_id=au.id\n    where (up.id is not null or (sm.user_id is not null and sm.status='active'))\n      and (\n        nullif(btrim(coalesce(p_query,'')),'') is null\n        or lower(coalesce(up.display_name,'')) like '%'||lower(btrim(p_query))||'%'\n        or lower(coalesce(up.first_name,'')) like '%'||lower(btrim(p_query))||'%'\n        or lower(coalesce(up.last_name,'')) like '%'||lower(btrim(p_query))||'%'\n        or lower(coalesce(au.email,'')) like '%'||lower(btrim(p_query))||'%'\n        or lower(coalesce(up.customer_number,'')) like '%'||lower(btrim(p_query))||'%'\n      )\n    order by kind desc,label,email\n    limit 120\n  ) x;\n\n  return jsonb_build_object('recipients',rows_json);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notification_admin_send(p_audience text, p_recipient_user_ids uuid[] DEFAULT NULL::uuid[], p_kind text DEFAULT 'notification'::text, p_title text DEFAULT ''::text, p_message text DEFAULT ''::text, p_severity text DEFAULT 'info'::text, p_action_url text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  actor uuid:=auth.uid();\n  dispatch_id uuid:=gen_random_uuid();\n  sent integer:=0;\n  r record;\n  clean_title text:=btrim(coalesce(p_title,''));\n  clean_message text:=btrim(coalesce(p_message,''));\n  clean_action text:=nullif(btrim(coalesce(p_action_url,'')),'');\n  actor_email text;\nbegin\n  if actor is null then raise exception 'authentication required'; end if;\n  if not public.has_permission('notifications.send') then raise exception 'permission denied'; end if;\n  if p_audience not in ('selected','customers','staff','everyone') then raise exception 'invalid audience'; end if;\n  if p_kind not in ('notification','message','alert','announcement','maintenance') then raise exception 'invalid notification type'; end if;\n  if p_severity not in ('info','success','warning','error') then raise exception 'invalid notification severity'; end if;\n  if clean_title='' then raise exception 'title is required'; end if;\n  if length(clean_title)>160 then raise exception 'title is too long'; end if;\n  if length(clean_message)>4000 then raise exception 'message is too long'; end if;\n  if clean_action is not null and (left(clean_action,1)<>'/' or left(clean_action,2)='//') then\n    raise exception 'action path must be a local OrbitFS path';\n  end if;\n  if p_audience='selected' and coalesce(array_length(p_recipient_user_ids,1),0)=0 then\n    raise exception 'select at least one recipient';\n  end if;\n\n  for r in\n    select au.id as user_id,\n      case when exists(\n        select 1 from public.staff_members sm where sm.user_id=au.id and sm.status='active'\n      ) then 'admin' else 'portal' end as surface\n    from auth.users au\n    where\n      (p_audience='selected' and au.id=any(coalesce(p_recipient_user_ids,'{}'::uuid[])))\n      or (p_audience='staff' and exists(select 1 from public.staff_members sm where sm.user_id=au.id and sm.status='active'))\n      or (p_audience='customers' and exists(select 1 from public.user_profiles up where up.id=au.id) and not exists(select 1 from public.staff_members sm where sm.user_id=au.id and sm.status='active'))\n      or (p_audience='everyone' and (exists(select 1 from public.user_profiles up where up.id=au.id) or exists(select 1 from public.staff_members sm where sm.user_id=au.id and sm.status='active')))\n  loop\n    perform public.notification_emit(\n      r.user_id,\n      r.surface,\n      'admin_message',\n      'admin.manual.'||p_kind,\n      clean_title,\n      clean_message,\n      p_severity,\n      actor,\n      'admin_dispatch',\n      dispatch_id::text,\n      clean_action,\n      jsonb_build_object('manual',true,'kind',p_kind,'dispatch_id',dispatch_id,'audience',p_audience),\n      'admin-dispatch-'||dispatch_id::text||'-'||r.user_id::text\n    );\n    sent:=sent+1;\n  end loop;\n\n  select email into actor_email from auth.users where id=actor;\n  insert into public.admin_audit_log(actor_id,actor_email,action,target_type,target_id,detail)\n  values(\n    actor,actor_email,'notification.send','notification_dispatch',dispatch_id::text,\n    jsonb_build_object(\n      'audience',p_audience,\n      'kind',p_kind,\n      'severity',p_severity,\n      'title',clean_title,\n      'action_url',clean_action,\n      'sent',sent,\n      'selected_count',coalesce(array_length(p_recipient_user_ids,1),0)\n    )\n  );\n\n  return jsonb_build_object('ok',true,'dispatch_id',dispatch_id,'sent',sent);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notification_emit(p_recipient_user_id uuid, p_surface text, p_category text, p_event_type text, p_title text, p_message text DEFAULT ''::text, p_severity text DEFAULT 'info'::text, p_actor_user_id uuid DEFAULT NULL::uuid, p_source_type text DEFAULT NULL::text, p_source_id text DEFAULT NULL::text, p_action_url text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_dedupe_key text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare nid uuid;\nbegin\n  if p_recipient_user_id is null or not exists(select 1 from auth.users where id=p_recipient_user_id) then return null; end if;\n  if p_surface not in ('admin','portal') then raise exception 'invalid notification surface'; end if;\n  if p_severity not in ('info','success','warning','error') then raise exception 'invalid notification severity'; end if;\n  if nullif(btrim(coalesce(p_title,'')),'') is null then raise exception 'notification title is required'; end if;\n\n  insert into public.notifications(\n    recipient_user_id,surface,category,event_type,title,message,severity,actor_user_id,\n    source_type,source_id,action_url,metadata,dedupe_key\n  ) values(\n    p_recipient_user_id,p_surface,coalesce(nullif(btrim(p_category),''),'general'),p_event_type,\n    btrim(p_title),coalesce(p_message,''),p_severity,p_actor_user_id,\n    p_source_type,p_source_id,p_action_url,coalesce(p_metadata,'{}'::jsonb),p_dedupe_key\n  )\n  on conflict (recipient_user_id,surface,dedupe_key) where dedupe_key is not null\n  do update set\n    category=excluded.category,\n    event_type=excluded.event_type,\n    title=excluded.title,\n    message=excluded.message,\n    severity=excluded.severity,\n    actor_user_id=excluded.actor_user_id,\n    source_type=excluded.source_type,\n    source_id=excluded.source_id,\n    action_url=excluded.action_url,\n    metadata=excluded.metadata,\n    read_at=null,\n    archived_at=null,\n    created_at=now()\n  returning id into nid;\n  return nid;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notification_feed(p_surface text, p_limit integer DEFAULT 40)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); rows_json jsonb; unread_count integer; safe_limit integer;\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  if p_surface not in ('admin','portal') then raise exception 'invalid notification surface'; end if;\n  safe_limit:=greatest(1,least(coalesce(p_limit,40),100));\n\n  select count(*)::integer into unread_count\n  from public.notifications\n  where recipient_user_id=uid and surface=p_surface and read_at is null and archived_at is null;\n\n  select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) into rows_json\n  from (\n    select id,category,event_type,title,message,severity,actor_user_id,source_type,source_id,\n      action_url,metadata,read_at,created_at\n    from public.notifications\n    where recipient_user_id=uid and surface=p_surface and archived_at is null\n    order by created_at desc\n    limit safe_limit\n  ) x;\n\n  return jsonb_build_object('notifications',rows_json,'unread_count',unread_count);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notification_mark_all_read(p_surface text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare changed integer;\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  if p_surface not in ('admin','portal') then raise exception 'invalid notification surface'; end if;\n  update public.notifications set read_at=coalesce(read_at,now())\n  where recipient_user_id=auth.uid() and surface=p_surface and read_at is null and archived_at is null;\n  get diagnostics changed=row_count;\n  return jsonb_build_object('ok',true,'changed',changed);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notification_mark_read(p_notification_id uuid, p_read boolean DEFAULT true)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  update public.notifications\n  set read_at=case when coalesce(p_read,true) then coalesce(read_at,now()) else null end\n  where id=p_notification_id and recipient_user_id=auth.uid();\n  if not found then raise exception 'notification not found'; end if;\n  return jsonb_build_object('ok',true,'read',coalesce(p_read,true));\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notification_notify_support_department(p_department_id uuid, p_actor_user_id uuid, p_event_type text, p_title text, p_message text, p_severity text, p_ticket_id uuid, p_metadata jsonb DEFAULT '{}'::jsonb, p_exact_rank integer DEFAULT NULL::integer, p_exclude_user_id uuid DEFAULT NULL::uuid)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare r record; sent integer:=0; member_count integer:=0;\nbegin\n  for r in\n    select distinct sm.user_id\n    from public.staff_members sm\n    where sm.status='active'\n      and sm.user_id is distinct from p_actor_user_id\n      and sm.user_id is distinct from p_exclude_user_id\n      and public.support_staff_rank(sm.user_id)>0\n      and (\n        (p_exact_rank is not null and public.support_staff_rank(sm.user_id)=p_exact_rank and public.support_user_has_department(sm.user_id,p_department_id))\n        or\n        (p_exact_rank is null and exists(select 1 from public.support_department_staff ds where ds.department_id=p_department_id and ds.user_id=sm.user_id))\n      )\n  loop\n    perform public.notification_emit(\n      r.user_id,'admin','support',p_event_type,p_title,p_message,p_severity,p_actor_user_id,\n      'support_ticket',p_ticket_id::text,'/admin/support/'||p_ticket_id::text,\n      coalesce(p_metadata,'{}'::jsonb),null\n    );\n    sent:=sent+1;\n  end loop;\n\n  member_count:=sent;\n  if member_count=0 and p_exact_rank is null then\n    for r in\n      select sm.user_id from public.staff_members sm\n      where sm.status='active'\n        and public.support_staff_rank(sm.user_id)>=3\n        and sm.user_id is distinct from p_actor_user_id\n        and sm.user_id is distinct from p_exclude_user_id\n    loop\n      perform public.notification_emit(\n        r.user_id,'admin','support',p_event_type,p_title,p_message,p_severity,p_actor_user_id,\n        'support_ticket',p_ticket_id::text,'/admin/support/'||p_ticket_id::text,\n        coalesce(p_metadata,'{}'::jsonb),null\n      );\n      sent:=sent+1;\n    end loop;\n  end if;\n  return sent;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notify_support_message_created()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare t public.support_tickets%rowtype; actor uuid:=new.author_user_id; human_count integer; preview text;\nbegin\n  select * into t from public.support_tickets where id=new.ticket_id;\n  if not found then return new; end if;\n\n  select count(*)::integer into human_count\n  from public.support_ticket_messages\n  where ticket_id=new.ticket_id and author_role<>'system';\n  if human_count<=1 then return new; end if;\n\n  preview:=left(regexp_replace(coalesce(new.body,''),'\\s+',' ','g'),180);\n\n  if new.internal_note then\n    if t.assigned_to is not null and t.assigned_to is distinct from actor then\n      perform public.notification_emit(\n        t.assigned_to,'admin','support','support.ticket.internal_note',\n        'Internal note on ticket #'||t.ticket_number::text,\n        preview,'info',actor,'support_ticket',t.id::text,'/admin/support/'||t.id::text,\n        jsonb_build_object('ticket_number',t.ticket_number,'message_id',new.id),null\n      );\n    end if;\n    return new;\n  end if;\n\n  if new.author_role='user' then\n    if t.assigned_to is not null and t.assigned_to is distinct from actor then\n      perform public.notification_emit(\n        t.assigned_to,'admin','support','support.ticket.customer_reply',\n        'Customer replied to ticket #'||t.ticket_number::text,\n        preview,'info',actor,'support_ticket',t.id::text,'/admin/support/'||t.id::text,\n        jsonb_build_object('ticket_number',t.ticket_number,'message_id',new.id),null\n      );\n    else\n      perform public.notification_notify_support_department(\n        t.department_id,actor,'support.ticket.customer_reply',\n        'Customer replied to ticket #'||t.ticket_number::text,\n        preview,'info',t.id,\n        jsonb_build_object('ticket_number',t.ticket_number,'message_id',new.id),\n        case when t.escalation_level>0 then t.escalation_level+1 else null end,\n        null\n      );\n    end if;\n  elsif new.author_role<>'system' and t.user_id is distinct from actor then\n    perform public.notification_emit(\n      t.user_id,'portal','support','support.ticket.staff_reply',\n      'New reply on ticket #'||t.ticket_number::text,\n      preview,'info',actor,'support_ticket',t.id::text,'/portal/support/'||t.id::text,\n      jsonb_build_object('ticket_number',t.ticket_number,'message_id',new.id),null\n    );\n  end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notify_support_ticket_created()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare actor uuid:=auth.uid(); dept_name text;\nbegin\n  select name into dept_name from public.support_departments where id=new.department_id;\n\n  perform public.notification_notify_support_department(\n    new.department_id,actor,'support.ticket.created',\n    'New support ticket #'||new.ticket_number::text,\n    new.subject||' · '||coalesce(dept_name,'Support'),\n    case when new.priority in ('high','urgent') then 'warning' else 'info' end,\n    new.id,\n    jsonb_build_object('ticket_number',new.ticket_number,'priority',new.priority,'department_id',new.department_id),\n    null,null\n  );\n\n  if new.source='admin' and new.user_id is distinct from actor then\n    perform public.notification_emit(\n      new.user_id,'portal','support','support.ticket.opened',\n      'Support ticket #'||new.ticket_number::text||' opened',\n      new.subject,'info',actor,'support_ticket',new.id::text,\n      '/portal/support/'||new.id::text,\n      jsonb_build_object('ticket_number',new.ticket_number,'priority',new.priority),\n      'support-opened-'||new.id::text\n    );\n  end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.notify_support_ticket_updated()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare actor uuid:=auth.uid(); dept_name text; old_dept_name text; target_rank integer;\nbegin\n  if old.assigned_to is distinct from new.assigned_to then\n    if new.assigned_to is not null and new.assigned_to is distinct from actor then\n      perform public.notification_emit(\n        new.assigned_to,'admin','support','support.ticket.assigned',\n        'Ticket #'||new.ticket_number::text||' assigned to you',\n        new.subject,'info',actor,'support_ticket',new.id::text,\n        '/admin/support/'||new.id::text,\n        jsonb_build_object('ticket_number',new.ticket_number,'priority',new.priority,'department_id',new.department_id),\n        null\n      );\n    end if;\n\n    if old.assigned_to is not null and old.assigned_to is distinct from new.assigned_to and old.assigned_to is distinct from actor then\n      perform public.notification_emit(\n        old.assigned_to,'admin','support','support.ticket.assignment_removed',\n        'Ticket #'||new.ticket_number::text||' is no longer assigned to you',\n        new.subject,'info',actor,'support_ticket',new.id::text,\n        '/admin/support/'||new.id::text,\n        jsonb_build_object('ticket_number',new.ticket_number,'new_assigned_to',new.assigned_to),\n        null\n      );\n    end if;\n  end if;\n\n  if old.escalation_level is distinct from new.escalation_level then\n    if new.escalation_level>0 and new.assigned_to is null then\n      target_rank:=new.escalation_level+1;\n      perform public.notification_notify_support_department(\n        new.department_id,actor,'support.ticket.escalated',\n        'Escalated ticket #'||new.ticket_number::text||' needs to be claimed',\n        new.subject,\n        'warning',new.id,\n        jsonb_build_object('ticket_number',new.ticket_number,'escalation_level',new.escalation_level,'claim_required',new.claim_required),\n        target_rank,new.assigned_to\n      );\n    end if;\n  elsif old.department_id is distinct from new.department_id then\n    select name into dept_name from public.support_departments where id=new.department_id;\n    select name into old_dept_name from public.support_departments where id=old.department_id;\n    perform public.notification_notify_support_department(\n      new.department_id,actor,'support.ticket.department_transferred',\n      'Ticket #'||new.ticket_number::text||' transferred to '||coalesce(dept_name,'your department'),\n      case when new.claim_required then 'This ticket must be claimed before work continues.' else new.subject end,\n      'warning',new.id,\n      jsonb_build_object('ticket_number',new.ticket_number,'from_department',old_dept_name,'to_department',dept_name,'claim_required',new.claim_required),\n      null,new.assigned_to\n    );\n  end if;\n\n  if old.status is distinct from new.status then\n    if actor is distinct from new.user_id and new.status not in ('customer_reply','staff_reply') then\n      perform public.notification_emit(\n        new.user_id,'portal','support','support.ticket.status_changed',\n        'Ticket #'||new.ticket_number::text||' status changed',\n        'Status: '||initcap(replace(new.status,'_',' ')),'info',actor,\n        'support_ticket',new.id::text,'/portal/support/'||new.id::text,\n        jsonb_build_object('ticket_number',new.ticket_number,'from_status',old.status,'status',new.status),\n        null\n      );\n    elsif actor=new.user_id and new.status='closed' and old.status<>'closed' and new.assigned_to is not null and new.assigned_to is distinct from actor then\n      perform public.notification_emit(\n        new.assigned_to,'admin','support','support.ticket.customer_closed',\n        'Customer closed ticket #'||new.ticket_number::text,\n        new.subject,'info',actor,'support_ticket',new.id::text,\n        '/admin/support/'||new.id::text,jsonb_build_object('ticket_number',new.ticket_number),null\n      );\n    end if;\n  end if;\n\n  if old.priority is distinct from new.priority and new.assigned_to is not null and new.assigned_to is distinct from actor then\n    perform public.notification_emit(\n      new.assigned_to,'admin','support','support.ticket.priority_changed',\n      'Priority changed on ticket #'||new.ticket_number::text,\n      'Priority: '||initcap(new.priority),'warning',actor,'support_ticket',new.id::text,\n      '/admin/support/'||new.id::text,jsonb_build_object('ticket_number',new.ticket_number,'from_priority',old.priority,'priority',new.priority),null\n    );\n  end if;\n\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_active_theme(p_surface text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare active_id text; t public.orbitfs_themes%rowtype;\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  if p_surface not in ('admin','customer') then raise exception 'invalid surface'; end if;\n  select value #>> '{}' into active_id from public.app_settings where key=case when p_surface='admin' then 'themes.active_admin' else 'themes.active_customer' end;\n  active_id:=coalesce(active_id,case when p_surface='admin' then 'V3A' else 'V3C' end);\n  select * into t from public.orbitfs_themes where id=active_id and surface=p_surface;\n  if not found then\n    active_id:=case when p_surface='admin' then 'V3A' else 'V3C' end;\n    select * into t from public.orbitfs_themes where id=active_id;\n  end if;\n  return jsonb_build_object('id',t.id,'name',t.name,'surface',t.surface,'version',t.version,'is_builtin',t.is_builtin,'css_text',case when t.is_builtin then null else t.css_text end);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_alert_candidate_recipients(p_audience text, p_recipient_user_ids uuid[] DEFAULT NULL::uuid[], p_conditions jsonb DEFAULT '{}'::jsonb)\n RETURNS TABLE(user_id uuid, surface text, label text, email text)\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\n  select\n    au.id as user_id,\n    case when sm.user_id is not null and sm.status='active' then 'admin' else 'portal' end as surface,\n    coalesce(\n      nullif(btrim(up.display_name),''),\n      nullif(btrim(concat_ws(' ',up.first_name,up.last_name)),''),\n      au.email,\n      au.id::text\n    ) as label,\n    au.email\n  from auth.users au\n  left join public.user_profiles up on up.id=au.id\n  left join public.staff_members sm on sm.user_id=au.id\n  where\n    (\n      (p_audience='selected' and au.id=any(coalesce(p_recipient_user_ids,'{}'::uuid[])))\n      or (p_audience='staff' and sm.user_id is not null and sm.status='active')\n      or (p_audience='customers' and up.id is not null and not (sm.user_id is not null and sm.status='active'))\n      or (p_audience='everyone' and (up.id is not null or (sm.user_id is not null and sm.status='active')))\n    )\n    and (\n      nullif(btrim(coalesce(p_conditions->>'customer_status','')),'') is null\n      or lower(coalesce(up.status,''))=lower(btrim(p_conditions->>'customer_status'))\n    )\n    and (\n      nullif(btrim(coalesce(p_conditions->>'country_code','')),'') is null\n      or upper(coalesce(up.country_code,''))=upper(btrim(p_conditions->>'country_code'))\n    )\n    and (\n      coalesce(p_conditions->>'verified_only','false')<>'true'\n      or up.email_verified_at is not null\n    )\n    and (\n      nullif(btrim(coalesce(p_conditions->>'product_slug','')),'') is null\n      or exists(\n        select 1\n        from public.orders o\n        join public.order_items oi on oi.order_id=o.id\n        where o.auth_user_id=au.id\n          and lower(coalesce(oi.product_slug,''))=lower(btrim(p_conditions->>'product_slug'))\n      )\n    )\n    and (\n      nullif(btrim(coalesce(p_conditions->>'service_status','')),'') is null\n      or exists(\n        select 1\n        from public.orders o\n        join public.order_items oi on oi.order_id=o.id\n        where o.auth_user_id=au.id\n          and lower(coalesce(oi.service_status,''))=lower(btrim(p_conditions->>'service_status'))\n      )\n    )\n    and (\n      nullif(btrim(coalesce(p_conditions->>'license_state','')),'') is null\n      or exists(\n        select 1 from public.license_bindings lb\n        where lb.auth_user_id=au.id\n          and lb.archived_at is null\n          and lower(coalesce(lb.remote_state,lb.desired_state,''))=lower(btrim(p_conditions->>'license_state'))\n      )\n    )\n    and (\n      nullif(btrim(coalesce(p_conditions->>'staff_status','')),'') is null\n      or lower(coalesce(sm.status,''))=lower(btrim(p_conditions->>'staff_status'))\n    )\n    and (\n      nullif(btrim(coalesce(p_conditions->>'staff_department','')),'') is null\n      or lower(coalesce(sm.department,''))=lower(btrim(p_conditions->>'staff_department'))\n    )\n    and (\n      nullif(btrim(coalesce(p_conditions->>'staff_group','')),'') is null\n      or exists(\n        select 1\n        from public.staff_member_groups smg\n        join public.staff_groups sg on sg.id=smg.group_id\n        where smg.user_id=au.id\n          and lower(sg.slug)=lower(btrim(p_conditions->>'staff_group'))\n      )\n    );\n$function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_alert_client_settings()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  enabled_value boolean:=true;\n  realtime_value boolean:=true;\n  feed_value integer:=40;\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  select coalesce((select (value#>>'{}')::boolean from public.app_settings where key='alerts.enabled'),true) into enabled_value;\n  select coalesce((select (value#>>'{}')::boolean from public.app_settings where key='alerts.realtime_enabled'),true) into realtime_value;\n  select greatest(10,least(100,coalesce((select (value#>>'{}')::integer from public.app_settings where key='alerts.feed_limit'),40))) into feed_value;\n  return jsonb_build_object('enabled',enabled_value,'realtime_enabled',realtime_value,'feed_limit',feed_value);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_alert_options()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  settings_json jsonb;\n  products_json jsonb;\n  customer_statuses_json jsonb;\n  countries_json jsonb;\n  service_statuses_json jsonb;\n  license_states_json jsonb;\n  staff_statuses_json jsonb;\n  staff_departments_json jsonb;\n  staff_groups_json jsonb;\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  if not public.has_permission('notifications.send') then raise exception 'permission denied'; end if;\n\n  select coalesce(jsonb_object_agg(replace(key,'alerts.',''),value),'{}'::jsonb)\n    into settings_json from public.app_settings where category='alerts';\n\n  select coalesce(jsonb_agg(jsonb_build_object('slug',slug,'name',name) order by name),'[]'::jsonb)\n    into products_json from public.products where active=true;\n\n  select coalesce(jsonb_agg(v order by v),'[]'::jsonb) into customer_statuses_json\n    from (select distinct status as v from public.user_profiles where nullif(btrim(status),'') is not null) q;\n  select coalesce(jsonb_agg(v order by v),'[]'::jsonb) into countries_json\n    from (select distinct upper(country_code) as v from public.user_profiles where nullif(btrim(country_code),'') is not null) q;\n  select coalesce(jsonb_agg(v order by v),'[]'::jsonb) into service_statuses_json\n    from (select distinct service_status as v from public.order_items where nullif(btrim(service_status),'') is not null) q;\n  select coalesce(jsonb_agg(v order by v),'[]'::jsonb) into license_states_json\n    from (\n      select distinct remote_state as v from public.license_bindings where archived_at is null and nullif(btrim(remote_state),'') is not null\n      union\n      select distinct desired_state as v from public.license_bindings where archived_at is null and nullif(btrim(desired_state),'') is not null\n    ) q;\n  select coalesce(jsonb_agg(v order by v),'[]'::jsonb) into staff_statuses_json\n    from (select distinct status as v from public.staff_members where nullif(btrim(status),'') is not null) q;\n  select coalesce(jsonb_agg(v order by v),'[]'::jsonb) into staff_departments_json\n    from (select distinct department as v from public.staff_members where nullif(btrim(department),'') is not null) q;\n  select coalesce(jsonb_agg(jsonb_build_object('slug',slug,'name',name) order by sort_order,name),'[]'::jsonb)\n    into staff_groups_json from public.staff_groups;\n\n  return jsonb_build_object(\n    'settings',settings_json,\n    'products',products_json,\n    'customer_statuses',customer_statuses_json,\n    'countries',countries_json,\n    'service_statuses',service_statuses_json,\n    'license_states',license_states_json,\n    'staff_statuses',staff_statuses_json,\n    'staff_departments',staff_departments_json,\n    'staff_groups',staff_groups_json\n  );\nend $function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_alert_preview(p_audience text, p_recipient_user_ids uuid[] DEFAULT NULL::uuid[], p_conditions jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  total integer:=0;\n  sample_json jsonb:='[]'::jsonb;\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  if not public.has_permission('notifications.send') then raise exception 'permission denied'; end if;\n  if p_audience not in ('selected','customers','staff','everyone') then raise exception 'invalid audience'; end if;\n\n  select count(*) into total\n  from public.orbitfs_alert_candidate_recipients(p_audience,p_recipient_user_ids,coalesce(p_conditions,'{}'::jsonb));\n\n  select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into sample_json\n  from (\n    select user_id,surface,label,email\n    from public.orbitfs_alert_candidate_recipients(p_audience,p_recipient_user_ids,coalesce(p_conditions,'{}'::jsonb))\n    order by label,email\n    limit 8\n  ) x;\n\n  return jsonb_build_object('count',total,'sample',sample_json);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_alert_send(p_audience text, p_recipient_user_ids uuid[] DEFAULT NULL::uuid[], p_kind text DEFAULT 'notification'::text, p_title text DEFAULT ''::text, p_message text DEFAULT ''::text, p_severity text DEFAULT 'info'::text, p_action_url text DEFAULT NULL::text, p_conditions jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  actor uuid:=auth.uid();\n  dispatch_id uuid:=gen_random_uuid();\n  sent integer:=0;\n  r record;\n  clean_title text:=btrim(coalesce(p_title,''));\n  clean_message text:=btrim(coalesce(p_message,''));\n  clean_action text:=nullif(btrim(coalesce(p_action_url,'')),'');\n  actor_email text;\n  system_enabled boolean:=true;\n  manual_enabled boolean:=true;\n  type_enabled boolean:=true;\n  links_enabled boolean:=true;\n  max_message integer:=4000;\nbegin\n  if actor is null then raise exception 'authentication required'; end if;\n  if not public.has_permission('notifications.send') then raise exception 'permission denied'; end if;\n  if p_audience not in ('selected','customers','staff','everyone') then raise exception 'invalid audience'; end if;\n  if p_kind not in ('notification','message','alert','announcement','maintenance') then raise exception 'invalid alert type'; end if;\n  if p_severity not in ('info','success','warning','error') then raise exception 'invalid severity'; end if;\n\n  select coalesce((select (value#>>'{}')::boolean from public.app_settings where key='alerts.enabled'),true) into system_enabled;\n  select coalesce((select (value#>>'{}')::boolean from public.app_settings where key='alerts.manual_send_enabled'),true) into manual_enabled;\n  select coalesce((select (value#>>'{}')::boolean from public.app_settings where key='alerts.action_links_enabled'),true) into links_enabled;\n  select coalesce((select (value#>>'{}')::boolean from public.app_settings where key='alerts.type_'||p_kind||'_enabled'),true) into type_enabled;\n  select greatest(100,least(4000,coalesce((select (value#>>'{}')::integer from public.app_settings where key='alerts.max_message_length'),4000))) into max_message;\n\n  if not system_enabled then raise exception 'OrbitFS Alert System is disabled'; end if;\n  if not manual_enabled then raise exception 'manual alert sending is disabled'; end if;\n  if not type_enabled then raise exception '% alerts are disabled',p_kind; end if;\n  if clean_title='' then raise exception 'title is required'; end if;\n  if length(clean_title)>160 then raise exception 'title is too long'; end if;\n  if length(clean_message)>max_message then raise exception 'message exceeds configured limit of % characters',max_message; end if;\n  if clean_action is not null and not links_enabled then raise exception 'alert action links are disabled'; end if;\n  if clean_action is not null and (left(clean_action,1)<>'/' or left(clean_action,2)='//') then\n    raise exception 'action path must be a local OrbitFS path';\n  end if;\n  if p_audience='selected' and coalesce(array_length(p_recipient_user_ids,1),0)=0 then\n    raise exception 'select at least one recipient';\n  end if;\n\n  for r in\n    select * from public.orbitfs_alert_candidate_recipients(\n      p_audience,p_recipient_user_ids,coalesce(p_conditions,'{}'::jsonb)\n    )\n  loop\n    perform public.notification_emit(\n      r.user_id,\n      r.surface,\n      'orbitfs_alert',\n      'orbitfs.alert.manual.'||p_kind,\n      clean_title,\n      clean_message,\n      p_severity,\n      actor,\n      'orbitfs_alert_dispatch',\n      dispatch_id::text,\n      clean_action,\n      jsonb_build_object(\n        'manual',true,\n        'kind',p_kind,\n        'dispatch_id',dispatch_id,\n        'audience',p_audience,\n        'conditions',coalesce(p_conditions,'{}'::jsonb)\n      ),\n      'orbitfs-alert-'||dispatch_id::text||'-'||r.user_id::text\n    );\n    sent:=sent+1;\n  end loop;\n\n  select email into actor_email from auth.users where id=actor;\n  insert into public.admin_audit_log(actor_id,actor_email,action,target_type,target_id,detail)\n  values(\n    actor,actor_email,'orbitfs.alert.send','orbitfs_alert_dispatch',dispatch_id::text,\n    jsonb_build_object(\n      'audience',p_audience,\n      'kind',p_kind,\n      'severity',p_severity,\n      'title',clean_title,\n      'action_url',clean_action,\n      'conditions',coalesce(p_conditions,'{}'::jsonb),\n      'sent',sent,\n      'selected_count',coalesce(array_length(p_recipient_user_ids,1),0)\n    )\n  );\n\n  return jsonb_build_object('ok',true,'dispatch_id',dispatch_id,'sent',sent);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_installations_touch_updated_at()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public'\nAS $function$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_release_public_settings()\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nselect jsonb_build_object(\n 'enabled',enabled,'customer_deploy_enabled',customer_deploy_enabled,'customer_updates_enabled',customer_updates_enabled,\n 'customer_rollbacks_enabled',customer_rollbacks_enabled,'allow_existing_supabase_project',allow_existing_supabase_project,\n 'allow_create_supabase_project',allow_create_supabase_project,'supabase_oauth_enabled',supabase_oauth_enabled,\n 'vercel_oauth_enabled',vercel_oauth_enabled,'schema_version',schema_version,'release_channel',release_channel\n) from public.orbitfs_release_system_settings where id='primary';\n$function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_theme_apply(p_theme_id text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare t public.orbitfs_themes%rowtype; setting_key text;\nbegin\n  if not public.is_admin() then raise exception 'admin required'; end if;\n  select * into t from public.orbitfs_themes where id=p_theme_id;\n  if not found then raise exception 'theme not installed'; end if;\n  setting_key:=case when t.surface='admin' then 'themes.active_admin' else 'themes.active_customer' end;\n  insert into public.app_settings(key,value,category,public_read)\n  values(setting_key,to_jsonb(t.id),'themes',false)\n  on conflict(key) do update set value=excluded.value,updated_at=now();\n  return jsonb_build_object('ok',true,'theme_id',t.id,'surface',t.surface);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_theme_import(p_manifest jsonb, p_css text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare tid text; tname text; tsurface text; tversion text;\nbegin\n  if not public.is_admin() then raise exception 'admin required'; end if;\n  tid:=nullif(trim(p_manifest->>'id'),''); tname:=coalesce(nullif(trim(p_manifest->>'name'),''),tid);\n  tsurface:=nullif(trim(p_manifest->>'surface'),''); tversion:=coalesce(nullif(trim(p_manifest->>'version'),''),'1.0.0');\n  if tid is null or tsurface not in ('admin','customer') then raise exception 'invalid theme manifest'; end if;\n  if tid in ('V3A','V3C') then raise exception 'built-in theme IDs cannot be overwritten'; end if;\n  if coalesce(length(p_css),0)<20 then raise exception 'theme CSS is empty'; end if;\n  insert into public.orbitfs_themes(id,name,surface,version,description,manifest,css_text,is_builtin,updated_at)\n  values(tid,tname,tsurface,tversion,coalesce(p_manifest->>'description',''),p_manifest,p_css,false,now())\n  on conflict(id) do update set name=excluded.name,surface=excluded.surface,version=excluded.version,description=excluded.description,manifest=excluded.manifest,css_text=excluded.css_text,updated_at=now();\n  return jsonb_build_object('ok',true,'theme_id',tid,'surface',tsurface);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.orbitfs_theme_list()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if not public.is_admin() then raise exception 'admin required'; end if;\n  return jsonb_build_object(\n    'themes',coalesce((select jsonb_agg(to_jsonb(t) order by t.surface,t.id) from public.orbitfs_themes t),'[]'::jsonb),\n    'active_admin',coalesce((select value #>> '{}' from public.app_settings where key='themes.active_admin'),'V3A'),\n    'active_customer',coalesce((select value #>> '{}' from public.app_settings where key='themes.active_customer'),'V3C')\n  );\nend $function$\n\nCREATE OR REPLACE FUNCTION public.order_cancellation_mail_context(p_request_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  r public.order_cancellation_requests%rowtype;\n  o public.orders%rowtype;\n  c public.customers%rowtype;\n  p public.user_profiles%rowtype;\n  uid uuid:=auth.uid();\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  select * into r from public.order_cancellation_requests where id=p_request_id;\n  if not found then raise exception 'cancellation request not found'; end if;\n  if r.auth_user_id<>uid and not public.is_staff() then raise exception 'permission denied'; end if;\n  select * into o from public.orders where id=r.order_id;\n  select * into c from public.customers where auth_user_id=r.auth_user_id limit 1;\n  select * into p from public.user_profiles where id=r.auth_user_id;\n  return jsonb_build_object(\n    'request_id',r.id,'order_id',r.order_id,'auth_user_id',r.auth_user_id,\n    'status',r.status,'requested_timing',r.requested_timing,'scheduled_for',r.scheduled_for,\n    'reason',r.reason,'staff_note',r.staff_note,'order_number',o.order_number,\n    'order_status',o.status,'payment_status',o.payment_status,\n    'email',c.email,'customer_name',coalesce(nullif(c.name,''),nullif(p.display_name,''),nullif(p.first_name,''),'Customer')\n  );\nend $function$\n\nCREATE OR REPLACE FUNCTION public.order_requires_manual_approval(p_order_id uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select coalesce(bool_or(p.approval_mode='manual'),false)\n  from public.order_items oi join public.products p on p.id=oi.product_id\n  where oi.order_id=p_order_id;\n$function$\n\nCREATE OR REPLACE FUNCTION public.pay_invoice_with_credit(p_invoice_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  res jsonb;\nbegin\n  res := public.apply_wallet_credit_to_invoice(p_invoice_id, null);\n  return res;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.payment_attempt_checkout_state(p_attempt_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare a public.payment_attempts%rowtype;\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  select * into a from public.payment_attempts where id=p_attempt_id and auth_user_id=auth.uid();\n  if not found then raise exception 'payment attempt not found'; end if;\n  return jsonb_build_object('id',a.id,'gateway_code',a.gateway_code,'status',a.status,'provider_reference',a.provider_reference,'checkout_url',a.checkout_url,'failure_code',a.failure_code,'failure_message',a.failure_message,'invoice_id',a.invoice_id,'wallet_recharge_id',a.wallet_recharge_id);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.payment_attempt_context(p_attempt_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  uid uuid:=auth.uid();\n  a public.payment_attempts%rowtype;\n  i public.invoices%rowtype;\n  r public.wallet_recharges%rowtype;\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  select * into a from public.payment_attempts where id=p_attempt_id and auth_user_id=uid;\n  if not found then raise exception 'payment attempt not found'; end if;\n  if a.wallet_recharge_id is not null then\n    select * into r from public.wallet_recharges where id=a.wallet_recharge_id and auth_user_id=uid;\n    if not found then raise exception 'wallet recharge not found'; end if;\n    return jsonb_build_object('attempt_id',a.id,'gateway_code',a.gateway_code,'status',a.status,'amount_cents',a.amount_cents,'currency',a.currency,'payment_kind','wallet_recharge','wallet_recharge_id',r.id,'receipt_number',r.receipt_number,'invoice_id',null,'invoice_number',null,'order_id',null);\n  end if;\n  select * into i from public.invoices where id=a.invoice_id and auth_user_id=uid;\n  if not found then raise exception 'invoice not found'; end if;\n  return jsonb_build_object('attempt_id',a.id,'gateway_code',a.gateway_code,'status',a.status,'amount_cents',a.amount_cents,'currency',a.currency,'payment_kind','invoice','invoice_id',i.id,'invoice_number',i.invoice_number,'order_id',i.order_id,'wallet_recharge_id',null,'receipt_number',null);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.preview_coupon(p_product_id uuid, p_configuration jsonb DEFAULT '{}'::jsonb, p_coupon_code text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare uid uuid:=auth.uid(); prod public.products%rowtype; c public.coupons%rowtype; subtotal bigint; option_total bigint:=0; discount bigint:=0; used_count integer; opt record; selected text; choice jsonb; begin if uid is null then raise exception 'authentication required'; end if; select * into prod from public.products where id=p_product_id and active=true; if not found then raise exception 'product unavailable'; end if; subtotal:=coalesce(prod.price_cents,0); for opt in select * from public.product_options where product_id=prod.id and active=true order by sort_order loop selected:=p_configuration->>opt.key; if opt.required and (selected is null or btrim(selected)='') then raise exception 'Required option missing: %',opt.label; end if; if selected is not null and btrim(selected)<>'' then if opt.option_type='select' and jsonb_array_length(opt.choices)>0 then select x into choice from jsonb_array_elements(opt.choices) x where (jsonb_typeof(x)='string' and trim(both '"' from x::text)=selected) or (jsonb_typeof(x)='object' and x->>'value'=selected) limit 1; if choice is null then raise exception 'Invalid choice for %',opt.label; end if; option_total:=option_total+coalesce(case when jsonb_typeof(choice)='object' then nullif(choice->>'price_delta_cents','')::bigint else null end,opt.price_delta_cents,0); else option_total:=option_total+coalesce(opt.price_delta_cents,0); end if; end if; end loop; subtotal:=subtotal+option_total; if p_coupon_code is null or btrim(p_coupon_code)='' then raise exception 'enter a coupon code'; end if; select * into c from public.coupons where lower(code)=lower(btrim(p_coupon_code)) and active=true and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()) and subtotal>=min_order_cents and (cardinality(product_ids)=0 or prod.id=any(product_ids)); if not found then raise exception 'coupon is invalid, expired, not yet active, below its minimum spend, or not available for this product'; end if; select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id; if c.max_redemptions is not null and used_count>=c.max_redemptions then raise exception 'coupon redemption limit reached'; end if; select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id and auth_user_id=uid; if used_count>=c.per_user_limit then raise exception 'coupon usage limit reached for this account'; end if; if c.discount_type='percent' then discount:=least(subtotal,round(subtotal*(c.discount_value::numeric/100))); else discount:=least(subtotal,c.discount_value); end if; return jsonb_build_object('valid',true,'code',c.code,'description',c.description,'subtotal_cents',subtotal,'discount_cents',discount,'total_cents',greatest(0,subtotal-discount),'discount_type',c.discount_type,'discount_value',c.discount_value); end $function$\n\nCREATE OR REPLACE FUNCTION public.process_cancellation_credit_refund(p_request_id uuid, p_payment_id uuid, p_amount_cents bigint)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  r public.order_cancellation_requests%rowtype;\n  inv public.invoices%rowtype;\n  pay public.invoice_payments%rowtype;\n  already bigint:=0;\n  newbal bigint;\n  rid uuid;\nbegin\n  if not public.has_permission('customers.cancellations') then raise exception 'permission denied: customers.cancellations'; end if;\n  select * into r from public.order_cancellation_requests where id=p_request_id for update;\n  if not found then raise exception 'cancellation request not found'; end if;\n  if r.status<>'completed' or r.refund_preference<>'original' then raise exception 'original-method refund is not ready'; end if;\n  select * into inv from public.invoices where order_id=r.order_id order by created_at desc limit 1;\n  select * into pay from public.invoice_payments where id=p_payment_id and invoice_id=inv.id and status='completed';\n  if not found or pay.method<>'account_credit' then raise exception 'Wallet payment not found'; end if;\n  select coalesce(sum(amount_cents),0) into already from public.invoice_refunds where payment_id=pay.id and status in ('pending','processing','completed','succeeded');\n  if p_amount_cents<=0 or p_amount_cents>pay.amount_cents-already then raise exception 'invalid refund amount'; end if;\n  newbal:=public.wallet_credit(inv.auth_user_id,p_amount_cents,'Original Wallet payment refund','cancellation_refund',r.id::text,jsonb_build_object('invoice_id',inv.id,'payment_id',pay.id,'order_id',r.order_id),auth.uid());\n  insert into public.invoice_refunds(invoice_id,payment_id,auth_user_id,method,amount_cents,status,reason,created_by,metadata)\n  values(inv.id,pay.id,inv.auth_user_id,'account_credit',p_amount_cents,'completed','Refund for cancelled unactivated order',auth.uid(),jsonb_build_object('balance_after_cents',newbal,'cancellation_request_id',r.id,'refund_preference','original')) returning id into rid;\n  return jsonb_build_object('ok',true,'refund_id',rid,'amount_cents',p_amount_cents,'wallet_balance_cents',newbal,'status','completed');\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.process_cancellation_wallet_refund(p_request_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  r public.order_cancellation_requests%rowtype;\n  inv public.invoices%rowtype;\n  committed bigint:=0;\n  processed_since bigint:=0;\n  amt bigint:=0;\n  newbal bigint;\n  rid uuid;\nbegin\n  if not public.has_permission('customers.cancellations') then raise exception 'permission denied: customers.cancellations'; end if;\n  select * into r from public.order_cancellation_requests where id=p_request_id for update;\n  if not found then raise exception 'cancellation request not found'; end if;\n  if r.status<>'completed' then raise exception 'cancellation must be completed before refund'; end if;\n  if r.refund_preference<>'wallet' then raise exception 'refund preference is not Wallet'; end if;\n  select * into inv from public.invoices where order_id=r.order_id order by created_at desc limit 1 for update;\n  select coalesce(sum(amount_cents),0) into committed from public.invoice_refunds where invoice_id=inv.id and status in ('pending','processing','completed','succeeded');\n  processed_since:=greatest(0,committed-coalesce(r.refund_baseline_cents,0));\n  amt:=least(greatest(0,r.refund_amount_cents-processed_since),greatest(0,inv.paid_cents-committed));\n  if amt<=0 then\n    update public.order_cancellation_requests set refund_status='completed',refund_processed_cents=refund_amount_cents,refund_completed_at=coalesce(refund_completed_at,now()),refund_last_error=null,updated_at=now() where id=r.id;\n    return jsonb_build_object('ok',true,'already_refunded',true,'amount_cents',0);\n  end if;\n  newbal:=public.wallet_credit(inv.auth_user_id,amt,'Cancellation refund to Wallet','cancellation_refund',r.id::text,jsonb_build_object('invoice_id',inv.id,'invoice_number',inv.invoice_number,'order_id',r.order_id),auth.uid());\n  insert into public.invoice_refunds(invoice_id,auth_user_id,method,amount_cents,status,reason,created_by,metadata)\n  values(inv.id,inv.auth_user_id,'wallet',amt,'completed','Refund for cancelled unactivated order',auth.uid(),jsonb_build_object('balance_after_cents',newbal,'cancellation_request_id',r.id,'refund_preference','wallet')) returning id into rid;\n  update public.order_cancellation_requests set refund_status='completed',refund_processed_cents=refund_amount_cents,refund_completed_at=now(),refund_last_error=null,updated_at=now() where id=r.id;\n  insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(auth.uid(),'order.cancellation.refund_wallet','order',r.order_id::text,jsonb_build_object('request_id',r.id,'invoice_id',inv.id,'refund_id',rid,'amount_cents',amt));\n  return jsonb_build_object('ok',true,'refund_id',rid,'amount_cents',amt,'wallet_balance_cents',newbal,'status','completed');\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.process_due_order_cancellations()\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare r record; n int:=0; why text;\nbegin\n  for r in select * from public.order_cancellation_requests where status='approved_scheduled' and scheduled_for<=now() order by scheduled_for for update skip locked loop\n    why:=coalesce(nullif(btrim(r.staff_note),''),'Customer cancellation effective at end of billing cycle');\n    update public.orders set status='terminated',fulfillment_status='terminated',terminated_at=coalesce(terminated_at,now()),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('terminated_at',now(),'termination_reason',why,'recurring_enabled',false,'cancellation_status','completed','cancellation_completed_at',now()),updated_at=now() where id=r.order_id and status<>'terminated';\n    update public.order_items set service_status='terminated' where order_id=r.order_id;\n    update public.invoices set status='cancelled',notes=concat_ws(E'\\n',notes,'Order terminated: '||why),updated_at=now() where order_id=r.order_id and status in ('unpaid','partial','overdue');\n    update public.license_bindings set desired_state='revoked',remote_state=case when api_source='website' then 'revoked' else remote_state end,archived_at=coalesce(archived_at,now()),suspension_reason=why,updated_at=now() where order_id=r.order_id and archived_at is null;\n    update public.download_entitlements set status='revoked',revoked_at=now(),reason='Order terminated: '||why where order_id=r.order_id and status='active';\n    update public.license_enforcement_queue set state='cancelled',last_error='Order terminated before queued action completed',finished_at=coalesce(finished_at,now()) where binding_id in(select id from public.license_bindings where order_id=r.order_id) and state in ('queued','running');\n    update public.payment_subscriptions set cancel_at_period_end=true,status='cancelled',next_charge_at=null,updated_at=now() where order_id=r.order_id and coalesce(status,'') not in ('cancelled','canceled','terminated','ended');\n    perform public.sync_order_service_status(r.order_id);\n    perform public.bump_license_revision();\n    update public.order_cancellation_requests set status='completed',processed_at=now(),updated_at=now() where id=r.id;\n    insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail) values(null,'order.cancellation.auto_terminated','order',r.order_id::text,jsonb_build_object('request_id',r.id,'scheduled_for',r.scheduled_for));\n    n:=n+1;\n  end loop;\n  return n;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.process_expired_guest_support_tickets()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare deleted_count integer:=0; attempt_count integer:=0;\nbegin\n  with expired as (\n    select t.id\n    from public.support_tickets t\n    where t.user_id is null\n      and t.source='public_web'\n      and coalesce(\n        nullif(t.metadata->>'guest_access_expires_at','')::timestamptz,\n        t.created_at + interval '48 hours'\n      ) <= now()\n    for update skip locked\n  ), removed as (\n    delete from public.support_tickets t\n    using expired e\n    where t.id=e.id\n    returning t.id\n  )\n  select count(*) into deleted_count from removed;\n\n  with removed_attempts as (\n    delete from public.guest_support_access_attempts\n    where attempted_at < now() - interval '24 hours'\n    returning id\n  )\n  select count(*) into attempt_count from removed_attempts;\n\n  return jsonb_build_object(\n    'ok',true,\n    'deleted_count',deleted_count,\n    'access_attempts_cleaned',attempt_count,\n    'processed_at',now()\n  );\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.process_mail_billing_lifecycle()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  before_days integer:=1;\n  after_days integer:=1;\n  cancel_days integer:=3;\n  r record;\n  sent_due integer:=0;\n  sent_overdue integer:=0;\n  cancelled integer:=0;\n  inv_id uuid;\nbegin\n  select coalesce((select (value#>>'{}')::int from public.app_settings where key='invoice.reminder_before_days'),1) into before_days;\n  select coalesce((select (value#>>'{}')::int from public.app_settings where key='invoice.reminder_after_days'),1) into after_days;\n  select coalesce((select (value#>>'{}')::int from public.app_settings where key='invoice.auto_cancel_unpaid_days'),3) into cancel_days;\n\n  for r in select * from public.invoices where status in ('unpaid','partial','overdue') and due_at is not null loop\n    if r.due_at between now() and now()+make_interval(days=>before_days) then\n      perform public.enqueue_mail_event('invoice.due','invoice',r.id::text,r.auth_user_id,jsonb_build_object('invoice_number',r.invoice_number,'invoice_total_cents',r.total_cents,'invoice_due_cents',greatest(0,r.total_cents-coalesce(r.paid_cents,0)),'currency',r.currency,'due_at',r.due_at),'invoice.due:'||r.id::text||':'||to_char(r.due_at,'YYYYMMDD'));\n      sent_due:=sent_due+1;\n    end if;\n    if r.due_at<=now()-make_interval(days=>after_days) then\n      perform public.enqueue_mail_event('invoice.overdue','invoice',r.id::text,r.auth_user_id,jsonb_build_object('invoice_number',r.invoice_number,'invoice_total_cents',r.total_cents,'invoice_due_cents',greatest(0,r.total_cents-coalesce(r.paid_cents,0)),'currency',r.currency,'due_at',r.due_at),'invoice.overdue:'||r.id::text||':'||to_char(r.due_at,'YYYYMMDD'));\n      if r.status<>'overdue' then update public.invoices set status='overdue',updated_at=now() where id=r.id; end if;\n      sent_overdue:=sent_overdue+1;\n    end if;\n  end loop;\n\n  for r in select * from public.orders where status='pending_payment' and coalesce(payment_status,'') !~ '^paid' and created_at<=now()-make_interval(days=>cancel_days) loop\n    select id into inv_id from public.invoices where order_id=r.id order by created_at desc limit 1;\n    perform public.enqueue_mail_event('order.cancelled_unpaid','order',r.id::text,r.auth_user_id,jsonb_build_object('order_number',r.order_number,'order_total_cents',r.total_cents,'currency',r.currency,'reason','Payment not completed within the 3-day payment period'),'order.cancelled_unpaid:'||r.id::text);\n    update public.invoices set status='cancelled',updated_at=now() where order_id=r.id and status in ('unpaid','partial','overdue');\n    update public.orders set status='terminated',payment_status='cancelled',fulfillment_status='terminated',termination_reason='Payment not completed within the 3-day payment period',terminated_at=coalesce(terminated_at,now()),updated_at=now() where id=r.id;\n    if inv_id is not null then update public.payment_attempts set status='expired',updated_at=now() where invoice_id=inv_id and status in ('created','pending','action_required','processing'); end if;\n    cancelled:=cancelled+1;\n  end loop;\n\n  return jsonb_build_object('due_events',sent_due,'overdue_events',sent_overdue,'cancelled_unpaid_orders',cancelled);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.process_support_auto_close()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare r record; closed_count integer:=0;\nbegin\n  for r in\n    select t.id,t.ticket_number,t.user_id,d.auto_close_hours\n    from public.support_tickets t\n    join public.support_departments d on d.id=t.department_id\n    where d.enabled=true\n      and d.auto_close_hours is not null\n      and d.auto_close_hours>0\n      and t.archived_at is null\n      and t.status='customer_reply'\n      and t.last_staff_reply_at is not null\n      and t.last_staff_reply_at <= now() - make_interval(hours=>d.auto_close_hours)\n      and (t.last_client_reply_at is null or t.last_client_reply_at<=t.last_staff_reply_at)\n    order by t.last_staff_reply_at\n    for update of t skip locked\n  loop\n    update public.support_tickets\n      set status='closed',closed_at=now(),closed_by=null,updated_at=now()\n      where id=r.id and status='customer_reply';\n    if found then\n      perform public.support_emit_system_message(r.id,'auto_closed','{}'::jsonb);\n      insert into public.support_ticket_events(ticket_id,actor_user_id,event_type,detail)\n      values(r.id,null,'auto_closed',jsonb_build_object('auto_close_hours',r.auto_close_hours,'ticket_number',r.ticket_number));\n      closed_count:=closed_count+1;\n    end if;\n  end loop;\n  return jsonb_build_object('ok',true,'closed_count',closed_count,'processed_at',now());\nend $function$\n\nCREATE OR REPLACE FUNCTION public.protect_role_change()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ begin if old.role is distinct from new.role then if not exists(select 1 from public.user_profiles where role='superadmin') then return new; end if; if not public.has_permission('customers.roles') then raise exception 'permission denied: customers.roles'; end if; if old.role='superadmin' and public.current_role()<>'superadmin' then raise exception 'only superadmin can change a superadmin role'; end if; end if; if (old.status is distinct from new.status or old.suspension_reason is distinct from new.suspension_reason or old.suspended_at is distinct from new.suspended_at or old.banned_at is distinct from new.banned_at or old.ban_reason is distinct from new.ban_reason or old.ban_expires_at is distinct from new.ban_expires_at) then if new.id=auth.uid() then raise exception 'use account enforcement controls; self enforcement changes are blocked'; end if; if not public.has_permission('customers.enforce') then raise exception 'permission denied: customers.enforce'; end if; end if; return new; end $function$\n\nCREATE OR REPLACE FUNCTION public.queue_account_license_action(target_user uuid, action_name text, why text, source_name text DEFAULT 'system'::text)\n RETURNS integer\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare n integer; begin insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source,payload) select b.id,b.auth_user_id,b.license_id,action_name,why,source_name,jsonb_build_object('desiredState',b.desired_state,'productKey',b.license_product_key) from public.license_bindings b where b.auth_user_id=target_user and b.desired_state<>'revoked'; get diagnostics n=row_count; return n; end $function$\n\nCREATE OR REPLACE FUNCTION public.record_cancellation_external_refund(p_request_id uuid, p_payment_id uuid, p_amount_cents bigint, p_external_reference text, p_status text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  r public.order_cancellation_requests%rowtype;\n  inv public.invoices%rowtype;\n  pay public.invoice_payments%rowtype;\n  already bigint:=0;\n  rid uuid;\n  st text:=lower(coalesce(p_status,'pending'));\nbegin\n  if not public.has_permission('customers.cancellations') then raise exception 'permission denied: customers.cancellations'; end if;\n  if st not in ('pending','processing','completed','succeeded','failed','cancelled') then st:='pending'; end if;\n  select * into r from public.order_cancellation_requests where id=p_request_id for update;\n  if not found then raise exception 'cancellation request not found'; end if;\n  if r.status<>'completed' or r.refund_preference<>'original' then raise exception 'original-method refund is not ready'; end if;\n  select * into inv from public.invoices where order_id=r.order_id order by created_at desc limit 1;\n  select * into pay from public.invoice_payments where id=p_payment_id and invoice_id=inv.id and status='completed';\n  if not found or pay.method not in ('stripe','paypal') then raise exception 'external payment not found'; end if;\n  select coalesce(sum(amount_cents),0) into already from public.invoice_refunds where payment_id=pay.id and status in ('pending','processing','completed','succeeded');\n  if p_amount_cents<=0 or p_amount_cents>pay.amount_cents-already then raise exception 'invalid refund amount'; end if;\n  insert into public.invoice_refunds(invoice_id,payment_id,auth_user_id,method,amount_cents,status,external_reference,reason,created_by,metadata)\n  values(inv.id,pay.id,inv.auth_user_id,pay.method,p_amount_cents,st,p_external_reference,'Refund for cancelled unactivated order',auth.uid(),coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('cancellation_request_id',r.id,'refund_preference','original','original_payment_reference',pay.external_reference)) returning id into rid;\n  return jsonb_build_object('ok',true,'refund_id',rid,'amount_cents',p_amount_cents,'status',st,'method',pay.method);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.record_payment_checkout_start(p_attempt_id uuid, p_provider_reference text, p_checkout_url text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_uid uuid:=auth.uid(); v_gateway text; v_recharge uuid;\nbegin\n  if v_uid is null then raise exception 'Unauthorized'; end if;\n  update public.payment_attempts\n  set provider_reference=coalesce(nullif(p_provider_reference,''),provider_reference),\n      checkout_url=coalesce(nullif(p_checkout_url,''),checkout_url),\n      status=case when status in ('created','failed','cancelled','expired') then 'action_required' else status end,\n      metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),\n      failure_code=null,\n      failure_message=null,\n      updated_at=now()\n  where id=p_attempt_id and auth_user_id=v_uid\n  returning gateway_code,wallet_recharge_id into v_gateway,v_recharge;\n  if not found then raise exception 'Payment attempt not found or not permitted'; end if;\n  if v_recharge is not null then\n    update public.wallet_recharges set status='action_required',gateway_code=v_gateway,updated_at=now() where id=v_recharge and auth_user_id=v_uid;\n  end if;\n  insert into public.payment_events(payment_attempt_id,gateway_code,event_type,payload)\n  values(p_attempt_id,v_gateway,'checkout.started',coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('provider_reference',p_provider_reference,'checkout_url',p_checkout_url));\n  return true;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.record_payment_provider_event(p_attempt_id uuid, p_gateway_code text, p_event_type text, p_provider_event_id text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_provider_reference text DEFAULT NULL::text, p_failure_code text DEFAULT NULL::text, p_failure_message text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare a public.payment_attempts%rowtype;\nbegin\n  if auth.role()<>'service_role' then raise exception 'permission denied'; end if;\n  select * into a from public.payment_attempts where id=p_attempt_id for update;\n  if not found then raise exception 'payment attempt not found'; end if;\n  insert into public.payment_events(payment_attempt_id,gateway_code,event_type,provider_event_id,payload)\n  values(p_attempt_id,p_gateway_code,p_event_type,p_provider_event_id,coalesce(p_payload,'{}'::jsonb))\n  on conflict (gateway_code,provider_event_id) where provider_event_id is not null do nothing;\n  if p_status is not null then\n    update public.payment_attempts set\n      status=p_status,\n      provider_reference=coalesce(nullif(p_provider_reference,''),provider_reference),\n      failure_code=p_failure_code,\n      failure_message=p_failure_message,\n      metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_payload,'{}'::jsonb),\n      completed_at=case when p_status in ('succeeded','failed','cancelled','expired') then coalesce(completed_at,now()) else completed_at end,\n      updated_at=now()\n    where id=p_attempt_id and gateway_code=p_gateway_code and status<>'succeeded';\n    if a.wallet_recharge_id is not null and p_status<>'succeeded' then\n      update public.wallet_recharges set\n        status=case when p_status in ('failed','cancelled','expired','refunded') then p_status when p_status='processing' then 'processing' else 'action_required' end,\n        gateway_code=p_gateway_code,\n        provider_reference=coalesce(nullif(p_provider_reference,''),provider_reference),\n        metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_payload,'{}'::jsonb),\n        updated_at=now()\n      where id=a.wallet_recharge_id and status<>'succeeded';\n    end if;\n  end if;\n  return true;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.record_payment_start_observation(p_attempt_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare a public.payment_attempts%rowtype; ev text; new_status text; payload jsonb;\nbegin\n  if auth.uid() is null then raise exception 'authentication required'; end if;\n  select * into a from public.payment_attempts where id=p_attempt_id and auth_user_id=auth.uid() for update;\n  if not found then raise exception 'payment attempt not found'; end if;\n  if a.failure_code is not null then ev:='checkout.failed'; new_status:='failed';\n  elsif a.checkout_url is not null or a.provider_reference is not null then ev:='checkout.started'; new_status:='action_required';\n  else ev:='checkout.pending'; new_status:=a.status; end if;\n  payload:=jsonb_build_object('provider_reference',a.provider_reference,'failure_code',a.failure_code,'failure_message',a.failure_message)||coalesce(a.metadata,'{}'::jsonb);\n  update public.payment_attempts set status=new_status,updated_at=now() where id=a.id and status<>'succeeded';\n  if a.wallet_recharge_id is not null and new_status<>'succeeded' then\n    update public.wallet_recharges set status=case when new_status='failed' then 'failed' else 'action_required' end,gateway_code=a.gateway_code,updated_at=now() where id=a.wallet_recharge_id;\n  end if;\n  if not exists(select 1 from public.payment_events e where e.payment_attempt_id=a.id and e.event_type=ev and coalesce(e.payload->>'provider_reference','')=coalesce(a.provider_reference,'') and coalesce(e.payload->>'failure_code','')=coalesce(a.failure_code,'')) then\n    insert into public.payment_events(payment_attempt_id,gateway_code,event_type,payload) values(a.id,a.gateway_code,ev,payload);\n  end if;\n  return jsonb_build_object('ok',true,'status',new_status,'event_type',ev);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.record_paypal_checkout_cancel(p_attempt_id uuid, p_token text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare a public.payment_attempts%rowtype;\nbegin\n  select * into a from public.payment_attempts where id=p_attempt_id for update;\n  if not found then raise exception 'payment attempt not found'; end if;\n  if coalesce(a.metadata->>'paypal_cancel_token','')='' or a.metadata->>'paypal_cancel_token'<>p_token then raise exception 'invalid cancellation token'; end if;\n  if a.status='succeeded' then return jsonb_build_object('ok',true,'already_paid',true,'invoice_id',a.invoice_id,'wallet_recharge_id',a.wallet_recharge_id); end if;\n  update public.payment_attempts set status='cancelled',checkout_url=null,failure_code='checkout_cancelled',failure_message='Customer cancelled PayPal Checkout.',metadata=coalesce(metadata,'{}'::jsonb)-'paypal_cancel_token',updated_at=now() where id=a.id;\n  if a.wallet_recharge_id is not null then\n    update public.wallet_recharges set status='cancelled',updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('last_cancelled_at',now()) where id=a.wallet_recharge_id;\n  end if;\n  insert into public.payment_events(payment_attempt_id,gateway_code,event_type,payload) values(a.id,'paypal','checkout.cancelled',jsonb_build_object('provider_reference',a.provider_reference,'reason','customer_cancelled'));\n  return jsonb_build_object('ok',true,'invoice_id',a.invoice_id,'wallet_recharge_id',a.wallet_recharge_id);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.record_paypal_provider_event(p_attempt_id uuid, p_event_type text, p_provider_event_id text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_provider_reference text DEFAULT NULL::text, p_failure_code text DEFAULT NULL::text, p_failure_message text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare a public.payment_attempts%rowtype; effective_status text;\nbegin\n  if auth.role()<>'service_role' and not public.has_permission('payments.manage') then raise exception 'permission denied'; end if;\n  select * into a from public.payment_attempts where id=p_attempt_id for update;\n  if not found then raise exception 'payment attempt not found'; end if;\n  if p_provider_event_id is not null and exists(select 1 from public.payment_events where provider_event_id=p_provider_event_id and gateway_code='paypal') then\n    return jsonb_build_object('ok',true,'duplicate',true,'attempt_id',a.id,'invoice_id',a.invoice_id,'wallet_recharge_id',a.wallet_recharge_id);\n  end if;\n  effective_status:=p_status;\n  if p_event_type='CHECKOUT.ORDER.COMPLETED' and effective_status='succeeded' then effective_status:='processing'; end if;\n  update public.payment_attempts set\n    status=case when a.status='succeeded' and coalesce(effective_status,'') not in ('succeeded','refunded','reversed') then a.status else coalesce(effective_status,a.status) end,\n    provider_reference=coalesce(p_provider_reference,provider_reference),\n    failure_code=case when effective_status in ('failed','cancelled','expired') then coalesce(p_failure_code,failure_code) when effective_status='succeeded' then null else failure_code end,\n    failure_message=case when effective_status in ('failed','cancelled','expired') then coalesce(p_failure_message,failure_message) when effective_status='succeeded' then null else failure_message end,\n    metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),\n    updated_at=now()\n  where id=a.id;\n  if a.wallet_recharge_id is not null and effective_status is not null and effective_status<>'succeeded' then\n    update public.wallet_recharges\n      set status=case when effective_status in ('failed','cancelled','expired','refunded') then effective_status when effective_status='processing' then 'processing' else 'action_required' end,\n          provider_reference=coalesce(p_provider_reference,provider_reference),\n          gateway_code='paypal',\n          metadata=coalesce(metadata,'{}'::jsonb)||coalesce(p_metadata,'{}'::jsonb),\n          updated_at=now()\n      where id=a.wallet_recharge_id and status<>'succeeded';\n  end if;\n  insert into public.payment_events(payment_attempt_id,gateway_code,event_type,provider_event_id,payload)\n  values(a.id,'paypal',p_event_type,p_provider_event_id,coalesce(p_metadata,'{}'::jsonb)||jsonb_build_object('provider_reference',p_provider_reference,'failure_code',p_failure_code,'failure_message',p_failure_message));\n  return jsonb_build_object('ok',true,'attempt_id',a.id,'invoice_id',a.invoice_id,'wallet_recharge_id',a.wallet_recharge_id,'order_id',(select order_id from public.invoices where id=a.invoice_id));\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.record_wallet_checkout_cancel(p_attempt_id uuid, p_token text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare a public.payment_attempts%rowtype;\nbegin\n  select * into a from public.payment_attempts where id=p_attempt_id for update;\n  if not found then raise exception 'payment attempt not found'; end if;\n  if a.wallet_recharge_id is null then raise exception 'not a Wallet recharge payment'; end if;\n  if coalesce(a.metadata->>'wallet_cancel_token','')='' or a.metadata->>'wallet_cancel_token'<>p_token then raise exception 'invalid cancellation token'; end if;\n  if a.status='succeeded' then return jsonb_build_object('ok',true,'already_paid',true,'wallet_recharge_id',a.wallet_recharge_id); end if;\n  update public.payment_attempts\n    set status='cancelled',checkout_url=null,failure_code='checkout_cancelled',failure_message='Customer cancelled Wallet recharge checkout.',metadata=coalesce(metadata,'{}'::jsonb)-'wallet_cancel_token',updated_at=now()\n    where id=a.id;\n  update public.wallet_recharges\n    set status='cancelled',updated_at=now(),metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('last_cancelled_at',now(),'last_attempt_id',a.id)\n    where id=a.wallet_recharge_id;\n  insert into public.payment_events(payment_attempt_id,gateway_code,event_type,payload)\n    values(a.id,a.gateway_code,'checkout.cancelled',jsonb_build_object('provider_reference',a.provider_reference,'reason','customer_cancelled','wallet_recharge_id',a.wallet_recharge_id));\n  return jsonb_build_object('ok',true,'wallet_recharge_id',a.wallet_recharge_id);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.redeem_wallet_coupon(p_coupon_code text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); c public.coupons%rowtype; used_count integer; newbal bigint;\nbegin\n if uid is null then raise exception 'authentication required'; end if;\n select * into c from public.coupons where lower(code)=lower(btrim(p_coupon_code)) and active=true and discount_type='wallet_credit' and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now());\n if not found then raise exception 'wallet coupon is invalid, expired, or unavailable'; end if;\n select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id;\n if c.max_redemptions is not null and used_count>=c.max_redemptions then raise exception 'coupon redemption limit reached'; end if;\n select count(*) into used_count from public.coupon_redemptions where coupon_id=c.id and auth_user_id=uid;\n if used_count>=c.per_user_limit then raise exception 'coupon usage limit reached for this account'; end if;\n newbal:=public.wallet_credit(uid,c.discount_value,'Coupon wallet credit','coupon',c.id::text,jsonb_build_object('coupon_code',c.code),uid);\n insert into public.coupon_redemptions(coupon_id,invoice_id,auth_user_id,discount_cents,credit_cents) values(c.id,null,uid,0,c.discount_value);\n return jsonb_build_object('ok',true,'code',c.code,'credit_cents',c.discount_value,'balance_cents',newbal);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.remove_from_cart(p_item_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); begin\n delete from public.shopping_cart_items i using public.shopping_carts c where i.id=p_item_id and i.cart_id=c.id and c.auth_user_id=uid;\n if not found then raise exception 'basket item not found'; end if;\n return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.request_license_controller_action(p_binding_id uuid, p_action text, p_component_key text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'extensions'\nAS $function$ declare uid uuid:=auth.uid(); b public.license_bindings%rowtype; req uuid; queue_action text; k text; begin if uid is null then raise exception 'authentication required'; end if; select * into b from public.license_bindings where id=p_binding_id and auth_user_id=uid; if not found then raise exception 'licence not found'; end if; if p_action not in ('retrieve_key','rotate_key','unlock_all','unlock_component') then raise exception 'unsupported customer licence action'; end if; if p_action='unlock_component' and (p_component_key is null or coalesce((b.components->>p_component_key)::boolean,false)=false) then raise exception 'component is not enabled on this licence'; end if; if b.api_source='website' then if p_action='retrieve_key' then return public.customer_retrieve_website_key(b.id); elsif p_action='rotate_key' then k:='OFS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4))||'-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,4)); update public.license_bindings set license_key_hash=encode(digest(k,'sha256'),'hex'),license_key_last4=right(k,4),updated_at=now() where id=b.id; delete from public.license_installations where binding_id=b.id; perform public.bump_license_revision(); return jsonb_build_object('ok',true,'status','applied','license_key',k); elsif p_action='unlock_all' then delete from public.license_installations where binding_id=b.id; perform public.bump_license_revision(); return jsonb_build_object('ok',true,'status','applied'); else delete from public.license_installations where binding_id=b.id and component_key=p_component_key; perform public.bump_license_revision(); return jsonb_build_object('ok',true,'status','applied','component',p_component_key); end if; end if; if b.license_id is null then raise exception 'licence is still provisioning'; end if; if exists(select 1 from public.license_controller_requests r where r.binding_id=b.id and r.action=p_action and coalesce(r.component_key,'')=coalesce(p_component_key,'') and r.status in ('queued','running')) then raise exception 'this licence action is already queued'; end if; queue_action:=case p_action when 'rotate_key' then 'rotate' when 'unlock_all' then 'unlock' when 'unlock_component' then 'unlock' else 'retrieve_key' end; insert into public.license_controller_requests(auth_user_id,binding_id,action,component_key,reason,status,payload) values(uid,b.id,p_action,p_component_key,p_reason,'queued',jsonb_build_object('license_id',b.license_id,'components',b.components)) returning id into req; insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source,payload) values(b.id,uid,b.license_id,queue_action,p_reason,'customer_portal',jsonb_build_object('request_id',req,'component',p_component_key,'customer_action',p_action)); return jsonb_build_object('ok',true,'request_id',req,'status','queued'); end $function$\n\nCREATE OR REPLACE FUNCTION public.request_order_cancellation(p_order_id uuid, p_reason text, p_timing text DEFAULT 'immediate'::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\nbegin\n  return public.request_order_cancellation_v2(p_order_id,p_reason,p_timing,null);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.request_order_cancellation_v2(p_order_id uuid, p_reason text, p_timing text DEFAULT 'immediate'::text, p_refund_preference text DEFAULT NULL::text)\n RETURNS uuid\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n  uid uuid:=auth.uid();\n  o public.orders%rowtype;\n  inv public.invoices%rowtype;\n  rid uuid;\n  timing text:=lower(coalesce(p_timing,'immediate'));\n  pref text:=lower(nullif(btrim(coalesce(p_refund_preference,'')),''));\n  sub public.payment_subscriptions%rowtype;\n  sched timestamptz;\n  committed bigint:=0;\n  refundable bigint:=0;\n  refund_required boolean:=false;\n  original_available boolean:=false;\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  if coalesce(btrim(p_reason),'')='' then raise exception 'cancellation reason required'; end if;\n  if timing not in ('immediate','end_of_cycle') then raise exception 'invalid cancellation timing'; end if;\n  if pref is not null and pref not in ('wallet','original') then raise exception 'invalid refund preference'; end if;\n\n  select * into o from public.orders where id=p_order_id and auth_user_id=uid;\n  if not found then raise exception 'order not found'; end if;\n  if o.status in ('cancelled','completed','terminated') then raise exception 'order cannot be cancelled in its current state'; end if;\n  if exists(select 1 from public.order_cancellation_requests where order_id=o.id and status in ('requested','approved_scheduled')) then raise exception 'cancellation already requested'; end if;\n\n  select * into inv from public.invoices where order_id=o.id and auth_user_id=uid order by created_at desc limit 1;\n  if inv.id is not null then\n    select coalesce(sum(amount_cents),0) into committed from public.invoice_refunds\n     where invoice_id=inv.id and status in ('pending','processing','completed','succeeded');\n    refundable:=greatest(0,coalesce(inv.paid_cents,0)-committed);\n    refund_required:=inv.status='partial' and coalesce(inv.paid_cents,0)>0 and refundable>0 and o.activated_at is null;\n  end if;\n\n  if refund_required then\n    if pref is null then raise exception 'choose how the partial payment should be refunded before submitting cancellation'; end if;\n    if timing<>'immediate' then raise exception 'partially paid unactivated orders can only be cancelled immediately'; end if;\n    if pref='original' then\n      select exists(\n        select 1 from public.invoice_payments p\n        left join lateral (\n          select coalesce(sum(r.amount_cents),0) refunded from public.invoice_refunds r\n           where r.payment_id=p.id and r.status in ('pending','processing','completed','succeeded')\n        ) rr on true\n        where p.invoice_id=inv.id and p.status='completed'\n          and p.method in ('account_credit','stripe','paypal') and p.amount_cents>coalesce(rr.refunded,0)\n      ) into original_available;\n      if not original_available then raise exception 'original payment method refund is unavailable; choose OrbitFS Wallet'; end if;\n    end if;\n  else\n    pref:=null;\n  end if;\n\n  select * into sub from public.payment_subscriptions where order_id=o.id and coalesce(status,'') not in ('cancelled','canceled','terminated','ended','inactive') order by created_at desc limit 1;\n  if timing='end_of_cycle' then\n    if sub.id is null or sub.next_charge_at is null then raise exception 'end-of-cycle cancellation is only available for an active subscription'; end if;\n    sched:=sub.next_charge_at;\n  end if;\n\n  insert into public.order_cancellation_requests(\n    order_id,auth_user_id,reason,requested_timing,scheduled_for,\n    refund_preference,refund_status,refund_amount_cents,refund_baseline_cents,refund_processed_cents\n  ) values(\n    o.id,uid,btrim(p_reason),timing,sched,\n    pref,case when refund_required then 'awaiting_approval' else 'not_required' end,\n    case when refund_required then refundable else 0 end,\n    case when refund_required then committed else 0 end,0\n  ) returning id into rid;\n\n  update public.orders set metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(\n    'cancellation_status','requested','cancellation_timing',timing,'cancellation_requested_at',now(),\n    'scheduled_termination_at',sched,'cancellation_refund_preference',pref\n  ),updated_at=now() where id=o.id;\n  return rid;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.reserve_order_item_stock()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare p public.products%rowtype; begin select * into p from public.products where id=new.product_id for update; if p.track_stock then if not p.allow_backorders and (p.stock_on_hand-p.stock_reserved)<new.quantity then raise exception 'Product is out of stock'; end if; update public.products set stock_reserved=stock_reserved+new.quantity,updated_at=now() where id=p.id; new.stock_reserved:=true; end if; return new; end $function$\n\nCREATE OR REPLACE FUNCTION public.run_billing_enforcement_scan()\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  suspended_count integer := 0;\n  restored_count integer := 0;\n  native_changed integer := 0;\n  auto_suspend boolean := true;\n  grace_days integer := 0;\nbegin\n  if not public.is_admin() then raise exception 'admin required'; end if;\n\n  select coalesce((value #>> '{}')::boolean,true)\n    into auto_suspend\n  from public.app_settings\n  where key='license.auto_suspend_on_overdue_invoice'\n  limit 1;\n\n  select greatest(0,coalesce((value #>> '{}')::integer,0))\n    into grace_days\n  from public.app_settings\n  where key='invoice.suspend_after_days'\n  limit 1;\n\n  if coalesce(auto_suspend,true) then\n    update public.license_bindings b\n       set desired_state='suspended',\n           remote_state=case when b.api_source='website' then 'suspended' else b.remote_state end,\n           suspension_reason='invoice overdue',\n           updated_at=now()\n     where b.desired_state='active'\n       and b.archived_at is null\n       and exists (\n         select 1\n           from public.invoices i\n          where i.status in ('unpaid','partial','overdue')\n            and i.due_at is not null\n            and i.due_at + make_interval(days => grace_days) < now()\n            and (\n              (b.order_item_id is not null and exists (\n                select 1 from public.order_items oi\n                 where oi.id=b.order_item_id and oi.order_id=i.order_id\n              ))\n              or\n              (b.order_item_id is null and i.auth_user_id=b.auth_user_id and exists (\n                select 1 from public.order_items oi\n                 where oi.order_id=i.order_id\n                   and oi.license_product_key is not null\n                   and (b.license_product_key is null or oi.license_product_key=b.license_product_key)\n              ))\n            )\n       );\n    get diagnostics suspended_count=row_count;\n\n    insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source)\n    select b.id,b.auth_user_id,b.license_id,'block','invoice overdue','billing_scan'\n      from public.license_bindings b\n     where b.api_source<>'website'\n       and b.desired_state='suspended'\n       and b.suspension_reason='invoice overdue'\n       and not exists (\n         select 1 from public.license_enforcement_queue q\n          where q.binding_id=b.id and q.action='block' and q.state in ('queued','running')\n       );\n  end if;\n\n  update public.license_bindings b\n     set desired_state='active',\n         remote_state=case when b.api_source='website' then 'active' else b.remote_state end,\n         suspension_reason=null,\n         updated_at=now()\n   where b.desired_state='suspended'\n     and b.suspension_reason='invoice overdue'\n     and (\n       not coalesce(auto_suspend,true)\n       or not exists (\n         select 1\n           from public.invoices i\n          where i.status in ('unpaid','partial','overdue')\n            and i.due_at is not null\n            and i.due_at + make_interval(days => grace_days) < now()\n            and (\n              (b.order_item_id is not null and exists (\n                select 1 from public.order_items oi\n                 where oi.id=b.order_item_id and oi.order_id=i.order_id\n              ))\n              or\n              (b.order_item_id is null and i.auth_user_id=b.auth_user_id and exists (\n                select 1 from public.order_items oi\n                 where oi.order_id=i.order_id\n                   and oi.license_product_key is not null\n                   and (b.license_product_key is null or oi.license_product_key=b.license_product_key)\n              ))\n            )\n       )\n     )\n     and exists (\n       select 1 from public.user_profiles p\n        where p.id=b.auth_user_id and p.status='active' and p.banned_at is null\n     );\n  get diagnostics restored_count=row_count;\n\n  insert into public.license_enforcement_queue(binding_id,auth_user_id,license_id,action,reason,source)\n  select b.id,b.auth_user_id,b.license_id,'unblock','billing restored','billing_scan'\n    from public.license_bindings b\n   where b.api_source<>'website'\n     and b.desired_state='active'\n     and b.suspension_reason is null\n     and b.updated_at>now()-interval '1 minute'\n     and not exists (\n       select 1 from public.license_enforcement_queue q\n        where q.binding_id=b.id and q.action='unblock' and q.state in ('queued','running')\n     );\n\n  select count(*) into native_changed\n    from public.license_bindings\n   where api_source='website' and updated_at>now()-interval '1 minute';\n  if native_changed>0 then perform public.bump_license_revision(); end if;\n\n  return jsonb_build_object(\n    'suspended',suspended_count,\n    'restored',restored_count,\n    'native_changed',native_changed,\n    'auto_suspend',coalesce(auto_suspend,true),\n    'grace_days',grace_days\n  );\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.service_delete_orbitfs_installation(p_installation_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private', 'vault'\nAS $function$\ndeclare\n  refs jsonb;\n  sid text;\n  removed boolean:=false;\nbegin\n  if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n  select secret_refs into refs from private.orbitfs_installation_secret_refs where installation_id=p_installation_id;\n  delete from public.orbitfs_installations where id=p_installation_id;\n  removed:=found;\n  if not removed then return false; end if;\n  for sid in select value from jsonb_each_text(coalesce(refs,'{}'::jsonb)) loop\n    begin delete from vault.secrets where id=sid::uuid; exception when others then null; end;\n  end loop;\n  return true;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.service_gateway_runtime_config(p_gateway_code text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare out jsonb;\nbegin\n  if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n  select jsonb_build_object('code',g.code,'provider',g.provider,'enabled',g.enabled,'currencies',g.currencies,'environment',coalesce(s.environment,'sandbox'),'setup_status',coalesce(s.setup_status,'not_configured'),'webhook_config',coalesce(s.webhook_config,'{}'::jsonb),'metadata',coalesce(s.metadata,'{}'::jsonb)) into out\n  from public.payment_gateways g left join public.payment_gateway_setups s on s.gateway_id=g.id where g.code=p_gateway_code;\n  return out;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.service_gateway_secret(p_gateway_code text, p_key text)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'vault'\nAS $function$\ndeclare sid uuid; val text;\nbegin\n  if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n  select nullif(s.secret_refs->>p_key,'')::uuid into sid from public.payment_gateway_setups s join public.payment_gateways g on g.id=s.gateway_id where g.code=p_gateway_code;\n  if sid is null then return null; end if;\n  select decrypted_secret into val from vault.decrypted_secrets where id=sid;\n  return val;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.service_orbitfs_installation_secret(p_installation_id uuid, p_key text)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private', 'vault'\nAS $function$\ndeclare sid uuid; val text;\nbegin\n  if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n  select nullif(secret_refs->>p_key,'')::uuid into sid from private.orbitfs_installation_secret_refs where installation_id=p_installation_id;\n  if sid is null then return null; end if;\n  select decrypted_secret into val from vault.decrypted_secrets where id=sid;\n  return val;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.service_orbitfs_provider_secret(p_user_id uuid, p_provider text, p_key text)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private', 'vault'\nAS $function$\ndeclare sid uuid; val text;\nbegin\n  if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n  select case when p_key='access_token' then s.access_token_secret_id when p_key='refresh_token' then s.refresh_token_secret_id else null end into sid\n  from private.orbitfs_provider_connection_secrets s join public.orbitfs_provider_connections c on c.id=s.connection_id\n  where c.auth_user_id=p_user_id and c.provider=p_provider;\n  if sid is null then return null; end if;\n  select decrypted_secret into val from vault.decrypted_secrets where id=sid;\n  return val;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.service_orbitfs_release_secret(p_key text)\n RETURNS text\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private', 'vault'\nAS $function$\ndeclare sid uuid; val text;\nbegin\n  if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n  select secret_id into sid from private.orbitfs_release_secret_refs where key=p_key;\n  if sid is null then return null; end if;\n  select decrypted_secret into val from vault.decrypted_secrets where id=sid;\n  return val;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.service_store_orbitfs_installation_secret(p_installation_id uuid, p_key text, p_value text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private', 'vault'\nAS $function$\ndeclare refs jsonb; sid uuid;\nbegin\n  if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n  if p_key not in ('db_secret','db_password') then raise exception 'unsupported installation secret'; end if;\n  if nullif(p_value,'') is null then raise exception 'secret value required'; end if;\n  insert into private.orbitfs_installation_secret_refs(installation_id) values(p_installation_id) on conflict(installation_id) do nothing;\n  select secret_refs into refs from private.orbitfs_installation_secret_refs where installation_id=p_installation_id for update;\n  sid:=nullif(refs->>p_key,'')::uuid;\n  if sid is null then sid:=vault.create_secret(p_value,'orbitfs_install_'||p_installation_id::text||'_'||p_key,'OrbitFS installation secret',null);\n  else perform vault.update_secret(sid,p_value,'orbitfs_install_'||p_installation_id::text||'_'||p_key,'OrbitFS installation secret',null); end if;\n  update private.orbitfs_installation_secret_refs set secret_refs=jsonb_set(coalesce(secret_refs,'{}'::jsonb),array[p_key],to_jsonb(sid::text),true),updated_at=now() where installation_id=p_installation_id;\n  return true;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.service_upsert_orbitfs_provider_connection(p_user_id uuid, p_provider text, p_access_token text, p_refresh_token text, p_expires_at timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb)\n RETURNS orbitfs_provider_connections\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'private', 'vault'\nAS $function$\ndeclare cid uuid; a uuid; r uuid; outrow public.orbitfs_provider_connections%rowtype;\nbegin\n  if auth.role()<>'service_role' then raise exception 'service role required'; end if;\n  if p_provider not in ('supabase','vercel') then raise exception 'unsupported provider'; end if;\n  insert into public.orbitfs_provider_connections(auth_user_id,provider,status,provider_account_id,provider_account_name,team_id,scopes,token_expires_at,metadata,refreshed_at,updated_at)\n  values(p_user_id,p_provider,'connected',p_metadata->>'provider_account_id',p_metadata->>'provider_account_name',p_metadata->>'team_id',coalesce(p_metadata->'scopes','[]'::jsonb),p_expires_at,coalesce(p_metadata,'{}'::jsonb),now(),now())\n  on conflict(auth_user_id,provider) do update set status='connected',provider_account_id=excluded.provider_account_id,provider_account_name=excluded.provider_account_name,team_id=excluded.team_id,scopes=excluded.scopes,token_expires_at=excluded.token_expires_at,metadata=excluded.metadata,refreshed_at=now(),last_error=null,updated_at=now()\n  returning * into outrow; cid:=outrow.id;\n  insert into private.orbitfs_provider_connection_secrets(connection_id) values(cid) on conflict(connection_id) do nothing;\n  select access_token_secret_id,refresh_token_secret_id into a,r from private.orbitfs_provider_connection_secrets where connection_id=cid for update;\n  if nullif(p_access_token,'') is not null then\n    if a is null then a:=vault.create_secret(p_access_token,'orbitfs_'||p_provider||'_'||cid::text||'_access','OrbitFS provider access token',null);\n    else perform vault.update_secret(a,p_access_token,'orbitfs_'||p_provider||'_'||cid::text||'_access','OrbitFS provider access token',null); end if;\n  end if;\n  if nullif(p_refresh_token,'') is not null then\n    if r is null then r:=vault.create_secret(p_refresh_token,'orbitfs_'||p_provider||'_'||cid::text||'_refresh','OrbitFS provider refresh token',null);\n    else perform vault.update_secret(r,p_refresh_token,'orbitfs_'||p_provider||'_'||cid::text||'_refresh','OrbitFS provider refresh token',null); end if;\n  end if;\n  update private.orbitfs_provider_connection_secrets set access_token_secret_id=a,refresh_token_secret_id=r,updated_at=now() where connection_id=cid;\n  return outrow;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.set_cart_coupon(p_code text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); cid uuid; begin\n cid:=public.get_or_create_cart();\n update public.shopping_carts set coupon_code=nullif(upper(btrim(coalesce(p_code,''))),''),updated_at=now() where id=cid and auth_user_id=uid;\n return jsonb_build_object('ok',true);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.settle_invoice_stock()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare r record; begin if new.status='paid' and old.status is distinct from 'paid' then for r in select oi.id,oi.product_id,oi.quantity,oi.stock_reserved from public.order_items oi where oi.order_id=new.order_id loop if r.stock_reserved then update public.products set stock_reserved=greatest(0,stock_reserved-r.quantity),stock_on_hand=greatest(0,stock_on_hand-r.quantity),updated_at=now() where id=r.product_id; update public.order_items set stock_reserved=false where id=r.id; end if; end loop; elsif new.status in ('void','cancelled') and old.status not in ('void','cancelled','paid') then for r in select oi.id,oi.product_id,oi.quantity,oi.stock_reserved from public.order_items oi where oi.order_id=new.order_id loop if r.stock_reserved then update public.products set stock_reserved=greatest(0,stock_reserved-r.quantity),updated_at=now() where id=r.product_id; update public.order_items set stock_reserved=false where id=r.id; end if; end loop; end if; return new; end $function$\n\nCREATE OR REPLACE FUNCTION public.staff_note_customer_can_view(p_entity_type text, p_entity_id uuid, p_user uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select case p_entity_type when 'customer' then p_entity_id=p_user when 'order' then exists(select 1 from public.orders where id=p_entity_id and auth_user_id=p_user) when 'invoice' then exists(select 1 from public.invoices where id=p_entity_id and auth_user_id=p_user) when 'support_ticket' then exists(select 1 from public.support_tickets where id=p_entity_id and user_id=p_user) else false end $function$\n\nCREATE OR REPLACE FUNCTION public.staff_note_permission(p_entity_type text, p_action text)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare k text; begin if public.current_role()='superadmin' then return true; end if; k:=case p_entity_type when 'customer' then 'notes.customer' when 'order' then 'notes.order' when 'invoice' then 'notes.invoice' when 'support_ticket' then 'notes.support' else null end; if k is null then return false; end if; return public.has_permission(k||'.'||p_action); end $function$\n\nCREATE OR REPLACE FUNCTION public.start_invoice_payment(p_invoice_id uuid, p_gateway_code text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  uid uuid:=auth.uid();\n  inv public.invoices%rowtype;\n  g public.payment_gateways%rowtype;\n  due bigint;\n  att uuid;\n  res jsonb;\n  applied bigint;\n  remaining bigint;\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  if not public.account_can_order(uid) then raise exception 'account is restricted; contact support via ticket or support@orbitfs.cc'; end if;\n\n  select * into inv from public.invoices where id=p_invoice_id and auth_user_id=uid for update;\n  if not found then raise exception 'invoice not found'; end if;\n  if inv.status='paid' then return jsonb_build_object('status','succeeded','invoice_id',inv.id,'already_paid',true); end if;\n  if inv.status in ('refunded','void','cancelled') then raise exception 'invoice is closed and cannot accept payment'; end if;\n\n  due:=greatest(0,inv.total_cents-inv.paid_cents);\n  if due<=0 then raise exception 'nothing due'; end if;\n\n  select * into g from public.payment_gateways where code=p_gateway_code and enabled=true;\n  if not found then raise exception 'payment method is unavailable'; end if;\n  if not inv.currency=any(g.currencies) then raise exception 'payment method does not support %',inv.currency; end if;\n\n  if g.provider='account_credit' then\n    res:=public.apply_wallet_credit_to_invoice(inv.id,null);\n    applied:=coalesce((res->>'applied_cents')::bigint,0);\n    remaining:=coalesce((res->>'remaining_cents')::bigint,0);\n    insert into public.payment_attempts(invoice_id,auth_user_id,gateway_id,gateway_code,amount_cents,currency,status,metadata,completed_at,updated_at)\n    values(inv.id,uid,g.id,g.code,applied,inv.currency,'succeeded',jsonb_build_object('wallet_result',res,'partial_invoice_payment',remaining>0),now(),now()) returning id into att;\n    if remaining>0 then\n      return jsonb_build_object('attempt_id',att,'status','pending','invoice_id',inv.id,'order_id',inv.order_id,'applied_cents',applied,'remaining_cents',remaining,'wallet_balance_cents',coalesce((res->>'wallet_balance_cents')::bigint,0),'instructions',format('Wallet credit applied. %s cents remain to pay with another payment method.',remaining));\n    end if;\n    return jsonb_build_object('attempt_id',att,'status','succeeded','invoice_id',inv.id,'order_id',inv.order_id,'applied_cents',applied,'remaining_cents',0,'wallet_balance_cents',coalesce((res->>'wallet_balance_cents')::bigint,0));\n  end if;\n\n  insert into public.payment_attempts(invoice_id,auth_user_id,gateway_id,gateway_code,amount_cents,currency,status)\n  values(inv.id,uid,g.id,g.code,due,inv.currency,case when g.provider='manual' then 'pending' else 'action_required' end) returning id into att;\n  if g.provider='manual' then\n    return jsonb_build_object('attempt_id',att,'status','pending','gateway',g.code,'instructions',g.instructions);\n  elsif g.provider in ('stripe','paypal') then\n    return jsonb_build_object('attempt_id',att,'status','action_required','gateway',g.code,'invoice_id',inv.id,'order_id',inv.order_id);\n  else\n    update public.payment_attempts set status='failed',failure_code='unsupported_gateway',failure_message='Unsupported payment gateway provider.',updated_at=now() where id=att;\n    raise exception 'Unsupported gateway provider';\n  end if;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.start_wallet_recharge_payment(p_recharge_id uuid, p_gateway_code text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  uid uuid:=auth.uid();\n  r public.wallet_recharges%rowtype;\n  g public.payment_gateways%rowtype;\n  a public.payment_attempts%rowtype;\n  att uuid;\nbegin\n  if uid is null then raise exception 'authentication required'; end if;\n  select * into r from public.wallet_recharges where id=p_recharge_id and auth_user_id=uid for update;\n  if not found then raise exception 'wallet recharge not found'; end if;\n  if r.status='succeeded' then return jsonb_build_object('status','succeeded','already_paid',true,'recharge_id',r.id,'receipt_number',r.receipt_number); end if;\n  select * into g from public.payment_gateways where code=p_gateway_code and enabled=true and provider in ('stripe','paypal');\n  if not found then raise exception 'payment method is unavailable for Wallet recharge'; end if;\n  if not r.currency=any(g.currencies) then raise exception 'payment method does not support %',r.currency; end if;\n\n  select * into a from public.payment_attempts\n   where wallet_recharge_id=r.id and gateway_code=g.code and status in ('created','pending','action_required','processing')\n   order by created_at desc limit 1;\n  if found then\n    update public.wallet_recharges set gateway_code=g.code,status='action_required',updated_at=now() where id=r.id;\n    return jsonb_build_object('attempt_id',a.id,'status',a.status,'gateway',g.code,'recharge_id',r.id,'receipt_number',r.receipt_number,'reused',true);\n  end if;\n\n  update public.payment_attempts\n    set status='cancelled',failure_code='gateway_changed',failure_message='Customer selected a different Wallet recharge gateway.',updated_at=now()\n    where wallet_recharge_id=r.id and status in ('created','pending','action_required','processing');\n\n  insert into public.payment_attempts(invoice_id,wallet_recharge_id,auth_user_id,gateway_id,gateway_code,amount_cents,currency,status,metadata)\n  values(null,r.id,uid,g.id,g.code,r.amount_cents,r.currency,'action_required',jsonb_build_object('wallet_recharge',true,'receipt_number',r.receipt_number))\n  returning id into att;\n  update public.wallet_recharges set gateway_code=g.code,status='action_required',updated_at=now() where id=r.id;\n  return jsonb_build_object('attempt_id',att,'status','action_required','gateway',g.code,'recharge_id',r.id,'receipt_number',r.receipt_number,'reused',false);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.superadmin_delete_customer(p_user_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare v_role text; v_email text; begin\n if public.current_role()<>'superadmin' then raise exception 'superadmin required'; end if;\n if p_user_id=auth.uid() then raise exception 'cannot delete your own account'; end if;\n select role into v_role from public.user_profiles where id=p_user_id;\n if v_role is null then raise exception 'customer not found'; end if;\n if v_role in ('support','admin','superadmin') then raise exception 'staff accounts cannot be deleted from customer deletion'; end if;\n select email into v_email from auth.users where id=p_user_id;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n values(auth.uid(),'customer.hard_delete','customer',p_user_id::text,jsonb_build_object('email',v_email,'reason',p_reason));\n\n update public.support_tickets set related_order_id=null where user_id=p_user_id;\n delete from public.support_tickets where user_id=p_user_id;\n update public.license_bindings set order_id=null,order_item_id=null where auth_user_id=p_user_id;\n delete from public.orders where auth_user_id=p_user_id;\n delete from public.invoices where auth_user_id=p_user_id;\n delete from public.customers where auth_user_id=p_user_id;\n delete from public.staff_notes where created_by=p_user_id;\n delete from auth.users where id=p_user_id;\n return jsonb_build_object('ok',true,'email',v_email);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.superadmin_delete_invoice(p_invoice_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_num text; v_order uuid; begin\n if public.current_role()<>'superadmin' then raise exception 'superadmin required'; end if;\n select invoice_number,order_id into v_num,v_order from public.invoices where id=p_invoice_id for update;\n if v_num is null then raise exception 'invoice not found'; end if;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n values(auth.uid(),'invoice.hard_delete','invoice',p_invoice_id::text,jsonb_build_object('invoice_number',v_num,'order_id',v_order,'reason',p_reason));\n delete from public.invoices where id=p_invoice_id;\n return jsonb_build_object('ok',true,'invoice_number',v_num,'order_id',v_order);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.superadmin_delete_order(p_order_id uuid, p_reason text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare v_num text; v_user uuid; begin\n if public.current_role()<>'superadmin' then raise exception 'superadmin required'; end if;\n select order_number,auth_user_id into v_num,v_user from public.orders where id=p_order_id for update;\n if v_num is null then raise exception 'order not found'; end if;\n insert into public.admin_audit_log(actor_id,action,target_type,target_id,detail)\n values(auth.uid(),'order.hard_delete','order',p_order_id::text,jsonb_build_object('order_number',v_num,'customer_user_id',v_user,'reason',p_reason));\n update public.support_tickets set related_order_id=null where related_order_id=p_order_id;\n update public.payment_subscriptions set order_id=null where order_id=p_order_id;\n update public.gift_deliveries set recipient_order_id=null where recipient_order_id=p_order_id;\n update public.license_bindings set order_id=null,order_item_id=null,updated_at=now() where order_id=p_order_id;\n delete from public.orders where id=p_order_id;\n return jsonb_build_object('ok',true,'order_number',v_num,'customer_user_id',v_user);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.support_emit_system_message(p_ticket uuid, p_event text, p_detail jsonb DEFAULT '{}'::jsonb)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare t public.support_message_templates%rowtype; txt text; owner_id uuid;\nbegin\n select user_id into owner_id from public.support_tickets where id=p_ticket;\n if owner_id is null then raise exception 'ticket not found'; end if;\n if auth.uid() is not null and auth.uid()<>owner_id and public.support_staff_rank(auth.uid())>0 and not public.support_staff_can_access_ticket(p_ticket,auth.uid()) then raise exception 'ticket is outside your support department or escalation level'; end if;\n select * into t from public.support_message_templates where event_key=p_event and enabled=true; if not found then return; end if;\n txt:=t.body; txt:=replace(txt,'{{staff}}',coalesce(p_detail->>'staff','Support staff')); txt:=replace(txt,'{{department}}',coalesce(p_detail->>'department','Support')); txt:=replace(txt,'{{priority}}',coalesce(p_detail->>'priority','normal')); txt:=replace(txt,'{{status}}',coalesce(p_detail->>'status','updated')); txt:=replace(txt,'{{escalation}}',coalesce(p_detail->>'escalation','Support')); txt:=replace(txt,'{{reason}}',coalesce(p_detail->>'reason',''));\n insert into public.support_ticket_messages(ticket_id,author_user_id,author_role,body,internal_note,attachments) values(p_ticket,null,'system',txt,not t.customer_visible,'[]'::jsonb);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.support_guard_staff_message_insert()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare owner_id uuid;\nbegin\n if auth.uid() is null then return new; end if;\n select user_id into owner_id from public.support_tickets where id=new.ticket_id;\n if owner_id=auth.uid() then return new; end if;\n if public.support_staff_rank(auth.uid())>0 and not public.support_staff_can_access_ticket(new.ticket_id,auth.uid()) then\n   raise exception 'ticket is outside your support department or escalation level';\n end if;\n return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.support_guard_ticket_staff_update()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n if auth.uid() is not null and auth.uid()<>old.user_id and public.support_staff_rank(auth.uid())>0 and not public.support_staff_can_access_ticket(old.id,auth.uid()) then\n   raise exception 'ticket is outside your support department or escalation level';\n end if;\n return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.support_staff_can_access_ticket(p_ticket_id uuid, p_user_id uuid DEFAULT auth.uid())\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare r integer; t public.support_tickets%rowtype; min_rank integer;\nbegin\n if p_user_id is null then return false; end if;\n r:=public.support_staff_rank(p_user_id); if r<=0 then return false; end if;\n select * into t from public.support_tickets where id=p_ticket_id; if not found then return false; end if;\n select min_support_rank into min_rank from public.support_departments where id=t.department_id;\n if r<coalesce(min_rank,1) then return false; end if;\n if r>=3 then return true; end if;\n if t.escalation_level>greatest(r-1,0) then return false; end if;\n if t.claim_required and r>=2 then return true; end if;\n return t.assigned_to=p_user_id or public.support_user_has_department(p_user_id,t.department_id);\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.support_staff_departments()\n RETURNS jsonb\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare uid uuid:=auth.uid(); r integer; out jsonb;\nbegin\n if uid is null or not public.has_permission('support.manage') then raise exception 'permission denied: support.manage'; end if;\n r:=public.support_staff_rank(uid);\n select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'name',d.name,'description',d.description,'slug',d.slug,'email',d.email,'allow_direct_create',d.allow_direct_create,'min_support_rank',d.min_support_rank,'escalation_department_id',d.escalation_department_id) order by d.sort_order,d.name),'[]'::jsonb) into out\n from public.support_departments d where d.enabled=true and r>=d.min_support_rank and (r>=3 or exists(select 1 from public.support_department_staff ds where ds.department_id=d.id and ds.user_id=uid));\n return out;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.support_staff_rank(p_user_id uuid DEFAULT auth.uid())\n RETURNS integer\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select coalesce(max(case sg.slug when 'superadmin' then 4 when 'admin' then 3 when 'senior-support' then 2 when 'support' then 1 else 0 end),0)\n  from public.staff_members sm left join public.staff_member_groups smg on smg.user_id=sm.user_id left join public.staff_groups sg on sg.id=smg.group_id\n  where sm.user_id=p_user_id and sm.status='active'\n$function$\n\nCREATE OR REPLACE FUNCTION public.support_staff_rank_label(p_rank integer)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\nAS $function$\n  select case p_rank\n    when 4 then 'Superadmin'\n    when 3 then 'Admin'\n    when 2 then 'Senior Support'\n    when 1 then 'Support'\n    else 'No support role'\n  end\n$function$\n\nCREATE OR REPLACE FUNCTION public.support_ticket_billing_context(p_ticket_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare t public.support_tickets%rowtype; o jsonb; items jsonb; invs jsonb;\nbegin\n if not public.has_permission('support.manage') then raise exception 'permission denied: support.manage'; end if;\n if not public.support_staff_can_access_ticket(p_ticket_id,auth.uid()) then raise exception 'ticket is outside your support department or escalation level'; end if;\n select * into t from public.support_tickets where id=p_ticket_id; if not found then raise exception 'ticket not found'; end if;\n if t.related_order_id is not null then select to_jsonb(x) into o from (select id,order_number,status,payment_status,fulfillment_status,total_cents,currency,created_at from public.orders where id=t.related_order_id and auth_user_id=t.user_id) x; select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into items from (select id,product_id,product_name,license_product_key,quantity,unit_price_cents,total_cents,service_status,billing_period,next_due_at from public.order_items where order_id=t.related_order_id order by product_name) x; else o=null; items='[]'::jsonb; end if;\n select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into invs from (select id,invoice_number,order_id,status,subtotal_cents,discount_cents,total_cents,paid_cents,currency,due_at,created_at from public.invoices where auth_user_id=t.user_id and (t.related_order_id is null or order_id=t.related_order_id) order by created_at desc limit 30) x;\n return jsonb_build_object('order',o,'items',items,'invoices',invs);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.support_ticket_mail_context(p_ticket_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'auth'\nAS $function$\ndeclare\n t public.support_tickets%rowtype;\n v_email text;\n v_name text;\n v_department_email text;\n v_department_name text;\n v_guest boolean:=false;\nbegin\n select * into t from public.support_tickets where id=p_ticket_id;\n if not found then raise exception 'ticket not found'; end if;\n if t.user_id is not null and auth.uid()=t.user_id then\n   null;\n else\n   if not (public.has_permission('support.manage') or public.has_permission('support.reply') or public.has_permission('support.close')) then raise exception 'permission denied'; end if;\n   if not public.support_staff_can_access_ticket(p_ticket_id,auth.uid()) then raise exception 'ticket is outside your support department or escalation level'; end if;\n end if;\n if t.user_id is not null then\n   select u.email,coalesce(nullif(p.display_name,''),nullif(concat_ws(' ',p.first_name,p.last_name),''),'Customer')\n   into v_email,v_name from auth.users u left join public.user_profiles p on p.id=u.id where u.id=t.user_id;\n else\n   v_email=nullif(trim(t.metadata->>'contact_email'),'');\n   v_name=coalesce(nullif(trim(t.metadata->>'contact_name'),''),'Guest');\n   v_guest=true;\n end if;\n select d.email,d.name into v_department_email,v_department_name from public.support_departments d where d.id=t.department_id;\n return jsonb_build_object('email',v_email,'customer_name',v_name,'ticket_id',t.id,'ticket_number',t.ticket_number,'subject',t.subject,'status',t.status,'user_id',t.user_id,'department_id',t.department_id,'department_name',v_department_name,'department_email',v_department_email,'is_guest',v_guest);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.support_ticket_routing_snapshot(p_ticket_id uuid)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare t public.support_tickets%rowtype; actor_rank integer; deps jsonb; people jsonb;\nbegin\n if not public.has_permission('support.manage') then raise exception 'permission denied: support.manage'; end if;\n select * into t from public.support_tickets where id=p_ticket_id; if not found then raise exception 'ticket not found'; end if;\n actor_rank:=public.support_staff_rank(auth.uid());\n if actor_rank<3 and t.assigned_to is distinct from auth.uid() and not public.support_user_has_department(auth.uid(),t.department_id) then raise exception 'ticket is outside your support departments'; end if;\n if t.escalation_level>greatest(actor_rank-1,0) then raise exception 'ticket is escalated above your support level'; end if;\n select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'name',d.name,'description',d.description,'enabled',d.enabled,'email',d.email,'allow_direct_create',d.allow_direct_create,'min_support_rank',d.min_support_rank) order by d.sort_order,d.name),'[]'::jsonb) into deps\n from public.support_departments d where d.enabled=true and actor_rank>=d.min_support_rank and (actor_rank>=3 or public.support_user_has_department(auth.uid(),d.id));\n select coalesce(jsonb_agg(jsonb_build_object('user_id',sm.user_id,'display_name',coalesce(up.display_name,trim(concat_ws(' ',up.first_name,up.last_name)),sm.user_id::text),'title',sm.title,'rank',public.support_staff_rank(sm.user_id),'rank_label',public.support_staff_rank_label(public.support_staff_rank(sm.user_id))) order by public.support_staff_rank(sm.user_id) desc,coalesce(up.display_name,sm.user_id::text)),'[]'::jsonb) into people\n from public.staff_members sm left join public.user_profiles up on up.id=sm.user_id\n where sm.status='active' and public.support_staff_rank(sm.user_id)>t.escalation_level and (public.support_staff_rank(sm.user_id)>=3 or public.support_user_has_department(sm.user_id,t.department_id));\n return jsonb_build_object('ticket',jsonb_build_object('id',t.id,'department_id',t.department_id,'assigned_to',t.assigned_to,'claim_required',t.claim_required,'escalation_level',t.escalation_level,'escalation_reason',t.escalation_reason,'escalated_at',t.escalated_at,'escalated_by',t.escalated_by),'actor_rank',actor_rank,'actor_rank_label',public.support_staff_rank_label(actor_rank),'departments',deps,'staff',people);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.support_user_has_department(p_user_id uuid, p_department_id uuid)\n RETURNS boolean\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare r integer; min_rank integer;\nbegin\n  r:=public.support_staff_rank(p_user_id);\n  select min_support_rank into min_rank from public.support_departments where id=p_department_id and enabled=true;\n  if min_rank is null or r<min_rank then return false; end if;\n  if r>=3 then return true; end if;\n  return exists(select 1 from public.support_department_staff ds where ds.user_id=p_user_id and ds.department_id=p_department_id);\nend $function$\n\nCREATE OR REPLACE FUNCTION public.sync_customer_from_profile()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n update public.customers\n set\n   name=coalesce(nullif(new.display_name,''),nullif(trim(concat_ws(' ',new.first_name,new.last_name)),''),name),\n   display_name=new.display_name,\n   first_name=new.first_name,\n   last_name=new.last_name,\n   company_name=new.company_name,\n   phone=new.phone,\n   address_line1=new.address_line1,\n   address_line2=new.address_line2,\n   city=new.city,\n   state_region=new.state_region,\n   postal_code=new.postal_code,\n   country_code=new.country_code,\n   timezone=new.timezone,\n   currency=new.currency,\n   language=new.language,\n   status=case\n     when new.banned_at is not null and (new.ban_expires_at is null or new.ban_expires_at>now()) then 'banned'\n     else coalesce(new.status,'active')\n   end,\n   customer_number=coalesce(new.customer_number,customer_number),\n   email_verified_at=coalesce(new.email_verified_at,email_verified_at),\n   updated_at=now()\n where auth_user_id=new.id;\n return new;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.sync_customer_number_to_profile()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nbegin\n  if new.auth_user_id is not null then update public.user_profiles set customer_number=new.customer_number where id=new.auth_user_id; end if;\n  return new;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.sync_invoice_refund_status(p_invoice_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  inv public.invoices%rowtype;\n  successful_refunded bigint:=0;\n  pending_refunded bigint:=0;\n  next_status text;\nbegin\n  select * into inv from public.invoices where id=p_invoice_id for update;\n  if not found then return; end if;\n\n  select\n    coalesce(sum(amount_cents) filter (where status in ('completed','succeeded')),0),\n    coalesce(sum(amount_cents) filter (where status in ('pending','processing')),0)\n  into successful_refunded,pending_refunded\n  from public.invoice_refunds\n  where invoice_id=inv.id;\n\n  next_status:=inv.status;\n  if coalesce(inv.paid_cents,0)>0 and successful_refunded>=coalesce(inv.paid_cents,0) then\n    next_status:='refunded';\n  elsif inv.status='refunded' and successful_refunded<coalesce(inv.paid_cents,0) then\n    next_status:=case\n      when coalesce(inv.paid_cents,0)>=coalesce(inv.total_cents,0) and coalesce(inv.total_cents,0)>0 then 'paid'\n      when coalesce(inv.paid_cents,0)>0 then 'partial'\n      when inv.due_at is not null and inv.due_at<now() then 'overdue'\n      else 'unpaid'\n    end;\n  end if;\n\n  update public.invoices\n  set status=next_status,\n      metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object(\n        'refunded_cents',successful_refunded,\n        'refund_pending_cents',pending_refunded,\n        'fully_refunded',coalesce(inv.paid_cents,0)>0 and successful_refunded>=coalesce(inv.paid_cents,0),\n        'refunded_at',case when coalesce(inv.paid_cents,0)>0 and successful_refunded>=coalesce(inv.paid_cents,0) then coalesce(metadata->'refunded_at',to_jsonb(now())) else 'null'::jsonb end\n      ),\n      updated_at=now()\n  where id=inv.id;\nend\n$function$\n\nCREATE OR REPLACE FUNCTION public.sync_order_service_status(p_order_id uuid)\n RETURNS void\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ declare s text; begin select case when count(*)=0 then 'pending' when bool_and(coalesce(service_status,'pending')='active') then 'active' when bool_and(coalesce(service_status,'pending')='terminated') then 'terminated' when bool_or(coalesce(service_status,'pending')='suspended') then 'suspended' when bool_or(coalesce(service_status,'pending')='blocked') then 'blocked' when bool_or(coalesce(service_status,'pending')='pending_approval') then 'pending_approval' else 'pending' end into s from public.order_items where order_id=p_order_id; update public.orders set service_status=s,updated_at=now() where id=p_order_id; end $function$\n\nCREATE OR REPLACE FUNCTION public.trg_sync_order_service_status()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ begin perform public.sync_order_service_status(coalesce(new.order_id,old.order_id)); return coalesce(new,old); end $function$\n\nCREATE OR REPLACE FUNCTION public.user_has_active_product(p_user uuid, p_product uuid)\n RETURNS boolean\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select exists(\n    select 1 from public.download_entitlements de\n    join public.orders o on o.id=de.order_id\n    where de.auth_user_id=p_user and de.product_id=p_product and de.status='active'\n      and o.status not in ('terminated','cancelled')\n  );\n$function$\n\nCREATE OR REPLACE FUNCTION public.wallet_credit(p_user_id uuid, p_amount_cents bigint, p_reason text, p_reference_type text DEFAULT 'wallet'::text, p_reference_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_created_by uuid DEFAULT NULL::uuid)\n RETURNS bigint\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare newbal bigint;\nbegin\n if p_amount_cents<=0 then raise exception 'wallet credit must be positive'; end if;\n insert into public.account_balances(user_id,available_cents,reserved_cents,lifetime_credit_cents,lifetime_debit_cents)\n values(p_user_id,p_amount_cents,0,p_amount_cents,0)\n on conflict(user_id) do update set available_cents=public.account_balances.available_cents+excluded.available_cents,lifetime_credit_cents=public.account_balances.lifetime_credit_cents+excluded.lifetime_credit_cents,updated_at=now()\n returning available_cents into newbal;\n insert into public.credit_ledger(user_id,direction,amount_cents,balance_after_cents,reason,reference_type,reference_id,created_by,metadata)\n values(p_user_id,'credit',p_amount_cents,newbal,p_reason,p_reference_type,p_reference_id,coalesce(p_created_by,auth.uid()),coalesce(p_metadata,'{}'::jsonb));\n return newbal;\nend $function$\n\nCREATE OR REPLACE FUNCTION public.wallet_recharge_gateways()\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select coalesce(jsonb_agg(jsonb_build_object(\n    'code',code,\n    'name',display_name,\n    'description',description,\n    'provider',provider,\n    'fee_fixed_cents',fee_fixed_cents,\n    'fee_percent',fee_percent,\n    'public_config',public_config\n  ) order by sort_order,display_name),'[]'::jsonb)\n  from public.payment_gateways\n  where enabled=true\n    and provider in ('stripe','paypal')\n    and 'AUD'=any(currencies)\n$function$\n\nCREATE OR REPLACE FUNCTION public.website_license_register(p_license_key text, p_installation_id text, p_components text[] DEFAULT NULL::text[], p_device_name text DEFAULT NULL::text, p_platform text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public', 'extensions'\nAS $function$ select public.website_license_validate(p_license_key,p_installation_id,p_components,true,p_device_name,p_platform,p_app_version) $function$\n\nCREATE OR REPLACE FUNCTION public.website_license_revision()\n RETURNS jsonb\n LANGUAGE sql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$ select jsonb_build_object('revision',revision,'updated_at',updated_at) from public.license_revision where id=1 $function$\n\nCREATE OR REPLACE FUNCTION public.website_license_runtime_settings()\n RETURNS jsonb\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  select jsonb_build_object(\n    'api_name', api_name,\n    'enabled', enabled,\n    'mode', mode,\n    'issuer', issuer,\n    'audience', audience,\n    'entitlement_ttl_seconds', entitlement_ttl_seconds,\n    'grace_seconds', grace_seconds,\n    'allow_offline_grace', allow_offline_grace\n  )\n  from public.license_api_settings\n  order by updated_at desc\n  limit 1\n$function$\n\nCREATE OR REPLACE FUNCTION public.website_license_validate(p_license_key text, p_installation_id text, p_components text[] DEFAULT NULL::text[], p_activate boolean DEFAULT false, p_device_name text DEFAULT NULL::text, p_platform text DEFAULT NULL::text, p_app_version text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'extensions'\nAS $function$\ndeclare\n  b public.license_bindings%rowtype;\n  requested text[];\n  requested_key text;\n  canonical_key text;\n  enabled boolean;\n  inst public.license_installations%rowtype;\n  result_components jsonb := '{}'::jsonb;\n  overall_valid boolean := true;\n  reason text := null;\n  rev bigint;\n  component_state text;\n  binding_installation_id text := null;\nbegin\n  if coalesce(trim(p_license_key),'')='' or coalesce(trim(p_installation_id),'')='' then\n    raise exception 'license key and installation id are required';\n  end if;\n\n  select * into b\n  from public.license_bindings\n  where license_key_hash=encode(digest(trim(p_license_key),'sha256'),'hex')\n    and api_source='website'\n    and archived_at is null\n  limit 1;\n\n  if not found then\n    insert into public.license_validation_log(result,reason,installation_id)\n    values('denied','license_not_found',p_installation_id);\n    return jsonb_build_object('valid',false,'reason','license_not_found');\n  end if;\n\n  if b.expires_at is not null and b.expires_at<=now() then\n    overall_valid:=false;\n    reason:='expired';\n  elsif b.desired_state<>'active' then\n    overall_valid:=false;\n    reason:=b.desired_state;\n  end if;\n\n  select li.installation_id into binding_installation_id\n  from public.license_installations li\n  where li.binding_id=b.id\n  order by li.registered_at asc, li.id asc\n  limit 1;\n\n  requested:=coalesce(\n    p_components,\n    array(select jsonb_object_keys(coalesce(b.components,'{}'::jsonb)))\n  );\n\n  foreach requested_key in array requested loop\n    canonical_key:=public.canonical_license_component_key(requested_key);\n    enabled:=coalesce((b.components->>canonical_key)::boolean,false);\n\n    select * into inst\n    from public.license_installations\n    where binding_id=b.id and component_key=canonical_key\n    limit 1;\n\n    if overall_valid and enabled and p_activate then\n      if binding_installation_id is null then\n        binding_installation_id:=p_installation_id;\n      end if;\n\n      if binding_installation_id=p_installation_id and inst.id is null then\n        insert into public.license_installations(\n          binding_id,component_key,installation_id,device_name,platform,app_version,status,registered_at,last_seen_at,locked_at,metadata\n        ) values(\n          b.id,canonical_key,p_installation_id,p_device_name,p_platform,p_app_version,'active',now(),now(),now(),'{}'::jsonb\n        ) returning * into inst;\n      elsif inst.id is not null and inst.installation_id=p_installation_id then\n        update public.license_installations\n        set last_seen_at=now(),\n            device_name=coalesce(p_device_name,device_name),\n            platform=coalesce(p_platform,platform),\n            app_version=coalesce(p_app_version,app_version),\n            status='active',\n            locked_at=coalesce(locked_at,now())\n        where id=inst.id\n        returning * into inst;\n      end if;\n    elsif inst.id is not null and inst.installation_id=p_installation_id then\n      update public.license_installations\n      set last_seen_at=now(),\n          device_name=coalesce(p_device_name,device_name),\n          platform=coalesce(p_platform,platform),\n          app_version=coalesce(p_app_version,app_version)\n      where id=inst.id\n      returning * into inst;\n    end if;\n\n    component_state:=case\n      when not enabled then 'blocked'\n      when not overall_valid then coalesce(reason,'blocked')\n      when binding_installation_id is not null and binding_installation_id<>p_installation_id then 'blocked'\n      when inst.id is null then 'active'\n      when inst.installation_id=p_installation_id then 'locked'\n      else 'blocked'\n    end;\n\n    result_components:=result_components||jsonb_build_object(\n      requested_key,\n      jsonb_build_object(\n        'state',component_state,\n        'allowed',overall_valid and enabled and inst.id is not null and inst.installation_id=p_installation_id,\n        'lockedToThisInstallation',inst.id is not null and inst.installation_id=p_installation_id,\n        'reason',case\n          when not overall_valid then reason\n          when not enabled then 'not_included'\n          when binding_installation_id is not null and binding_installation_id<>p_installation_id then 'locked_to_another_installation'\n          when inst.id is null then 'activation_required'\n          else null\n        end\n      )\n    );\n  end loop;\n\n  select revision into rev from public.license_revision where id=1;\n\n  insert into public.license_validation_log(binding_id,license_id,installation_id,result,reason)\n  values(\n    b.id,b.license_id,p_installation_id,\n    case\n      when not overall_valid then 'denied'\n      when binding_installation_id is not null and binding_installation_id<>p_installation_id then 'denied'\n      else 'allowed'\n    end,\n    case\n      when not overall_valid then reason\n      when binding_installation_id is not null and binding_installation_id<>p_installation_id then 'locked_to_another_installation'\n      else null\n    end\n  );\n\n  return jsonb_build_object(\n    'valid',overall_valid and (binding_installation_id is null or binding_installation_id=p_installation_id),\n    'reason',case\n      when not overall_valid then reason\n      when binding_installation_id is not null and binding_installation_id<>p_installation_id then 'locked_to_another_installation'\n      else null\n    end,\n    'licenceId',coalesce(b.license_id,b.id::text),\n    'bindingId',b.id,\n    'installationId',p_installation_id,\n    'lockedInstallationId',binding_installation_id,\n    'components',result_components,\n    'revision',coalesce(rev,1)\n  );\nend;\n$function$\n\n\nCREATE TRIGGER trg_assign_customer_number BEFORE INSERT ON customers FOR EACH ROW EXECUTE FUNCTION assign_customer_number();\nCREATE TRIGGER trg_mail_customer_created AFTER INSERT ON customers FOR EACH ROW EXECUTE FUNCTION mail_event_customer_trigger();\nCREATE TRIGGER trg_sync_customer_number_to_profile AFTER INSERT OR UPDATE OF customer_number, auth_user_id ON customers FOR EACH ROW EXECUTE FUNCTION sync_customer_number_to_profile();\nCREATE TRIGGER trg_invoice_refund_status AFTER INSERT OR DELETE OR UPDATE OF status, amount_cents ON invoice_refunds FOR EACH ROW EXECUTE FUNCTION invoice_refund_status_trigger();\nCREATE TRIGGER trg_mail_event_invoice_refund AFTER INSERT OR UPDATE OF status ON invoice_refunds FOR EACH ROW EXECUTE FUNCTION mail_event_refund_trigger();\nCREATE TRIGGER trg_default_invoice_policy BEFORE INSERT ON invoices FOR EACH ROW EXECUTE FUNCTION default_invoice_policy();\nCREATE TRIGGER trg_invoice_paid_entitlements AFTER UPDATE OF status ON invoices FOR EACH ROW EXECUTE FUNCTION invoice_paid_entitlement_trigger();\nCREATE TRIGGER trg_mail_invoice_insert AFTER INSERT ON invoices FOR EACH ROW EXECUTE FUNCTION mail_event_invoice_trigger();\nCREATE TRIGGER trg_mail_invoice_update AFTER UPDATE ON invoices FOR EACH ROW EXECUTE FUNCTION mail_event_invoice_trigger();\nCREATE TRIGGER trg_settle_invoice_stock AFTER UPDATE OF status ON invoices FOR EACH ROW EXECUTE FUNCTION settle_invoice_stock();\nCREATE TRIGGER orbitfs_installations_touch BEFORE UPDATE ON orbitfs_installations FOR EACH ROW EXECUTE FUNCTION orbitfs_installations_touch_updated_at();\nCREATE TRIGGER trg_mail_cancellation AFTER INSERT OR UPDATE ON order_cancellation_requests FOR EACH ROW EXECUTE FUNCTION mail_event_cancellation_trigger();\nCREATE TRIGGER trg_reserve_order_item_stock BEFORE INSERT ON order_items FOR EACH ROW EXECUTE FUNCTION reserve_order_item_stock();\nCREATE TRIGGER trg_sync_order_service_status AFTER INSERT OR DELETE OR UPDATE OF service_status ON order_items FOR EACH ROW EXECUTE FUNCTION trg_sync_order_service_status();\nCREATE TRIGGER trg_mail_order_insert AFTER INSERT ON orders FOR EACH ROW EXECUTE FUNCTION mail_event_order_trigger();\nCREATE TRIGGER trg_mail_order_update AFTER UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION mail_event_order_trigger();\nCREATE TRIGGER trg_enforce_staff_group_invariants BEFORE UPDATE ON staff_groups FOR EACH ROW EXECUTE FUNCTION enforce_staff_group_invariants();\nCREATE TRIGGER notify_support_message_created_trg AFTER INSERT ON support_ticket_messages FOR EACH ROW EXECUTE FUNCTION notify_support_message_created();\nCREATE TRIGGER trg_mail_support_message AFTER INSERT ON support_ticket_messages FOR EACH ROW EXECUTE FUNCTION mail_event_support_message_trigger();\nCREATE TRIGGER trg_support_guard_staff_message BEFORE INSERT ON support_ticket_messages FOR EACH ROW EXECUTE FUNCTION support_guard_staff_message_insert();\nCREATE TRIGGER notify_support_ticket_created_trg AFTER INSERT ON support_tickets FOR EACH ROW EXECUTE FUNCTION notify_support_ticket_created();\nCREATE TRIGGER notify_support_ticket_updated_trg AFTER UPDATE ON support_tickets FOR EACH ROW EXECUTE FUNCTION notify_support_ticket_updated();\nCREATE TRIGGER trg_mail_support_ticket AFTER INSERT OR UPDATE ON support_tickets FOR EACH ROW EXECUTE FUNCTION mail_event_support_ticket_trigger();\nCREATE TRIGGER trg_support_guard_staff_update BEFORE UPDATE ON support_tickets FOR EACH ROW EXECUTE FUNCTION support_guard_ticket_staff_update();\nCREATE TRIGGER protect_user_profile_role BEFORE UPDATE ON user_profiles FOR EACH ROW EXECUTE FUNCTION protect_role_change();\nCREATE TRIGGER trg_account_enforcement AFTER UPDATE OF status, banned_at ON user_profiles FOR EACH ROW EXECUTE FUNCTION apply_account_enforcement();\nCREATE TRIGGER user_profiles_sync_customer AFTER INSERT OR UPDATE OF display_name, first_name, last_name, status, banned_at, ban_expires_at, email_verified_at ON user_profiles FOR EACH ROW EXECUTE FUNCTION sync_customer_from_profile();\n\nALTER TABLE public.account_activity ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.account_balances ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.admin_audit_log ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.app_settings ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.coupon_redemptions ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.credit_ledger ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.custom_field_definitions ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.custom_field_values ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.customer_credentials ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.customer_sessions ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.download_entitlements ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.email_verification_tokens ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.enforcement_settings ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.gift_deliveries ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.guest_support_access_attempts ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.invoice_items ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.invoice_payments ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.invoice_refunds ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_api_clients ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_api_settings ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_bindings ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_controller_requests ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_enforcement_queue ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_fulfillments ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_installations ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_key_delivery ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_revision ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.license_validation_log ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_account_access ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_accounts ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_automations ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_delivery_log ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_event_outbox ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_message_state ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_messages ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_settings ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_spam_events ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_spam_rules ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.mail_templates ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.news_posts ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.option_sets ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orbitfs_deployment_events ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orbitfs_installation_releases ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orbitfs_installations ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orbitfs_oauth_states ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orbitfs_provider_connections ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orbitfs_release_bundles ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orbitfs_release_system_settings ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orbitfs_themes ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.order_cancellation_requests ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.password_reset_tokens ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.payment_attempts ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.payment_events ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.payment_gateway_setups ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.payment_gateways ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.payment_subscriptions ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.product_artifacts ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.product_dependencies ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.product_options ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.products ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.role_definitions ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.role_permissions ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.shopping_cart_items ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.shopping_carts ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.staff_groups ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.staff_member_groups ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.staff_members ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.staff_note_revisions ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.staff_notes ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_attachments ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_department_staff ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_departments ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_kb_articles ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_kb_categories ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_message_templates ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_premade_messages ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_ticket_events ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_ticket_messages ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.user_preferences ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.user_profiles ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.wallet_recharges ENABLE ROW LEVEL SECURITY;\\nALTER TABLE public.webhook_events ENABLE ROW LEVEL SECURITY;\\nCREATE POLICY "account activity own insert" ON public.account_activity AS permissive TO {public} FOR INSERT WITH CHECK ((auth_user_id = auth.uid()));\nCREATE POLICY "staff activity read" ON public.account_activity AS permissive TO {authenticated} FOR SELECT USING ((has_permission('customers.view'::text) OR has_permission('audit.view'::text)));\nCREATE POLICY balances_self_read ON public.account_balances AS permissive TO {authenticated} FOR SELECT USING ((user_id = auth.uid()));\nCREATE POLICY staff_balances_read ON public.account_balances AS permissive TO {authenticated} FOR SELECT USING (app_private.is_staff());\nCREATE POLICY "staff read audit" ON public.admin_audit_log AS permissive TO {public} FOR SELECT USING (is_admin());\nCREATE POLICY "read permitted app settings" ON public.app_settings AS permissive TO {public} FOR SELECT USING (((public_read = true) OR\nCASE\n    WHEN (category = ANY (ARRAY['billing'::text, 'invoice'::text])) THEN has_permission('settings.billing'::text)\n    WHEN (category = ANY (ARRAY['identity'::text, 'customization'::text])) THEN has_permission('settings.identity'::text)\n    ELSE has_permission('settings.general'::text)\nEND));\nCREATE POLICY "staff manage permitted settings" ON public.app_settings AS permissive TO {public} FOR ALL USING (\nCASE\n    WHEN ((category = 'billing'::text) OR (category = 'invoice'::text)) THEN has_permission('settings.billing'::text)\n    WHEN ((category = 'identity'::text) OR (category = 'customization'::text)) THEN has_permission('settings.identity'::text)\n    ELSE has_permission('settings.general'::text)\nEND) WITH CHECK (\nCASE\n    WHEN ((category = 'billing'::text) OR (category = 'invoice'::text)) THEN has_permission('settings.billing'::text)\n    WHEN ((category = 'identity'::text) OR (category = 'customization'::text)) THEN has_permission('settings.identity'::text)\n    ELSE has_permission('settings.general'::text)\nEND);\nCREATE POLICY "active coupons readable" ON public.coupons AS permissive TO {public} FOR SELECT USING ((active = true));\nCREATE POLICY "admin manage coupons" ON public.coupons AS permissive TO {public} FOR ALL USING (("current_role"() = ANY (ARRAY['admin'::text, 'superadmin'::text]))) WITH CHECK (("current_role"() = ANY (ARRAY['admin'::text, 'superadmin'::text])));\nCREATE POLICY credit_ledger_owner_read ON public.credit_ledger AS permissive TO {auth